/* ---- Sieges ---- */
const SG_TIERS = [
  { id:1, name:"Bandit Raid",     icon:"🐀", waves:10, hpMult:1,   spd:1.00, rep:600,   credits:8000,   power:120 },
  { id:2, name:"Warband Assault", icon:"🗡️", waves:12, hpMult:3,   spd:1.05, rep:1800,  credits:30000,  power:600 },
  { id:3, name:"The Iron Horde",  icon:"🛡️", waves:14, hpMult:12,  spd:1.10, rep:5000,  credits:110000, power:1500 },
  { id:4, name:"The Long Winter", icon:"❄️", waves:16, hpMult:22,  spd:1.15, rep:14000, credits:400000, power:3800 },
  { id:5, name:"Endless Siege",   icon:"♾️", waves:Infinity, hpMult:4, spd:1.08, rep:0, credits:0, power:2500, endless:true },
];
function sgTier(id){ return SG_TIERS.find(t=>t.id===id); }
function sgTierUnlocked(t){
  if(t.id === 1) return true;
  const prev = t.endless ? 4 : t.id-1;
  return !!(state.siege && state.siege.cleared && state.siege.cleared[prev]);
}
function sgCastleMaxHp(){
  const s = computeEmpireStats();
  return Math.round(320 + s.castleDefense*1.4 + s.wallDefense*1.8);
}
function sgStartSupply(){
  const treasury = (state.empire && state.empire.castle && state.empire.castle.treasury) || 0;
  return 260 + treasury*12;
}

let sg = null, sgRaf = null, sgLastTs = 0, sgTabActive = false;
let sgSeed = 1;
function sgRand(){ sgSeed = (sgSeed*1103515245 + 12345) & 0x7fffffff; return sgSeed/0x7fffffff; }

function sgNewBattle(tierId){
  const t = sgTier(tierId), maxHp = sgCastleMaxHp();
  return {
    tier:t, wave:0, phase:"prep", countdown:5,
    hp:maxHp, maxHp, supply:sgStartSupply(), speed:1,
    towers:[], enemies:[], shots:[], fx:[], nums:[], queue:[], fires:[], barricades:[],
    leaks:0, kills:0, endlessRep:0, endlessCred:0,
    cd:{}, sel:null, build:null, aiming:null, hover:null,
    streak:0, streakT:0, bestStreak:0, shake:0,
    log:[], time:0, spawnTimer:0, mod:null, nextMod:null, result:null,
  };
}

function sgLog(msg, cls){
  if(!sg) return;
  sg.log.unshift({ msg, cls:cls||"" });
  if(sg.log.length > 40) sg.log.pop();
  const el = document.getElementById("sgLog");
  if(el) el.innerHTML = sg.log.map(l=>`<div class="${l.cls}">${l.msg}</div>`).join("");
}
function sgShake(n){ if(sg) sg.shake = Math.min(14, sg.shake + n); }
function sgNum(x, y, txt, color, big){ if(sg) sg.nums.push({ x:Math.max(24, Math.min(SG_W-24, x)), y:Math.max(18, y), txt, color, big:!!big, t:0 }); }

/* ---- Wave building ---- */
function sgWaveHpMult(w){ return Math.pow(1.175, w-1) * sg.tier.hpMult; }
function sgPickMod(w){
  if(w < 3 || w % 5 === 0) return null;
  if(sgRand() < 0.42) return null;
  return SG_MODS[Math.floor(sgRand()*SG_MODS.length)];
}
function sgBuildWave(w, mod){
  const q = [];
  const push = (type, n, gap)=>{ for(let i=0;i<n;i++) q.push({ type, gap }); };
  const cm = mod ? (mod.count||1) : 1;
  const boss = (w % 5 === 0);
  push("scav", Math.round((4 + w*1.2)*cm), 0.5);
  if(w >= 2) push("raider", Math.round((3 + w*0.9)*cm), 0.62);
  if(w >= 5) push("splitter", Math.round((1 + w*0.22)*cm), 0.9);
  if(w >= 4) push("harrier", Math.round((2 + w*0.5)*cm), 0.45);
  if(w >= 5) push("brute", Math.round((1 + w*0.4)*cm), 0.95);
  const veiled = SG_TIERS.indexOf(sg.tier) >= 1 || sg.tier.endless;   // no Wraiths in the first siege
  if(veiled && w >= 6) push("wraith", Math.round((1 + w*0.45)*cm), 0.55);
  if(w >= 7) push("shaman", Math.round((1 + w*0.2)*cm), 0.9);
  if(w >= 10 && w % 5 !== 0 && (SG_TIERS.indexOf(sg.tier) >= 1 || sg.tier.endless)) push("jugg", Math.round(1 + (w-10)*0.25), 1.6);
  if(boss) push("warlord", Math.max(1, Math.floor(w/10)), 2.0);
  const out = [];
  while(q.length) out.push(q.splice(Math.floor(sgRand()*q.length), 1)[0]);
  return out;
}
function sgWavePreview(w){
  const mod = sg.nextMod;
  const q = sgBuildWave(w, mod);
  const counts = {};
  q.forEach(e=>counts[e.type] = (counts[e.type]||0)+1);
  return { count:q.length, counts, mod, boss:(w%5===0) };
}

function sgSpawn(type){
  const base = SG_ENEMIES[type], mod = sg.mod;
  const mult = sgWaveHpMult(sg.wave) * (mod ? mod.hp : 1);
  const hp = Math.round(base.hp * mult);
  const fly = !!base.fly || !!(mod && mod.allFly);
  const routeIdx = Math.floor(sgRand()*SG_ROUTES.length);
  const e = {
    type, def:base, hp, maxHp:hp, d:0, routeIdx,
    speed: base.speed * sg.tier.spd * (mod?mod.speed:1) * (0.94 + sgRand()*0.12),
    armor: Math.round(base.armor * Math.pow(1.12, sg.wave-1) * (mod && mod.armor ? mod.armor : 1) * (sg.tier.hpMult>5?1.4:1)),
    bountyMul: mod ? (mod.bounty||1) : 1,
    regen: mod && mod.regen ? mod.regen : 0,
    slowUntil:0, slowMul:1, burnUntil:0, burnDps:0, healCd:0, flash:0, fly,
    stunUntil:0, ghost:!!base.ghost,
    off:(sgRand()-0.5)*11, walk:sgRand()*6.28, blocked:null, hitT:0,
  };
  sg.enemies.push(e);
}

/* Everyone follows the road now — fliers included. Wings just mean they sail
   over barricades and burning ground, not that they take a secret shortcut. */
function sgEnemyPos(e){
  const p = sgPosOn(SG_ROUTES[e.routeIdx], e.d);
  return { x:p.x, y:p.y + e.off };
}
function sgEnemyLen(e){ return SG_ROUTES[e.routeIdx].total; }
function sgProgress(e){ return e.d / sgEnemyLen(e); }

/* Auras from neighbouring support towers, recomputed only when the board changes. */
function sgRecalcAuras(){
  if(!sg) return;
  for(const t of sg.towers){ t.auraDmg = 1; t.auraRate = 1; t.auraSight = false; }
  for(const s of sg.towers){
    const rs = sgResolve(s);
    if(!rs.aura && !rs.hasteAura) continue;
    const sc = sgCC(s.c, s.r);
    for(const t of sg.towers){
      if(t === s) continue;
      const tc = sgCC(t.c, t.r);
      if(Math.hypot(sc.x-tc.x, sc.y-tc.y) <= rs.range){
        t.auraDmg += rs.aura || 0;
        t.auraRate += rs.hasteAura || 0;
        if(s.key === "signal") t.auraSight = true;   // the beacon unveils Wraiths for its neighbours
      }
    }
  }
}

function sgHurt(e, dmg, pierce, crit){
  const eff = pierce ? dmg : Math.max(dmg*0.15, dmg - e.armor);
  e.hp -= eff;
  e.flash = 0.13;
  const p = sgEnemyPos(e);
  if(eff >= 1) sgNum(p.x + (sgRand()-0.5)*10, p.y-12, Math.round(eff).toLocaleString(), crit ? "#ffd35c" : "#ffffff", crit);
  if(e.hp <= 0) sgKill(e);
}
function sgKill(e){
  const i = sg.enemies.indexOf(e);
  if(i < 0) return;
  sg.enemies.splice(i, 1);
  if(e.def.splits && !e.fly){
    for(let k=0;k<2;k++){
      const kid = SG_ENEMIES.scav;
      const hp = Math.round(kid.hp * sgWaveHpMult(sg.wave) * 0.8);
      sg.enemies.push({ type:"scav", def:kid, hp, maxHp:hp, d:Math.max(0, e.d - k*9), routeIdx:e.routeIdx,
        speed: kid.speed * sg.tier.spd * (1 + sgRand()*0.15), armor:0, bountyMul:0.5, regen:0,
        slowUntil:0, slowMul:1, burnUntil:0, burnDps:0, healCd:0, flash:0.1, fly:false,
        stunUntil:0, ghost:false, off:(sgRand()-0.5)*11, walk:sgRand()*6.28, blocked:null, hitT:0 });
    }
  }
  sg.kills++;
  sg.streak++; sg.streakT = 2.2;
  sg.bestStreak = Math.max(sg.bestStreak, sg.streak);
  const streakBonus = 1 + Math.min(0.6, Math.floor(sg.streak/5)*0.1);
  const bounty = Math.round((e.def.bounty + Math.pow(e.maxHp, 0.55)*1.1) * e.bountyMul * streakBonus);
  sg.supply += bounty;
  const p = sgEnemyPos(e);
  for(let k=0;k<(e.def.boss?18:7);k++){
    sg.fx.push({ kind:"bit", x:p.x, y:p.y, vx:(sgRand()-0.5)*150, vy:-40-sgRand()*130,
      t:0, life:0.5+sgRand()*0.3, color:sgRand()<0.5 ? e.def.body : e.def.trim, r:1.6+sgRand()*2.2 });
  }
  sg.fx.push({ kind:"coin", x:p.x, y:p.y, t:0, life:0.62, txt:"+"+bounty });
  if(e.def.boss){ sgShake(9); sgLog(`<b>${e.def.name}</b> cut down. <span class="good">+${bounty} supply</span>`, "good"); }
}

function sgBarricadeAhead(e){
  if(e.fly) return null;
  let best = null;
  for(const b of sg.barricades){
    const bd = b.dBy[e.routeIdx];
    if(bd === undefined) continue;
    if(bd > e.d && bd - e.d <= 15 && (!best || bd < best.d)) best = { b, d:bd };
  }
  return best;
}

function sgTick(dt){
  sg.time += dt;
  sg.shake = Math.max(0, sg.shake - dt*26);
  for(const k in sg.cd) sg.cd[k] = Math.max(0, sg.cd[k] - dt);
  if(sg.streakT > 0){ sg.streakT -= dt; if(sg.streakT <= 0) sg.streak = 0; }

  if(sg.phase === "prep"){
    sg.countdown -= dt;
    if(sg.countdown <= 0) sgStartWave();
  }
  if(sg.phase === "wave"){
    sg.spawnTimer -= dt;
    if(sg.queue.length && sg.spawnTimer <= 0){
      const next = sg.queue.shift();
      sgSpawn(next.type);
      sg.spawnTimer = next.gap / Math.max(1, sg.tier.spd*0.9);
    }
    if(!sg.queue.length && !sg.enemies.length) sgEndWave();
  }

  /* burning ground */
  for(let i=sg.fires.length-1;i>=0;i--){
    const f = sg.fires[i];
    f.t += dt;
    if(f.t >= f.life){ sg.fires.splice(i,1); continue; }
    for(const e of sg.enemies){
      if(e.fly) continue;
      const p = sgEnemyPos(e);
      if(Math.hypot(p.x-f.x, p.y-f.y) <= f.r){
        e.burnUntil = sg.time + 1.1;
        e.burnDps = Math.max(e.burnDps, f.dps);
        if(f.slow){ e.slowUntil = Math.max(e.slowUntil, sg.time + 0.4); e.slowMul = Math.min(e.slowMul, 1-f.slow); }
      }
    }
  }

  /* barricades */
  for(let i=sg.barricades.length-1;i>=0;i--){
    const b = sg.barricades[i];
    b.hitT = Math.max(0, b.hitT - dt);
    if(b.hp <= 0){
      sg.fx.push({ kind:"boom", x:b.x, y:b.y, t:0, life:0.35, r:34, color:"#c9a06a" });
      for(let k=0;k<10;k++) sg.fx.push({ kind:"bit", x:b.x, y:b.y, vx:(sgRand()-0.5)*180, vy:-60-sgRand()*120, t:0, life:0.6, color:"#8a6b45", r:2.4 });
      sg.barricades.splice(i,1);
      sgLog(`A barricade splintered.`, "bad");
    }
  }

  /* enemies */
  for(let i=sg.enemies.length-1;i>=0;i--){
    const e = sg.enemies[i];
    e.flash = Math.max(0, e.flash - dt);
    e.hitT = Math.max(0, e.hitT - dt);
    if(e.regen && e.hp < e.maxHp) e.hp = Math.min(e.maxHp, e.hp + e.maxHp*e.regen*dt);
    if(sg.time < e.burnUntil && e.burnDps > 0){
      e.hp -= e.burnDps*dt;
      if(sgRand() < dt*9){
        const bp = sgEnemyPos(e);
        sg.fx.push({ kind:"ember", x:bp.x+(sgRand()-0.5)*10, y:bp.y, t:0, life:0.42 });
      }
      if(e.hp <= 0){ sgKill(e); continue; }
    }

    const block = sgBarricadeAhead(e);
    if(block){
      e.blocked = block.b;
      e.d = Math.min(e.d, block.d - 15);
      block.b.hp -= e.maxHp*0.30*dt;
      block.b.hitT = 0.12;
      e.hitT = 0.18;
    } else {
      e.blocked = null;
      const stunned = sg.time < e.stunUntil;
      const slowed = sg.time < e.slowUntil;
      const v = stunned ? 0 : e.speed * (slowed ? e.slowMul : 1);
      e.d += v*dt;
      e.walk += v*dt*0.16;
    }

    if(e.def.heals){
      e.healCd -= dt;
      if(e.healCd <= 0){
        e.healCd = 1.3;
        const p = sgEnemyPos(e);
        let healed = 0;
        for(const o of sg.enemies){
          if(o === e || o.hp >= o.maxHp) continue;
          const q = sgEnemyPos(o);
          if(Math.hypot(p.x-q.x, p.y-q.y) <= 95){ o.hp = Math.min(o.maxHp, o.hp + o.maxHp*0.05); healed++; }
        }
        if(healed) sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.5, r:95, color:"#3ddc84" });
      }
    }

    if(e.d >= sgEnemyLen(e)){
      const dmg = Math.round(e.def.boss ? e.maxHp*0.22 : 18 + e.maxHp*0.07);
      sg.hp -= dmg; sg.leaks++;
      sg.enemies.splice(i,1);
      sg.streak = 0;
      const cp = sgCC(SG_CASTLE.c, SG_CASTLE.r);
      sg.fx.push({ kind:"ring", x:cp.x, y:cp.y, t:0, life:0.45, r:56, color:"#ff5c5c" });
      sgNum(cp.x, cp.y-34, "−"+dmg.toLocaleString(), "#ff5c5c", true);
      sgShake(10);
      sgLog(`<b>${e.def.name}</b> reached the keep — <span class="bad">−${dmg.toLocaleString()} HP</span>`, "bad");
      if(sg.hp <= 0){ sg.hp = 0; sgFinish(false); return; }
    }
  }

  /* towers */
  for(const t of sg.towers){
    const rs = sgResolve(t);
    if(rs.def.income) continue;                       // counting houses don't shoot
    t.cd -= dt * (t.auraRate || 1);
    t.muzzle = Math.max(0, (t.muzzle||0) - dt);
    if(t.cd > 0) continue;
    const canSeeGhosts = rs.sight || t.key === "signal" || t.auraSight;
    const c = sgCC(t.c, t.r);
    const pool = sg.enemies.filter(e=>{
      if(e.fly && !rs.def.air) return false;
      if(e.ghost && !canSeeGhosts) return false;
      const p = sgEnemyPos(e);
      const dist = Math.hypot(p.x-c.x, p.y-c.y);
      return dist <= rs.range && dist >= rs.minRange;
    });
    if(!pool.length) continue;
    const order = t.order || "first";
    pool.sort((a,b)=>{
      if(order === "last")   return sgProgress(a) - sgProgress(b);
      if(order === "strong") return b.hp - a.hp;
      if(order === "weak")   return a.hp - b.hp;
      return sgProgress(b) - sgProgress(a);
    });
    const picks = pool.slice(0, rs.targets);
    const dmg = rs.dmg * (t.auraDmg || 1);
    t.cd = 1 / rs.rate;
    t.muzzle = 0.1;
    const aim = sgEnemyPos(picks[0]);
    t.face = Math.atan2(aim.y - c.y, aim.x - c.x);

    if(rs.splash > 0){
      const tp = sgEnemyPos(picks[0]);
      sg.shots.push({ kind:"shell", x:c.x, y:c.y-8, tx:tp.x, ty:tp.y, t:0,
        life: Math.max(0.22, Math.hypot(tp.x-c.x, tp.y-c.y)/620),
        dmg, splash:rs.splash, pierce:rs.pierce, color:rs.color, burn:rs.burn, arc:rs.p && rs.p.key==="mortar" ? 60 : 26 });
    } else {
      for(const e of picks){
        const p = sgEnemyPos(e);
        const crit = rs.crit > 0 && sgRand() < rs.crit;
        sg.shots.push({ kind:"arrow", x:c.x, y:c.y-10, tx:p.x, ty:p.y, t:0,
          life: Math.max(0.07, Math.hypot(p.x-c.x, p.y-c.y)/1500), color:rs.color, target:e,
          dmg: dmg*(crit?2:1), pierce:rs.pierce, crit, slow:rs.slow, slowMs:rs.slowMs,
          shred:rs.shred, execute:rs.execute, stunMs:rs.stunMs });
      }
    }
  }

  /* projectiles */
  for(let i=sg.shots.length-1;i>=0;i--){
    const s = sg.shots[i];
    s.t += dt;
    if(s.t < s.life) continue;
    if(s.kind === "shell"){
      sg.fx.push({ kind:"boom", x:s.tx, y:s.ty, t:0, life:0.32, r:s.splash, color:s.color });
      if(s.splash > 60) sgShake(3);
      if(s.burn){
        sg.fires.push({ x:s.tx, y:s.ty, r:s.splash*0.9, t:0, life:3.4, dps:s.dmg*0.34, slow:0.2 });
      }
      for(let j=sg.enemies.length-1;j>=0;j--){
        const e = sg.enemies[j];
        if(e.fly) continue;
        const p = sgEnemyPos(e);
        const dist = Math.hypot(p.x-s.tx, p.y-s.ty);
        if(dist <= s.splash) sgHurt(e, s.dmg*(dist < s.splash*0.45 ? 1 : 0.6), s.pierce, false);
      }
    } else {
      const e = s.target;
      if(e && sg.enemies.includes(e)){
        if(s.slow){ e.slowUntil = sg.time + s.slowMs/1000; e.slowMul = Math.min(e.slowMul, 1-s.slow); }
        if(s.shred) e.armor = Math.max(0, e.armor - s.shred);
        if(s.stunMs) e.stunUntil = Math.max(e.stunUntil, sg.time + s.stunMs/1000);
        if(s.execute && e.hp > 0 && e.hp <= e.maxHp*s.execute && !e.def.boss){
          const ep = sgEnemyPos(e);
          sgNum(ep.x, ep.y-16, "FINISHED", "#ff5c8a", true);
          sgKill(e);
        } else {
          sgHurt(e, s.dmg, s.pierce, s.crit);
        }
      }
    }
    sg.shots.splice(i,1);
  }

  for(let i=sg.fx.length-1;i>=0;i--){
    const f = sg.fx[i];
    f.t += dt;
    if(f.kind === "bit"){ f.x += f.vx*dt; f.y += f.vy*dt; f.vy += 380*dt; }
    if(f.t >= f.life) sg.fx.splice(i,1);
  }
  for(let i=sg.nums.length-1;i>=0;i--){
    sg.nums[i].t += dt;
    if(sg.nums[i].t >= 0.85) sg.nums.splice(i,1);
  }
}

/* BTD-style early call: pile the next wave on top of this one for bonus supply. */
function sgCallEarly(){
  if(!sg || sg.phase !== "wave") return;
  if(!sg.tier.endless && sg.wave >= sg.tier.waves) return;
  const bonus = Math.round(14 + sg.wave*4);
  sg.supply += bonus;
  sg.wave++;
  sg.mod = sg.nextMod;
  sg.nextMod = sgPickMod(sg.wave+1);
  sg.queue = sg.queue.concat(sgBuildWave(sg.wave, sg.mod));
  sgNum(SG_W/2, 40, "+"+bonus+"⚡ EARLY CALL", "#ffd35c", true);
  sgLog(`<b>Wave ${sg.wave}</b> called in early — <span class="good">+${bonus} supply</span>. Brave.`, "good");
  sgRenderHud(); sgRenderPreview();
}
function sgStartWave(){
  sg.wave++;
  sg.mod = sg.nextMod;
  sg.phase = "wave";
  sg.queue = sgBuildWave(sg.wave, sg.mod);
  sg.spawnTimer = 0;
  const boss = sg.wave % 5 === 0;
  sgLog(boss
    ? `<b>Wave ${sg.wave}</b> — a Warlord marches with them.`
    : `<b>Wave ${sg.wave}</b>${sg.mod ? ` · ${sg.mod.icon} ${sg.mod.name}` : ""} — ${sg.queue.length} enemies.`);
}
function sgEndWave(){
  if(sg.tier.endless){
    const rep = Math.round(90 * sg.wave * (1 + sg.wave*0.04));
    const cred = Math.round(1000 * sg.wave * (1 + sg.wave*0.04));
    sg.endlessRep += rep; sg.endlessCred += cred;
    if(!state.siege) state.siege = defaultSiege();
    state.siege.bestEndlessWave = Math.max(state.siege.bestEndlessWave||0, sg.wave);
    sgLog(`Wave ${sg.wave} held. <span class="good">Banked ${rep.toLocaleString()} 🎖️ + ${cred.toLocaleString()} 🪙</span>`, "good");
  }
  if(!sg.tier.endless && sg.wave >= sg.tier.waves){ sgFinish(true); return; }
  const perfect = sg.leaks === sg.leaksAtWaveStart;
  const bonus = 38 + 12*sg.wave + (perfect ? 22 : 0);
  sg.supply += bonus;
  let banked = 0;
  for(const t of sg.towers){
    const rs = sgResolve(t);
    if(rs.income) banked += rs.income;
    if(rs.interest) banked += Math.min(rs.interestCap, Math.round(sg.supply * rs.interest));
  }
  if(banked > 0){
    sg.supply += banked;
    for(const t of sg.towers){
      if(sgTowerDef(t.key).income){ const p = sgCC(t.c,t.r); sg.fx.push({ kind:"coin", x:p.x, y:p.y-18, t:0, life:0.8, txt:"+⚡" }); }
    }
    sgLog(`Your counting houses pay out. <span class="good">+${banked} supply</span>`, "good");
  }
  sg.phase = "prep";
  sg.countdown = 7;
  sg.nextMod = sgPickMod(sg.wave+1);
  sg.leaksAtWaveStart = sg.leaks;
  sgLog(`Wave ${sg.wave} cleared. <span class="good">+${bonus} supply</span>${perfect?" (nothing got through)":""}`, "good");
  sgRenderPreview();
}

/* ---------------- SIEGE: DRAWING ---------------- */
function sgRR(g,x,y,w,h,r){ g.beginPath(); if(g.roundRect) g.roundRect(x,y,w,h,r); else g.rect(x,y,w,h); }

let sgTerrain = null;      // baked painted background, rebuilt per battle
function sgBakeTerrain(){
  const T = SG_MAP.theme;
  const cv = document.createElement("canvas");
  cv.width = SG_W*2; cv.height = SG_H*2;
  const g = cv.getContext("2d");
  g.setTransform(2,0,0,2,0,0);
  const H = sgHash;
  // --- base wash ---
  const grd = g.createLinearGradient(0,0,0,SG_H);
  grd.addColorStop(0,T.gA); grd.addColorStop(0.5,T.gB); grd.addColorStop(1,T.gC);
  g.fillStyle = grd; g.fillRect(0,0,SG_W,SG_H);
  // --- big soft brush daubs: the painted underlayer ---
  for(let i=0;i<170;i++){
    const h1 = H(i,3), h2 = H(i,7), h3 = H(i,11);
    const rg = g.createRadialGradient(h1*SG_W, h2*SG_H, 2, h1*SG_W, h2*SG_H, 26+h3*70);
    const col = h3 > 0.5 ? T.patchL : T.patchD;
    rg.addColorStop(0, col); rg.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = rg;
    g.beginPath(); g.ellipse(h1*SG_W, h2*SG_H, 30+h3*80, 18+h2*50, h1*3, 0, 7); g.fill();
  }
  // --- sun-side light wash (top-left warm light, bottom-right cool shade) ---
  const light = g.createLinearGradient(0,0,SG_W,SG_H);
  light.addColorStop(0,"rgba(255,240,200,.10)");
  light.addColorStop(0.5,"rgba(255,240,200,0)");
  light.addColorStop(1,"rgba(20,25,60,.12)");
  g.fillStyle = light; g.fillRect(0,0,SG_W,SG_H);
  // --- road: soft outer shadow, layered body, painted wear ---
  g.lineCap = "round"; g.lineJoin = "round";
  for(const rt of SG_ROUTES){
    g.strokeStyle = "rgba(0,0,0,.22)"; g.lineWidth = SG_CELL*0.82;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
  }
  for(const rt of SG_ROUTES){
    g.strokeStyle = T.roadD; g.lineWidth = SG_CELL*0.70;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
    g.strokeStyle = T.roadM; g.lineWidth = SG_CELL*0.58;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
    g.strokeStyle = T.roadL; g.lineWidth = SG_CELL*0.44;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
  }
  // sun-lit top edge of the road
  for(const rt of SG_ROUTES){
    g.save(); g.translate(0,-SG_CELL*0.20);
    g.strokeStyle = "rgba(255,245,215,.13)"; g.lineWidth = 3;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
    g.restore();
  }
  // painted wheel-ruts and daubs along the road
  SG_PATH_CELLS.forEach(k=>{
    const [c,r] = k.split(",").map(Number);
    const p = sgCC(c,r);
    for(let i=0;i<6;i++){
      const hx = H(c*9+i, r*5), hy = H(c*3, r*7+i);
      g.fillStyle = hx > 0.55 ? "rgba(255,255,255,.07)" : "rgba(0,0,0,.10)";
      g.beginPath();
      g.ellipse(p.x-14+hx*28, p.y-12+hy*24, 2.5+hx*4, 1.8+hy*2.6, hx*3, 0, 7);
      g.fill();
    }
  });
  // --- hills as painted mounds with cast shadows ---
  for(let c=0;c<SG_COLS;c++) for(let r=0;r<SG_ROWS;r++){
    if(!sgIsHill(c,r) || sgIsPath(c,r)) continue;
    const p = sgCC(c,r);
    g.fillStyle = "rgba(0,0,0,.20)";
    g.beginPath(); g.ellipse(p.x+4, p.y+8, 24, 11, 0, 0, 7); g.fill();
    g.fillStyle = T.hillA;
    g.beginPath(); g.ellipse(p.x, p.y+2, 22, 13, 0, 0, 7); g.fill();
    g.fillStyle = T.hillB;
    g.beginPath(); g.ellipse(p.x-2, p.y-1, 17, 9.5, 0, 0, 7); g.fill();
    g.fillStyle = "rgba(255,255,255,.20)";
    g.beginPath(); g.ellipse(p.x-6, p.y-4, 8, 3.6, -0.4, 0, 7); g.fill();
    g.fillStyle = "rgba(255,255,255,.55)"; g.font = "bold 9px system-ui"; g.textAlign = "center";
    g.fillText("\u25b2", p.x, p.y);
  }
  // --- grass tufts as curved brush strokes ---
  g.lineWidth = 1.2;
  for(let c=0;c<SG_COLS;c++) for(let r=0;r<SG_ROWS;r++){
    if(sgIsPath(c,r) || sgIsHill(c,r)) continue;
    const p = sgCC(c,r);
    for(let k=0;k<3;k++){
      const hx = p.x - 17 + H(c*4+k, r)*34, hy = p.y - 15 + H(c, r*4+k)*30;
      const lean = (H(c+k,r+k)-0.5)*3;
      g.strokeStyle = H(c*2+k,r) > 0.5 ? T.tuft : "rgba(0,0,0,.10)";
      g.beginPath(); g.moveTo(hx, hy);
      g.quadraticCurveTo(hx+lean, hy-3, hx+lean*1.6, hy-5.5); g.stroke();
    }
  }
  // --- theme accents: the hand-painted details ---
  if(SG_MAP.id === "meadow"){
    for(let i=0;i<44;i++){
      const h1 = H(i,23), h2 = H(i,29);
      const fx = h1*SG_W, fy = h2*SG_H;
      const [c1,r1] = [Math.floor(fx/SG_CELL), Math.floor(fy/SG_CELL)];
      if(sgIsPath(c1,r1)) continue;
      const col = ["#e8b4c8","#f5e6a8","#ffffff"][Math.floor(H(i,31)*3)];
      for(let k=0;k<3;k++){
        g.fillStyle = col; g.globalAlpha = 0.75;
        g.beginPath(); g.arc(fx + (H(i+k,5)-0.5)*10, fy + (H(i,7+k)-0.5)*8, 1.4, 0, 7); g.fill();
      }
      g.globalAlpha = 1;
    }
  }
  if(SG_MAP.id === "desert"){
    for(let i=0;i<40;i++){
      const h1 = H(i,23), h2 = H(i,29);
      const fx = h1*SG_W, fy = h2*SG_H;
      const [c1,r1] = [Math.floor(fx/SG_CELL), Math.floor(fy/SG_CELL)];
      if(sgIsPath(c1,r1)) continue;
      if(H(i,31) > 0.5){
        g.fillStyle = "rgba(240,225,195,.5)";
        g.beginPath(); g.ellipse(fx, fy, 2.6+H(i,3)*2.4, 1.8+H(i,5)*1.6, H(i,7)*3, 0, 7); g.fill();
      } else {
        g.strokeStyle = "rgba(90,60,25,.30)"; g.lineWidth = 1;
        g.beginPath(); g.moveTo(fx, fy);
        g.lineTo(fx + 6+H(i,3)*8, fy + (H(i,5)-0.5)*6);
        g.lineTo(fx + 12+H(i,3)*12, fy + (H(i,7)-0.5)*9); g.stroke();
      }
    }
  }
  if(SG_MAP.id === "snow"){
    for(let i=0;i<56;i++){
      const h1 = H(i,23), h2 = H(i,29);
      const fx = h1*SG_W, fy = h2*SG_H;
      g.globalAlpha = 0.35 + H(i,31)*0.5;
      g.strokeStyle = "#ffffff"; g.lineWidth = 1;
      const rr = 1.6 + H(i,3)*1.8;
      g.beginPath(); g.moveTo(fx-rr, fy); g.lineTo(fx+rr, fy); g.stroke();
      g.beginPath(); g.moveTo(fx, fy-rr); g.lineTo(fx, fy+rr); g.stroke();
      g.globalAlpha = 1;
    }
    // wind-blown drift streaks
    g.strokeStyle = "rgba(255,255,255,.12)"; g.lineWidth = 4; g.lineCap = "round";
    for(let i=0;i<14;i++){
      const h1 = H(i,37), h2 = H(i,41);
      g.beginPath(); g.moveTo(h1*SG_W, h2*SG_H);
      g.quadraticCurveTo(h1*SG_W+40, h2*SG_H-6, h1*SG_W+90, h2*SG_H+4); g.stroke();
    }
  }
  if(SG_MAP.id === "ember"){
    for(let i=0;i<22;i++){
      const h1 = H(i,23), h2 = H(i,29);
      let fx = h1*SG_W, fy = h2*SG_H;
      const [c1,r1] = [Math.floor(fx/SG_CELL), Math.floor(fy/SG_CELL)];
      if(sgIsPath(c1,r1)) continue;
      g.strokeStyle = `rgba(255,${120+Math.floor(H(i,31)*60)},60,${0.25+H(i,3)*0.3})`;
      g.lineWidth = 1.4;
      g.beginPath(); g.moveTo(fx, fy);
      for(let k=0;k<3;k++){
        fx += 5 + H(i+k,5)*9; fy += (H(i,7+k)-0.5)*10;
        g.lineTo(fx, fy);
      }
      g.stroke();
      g.globalAlpha = 0.12;
      g.fillStyle = "#ff8a4c";
      g.beginPath(); g.arc(fx-10, fy, 9, 0, 7); g.fill();
      g.globalAlpha = 1;
    }
  }
  // --- canvas grain: tiny paper specks ---
  for(let i=0;i<1400;i++){
    const h1 = H(i,13), h2 = H(i,17);
    g.fillStyle = H(i,19) > 0.5 ? "rgba(255,255,255,.022)" : "rgba(0,0,0,.028)";
    g.fillRect(h1*SG_W, h2*SG_H, 1.3, 1.3);
  }
  // --- soft painted border shading ---
  const vg = g.createRadialGradient(SG_W/2, SG_H/2, SG_H*0.35, SG_W/2, SG_H/2, SG_H*1.02);
  vg.addColorStop(0, "rgba(0,0,0,0)"); vg.addColorStop(1, "rgba(10,8,20,.30)");
  g.fillStyle = vg; g.fillRect(0,0,SG_W,SG_H);
  sgTerrain = cv;
}
function sgDrawGround(g){
  const T = SG_MAP.theme;
  const grd = g.createLinearGradient(0,0,0,SG_H);
  grd.addColorStop(0,T.gA); grd.addColorStop(0.5,T.gB); grd.addColorStop(1,T.gC);
  g.fillStyle = grd; g.fillRect(0,0,SG_W,SG_H);
  // soft terrain variation
  for(let i=0;i<16;i++){
    const h1 = sgHash(i,3), h2 = sgHash(i,7);
    g.fillStyle = h1 > 0.5 ? T.patchL : T.patchD;
    g.beginPath(); g.ellipse(h1*SG_W, h2*SG_H, 55+h1*80, 32+h2*46, h1*3, 0, 7); g.fill();
  }
  // hills as raised mounds
  for(let c=0;c<SG_COLS;c++) for(let r=0;r<SG_ROWS;r++){
    if(!sgIsHill(c,r) || sgIsPath(c,r)) continue;
    const p = sgCC(c,r);
    g.fillStyle = "rgba(0,0,0,.16)";
    g.beginPath(); g.ellipse(p.x, p.y+7, 23, 12, 0, 0, 7); g.fill();
    g.fillStyle = T.hillA;
    g.beginPath(); g.ellipse(p.x, p.y+2, 22, 13, 0, 0, 7); g.fill();
    g.fillStyle = T.hillB;
    g.beginPath(); g.ellipse(p.x, p.y-1, 18, 10, 0, 0, 7); g.fill();
    g.fillStyle = "rgba(255,255,255,.5)"; g.font = "bold 9px system-ui"; g.textAlign = "center";
    g.fillText("\u25b2", p.x, p.y-1);
  }
  // tufts / pebbles / ice glints — quiet per-tile detail
  g.strokeStyle = T.tuft; g.lineWidth = 1.1;
  for(let c=0;c<SG_COLS;c++) for(let r=0;r<SG_ROWS;r++){
    if(sgIsPath(c,r) || sgIsHill(c,r)) continue;
    const p = sgCC(c,r);
    for(let k=0;k<2;k++){
      const hx = p.x - 15 + sgHash(c*4+k, r)*30, hy = p.y - 13 + sgHash(c, r*4+k)*26;
      g.beginPath(); g.moveTo(hx, hy); g.lineTo(hx-1.6, hy-3.4); g.stroke();
      g.beginPath(); g.moveTo(hx, hy); g.lineTo(hx+1.8, hy-3); g.stroke();
    }
  }
}

function sgDrawRoad(g){
  const T = SG_MAP.theme;
  g.lineCap = "round"; g.lineJoin = "round";
  for(const rt of SG_ROUTES){
    g.strokeStyle = T.roadD; g.lineWidth = SG_CELL*0.70;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
    g.strokeStyle = T.roadM; g.lineWidth = SG_CELL*0.58;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
    g.strokeStyle = T.roadL; g.lineWidth = SG_CELL*0.46;
    g.beginPath(); rt.pts.forEach((p,i)=> i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y)); g.stroke();
  }
  // cobbles / cracks
  g.save();
  SG_PATH_CELLS.forEach(k=>{
    const [c,r] = k.split(",").map(Number);
    const p = sgCC(c,r);
    for(let i=0;i<5;i++){
      const hx = sgHash(c*9+i, r*5), hy = sgHash(c*3, r*7+i);
      g.fillStyle = hx > 0.5 ? "rgba(255,255,255,.06)" : "rgba(0,0,0,.11)";
      g.beginPath();
      g.ellipse(p.x-13+hx*26, p.y-11+hy*22, 3+hx*3, 2.4+hy*2.4, hx*3, 0, 7);
      g.fill();
    }
  });
  g.restore();
  // travel arrows
  g.strokeStyle = "rgba(255,255,255,.16)"; g.lineWidth = 2.5;
  for(const rt of SG_ROUTES){
    const drift = (sg.time*24) % 50;
    for(let d = drift; d < rt.total; d += 50){
      const a = sgPosOn(rt,d), b = sgPosOn(rt, Math.min(rt.total, d+10));
      const ang = Math.atan2(b.y-a.y, b.x-a.x);
      g.beginPath();
      g.moveTo(a.x - Math.cos(ang-0.6)*7, a.y - Math.sin(ang-0.6)*7);
      g.lineTo(a.x, a.y);
      g.lineTo(a.x - Math.cos(ang+0.6)*7, a.y - Math.sin(ang+0.6)*7);
      g.stroke();
    }
  }
}

function sgDrawDecor(g){
  for(const d of SG_DECOR){
    const p = sgCC(d.c,d.r), h = sgHash(d.c,d.r);
    g.fillStyle = "rgba(0,0,0,.28)";
    g.beginPath(); g.ellipse(p.x, p.y+13, 14, 5, 0, 0, 7); g.fill();
    if(d.t === "tree"){
      g.fillStyle = "#5a4028"; g.fillRect(p.x-3, p.y-2, 6, 15);
      const lay = [[0,-16,17],[0,-25,13],[0,-33,9]];
      for(let i=0;i<lay.length;i++){
        g.fillStyle = ["#2f5c30","#3a6d38","#468040"][i];
        g.beginPath();
        g.moveTo(p.x, p.y + lay[i][1] - lay[i][2]*0.9);
        g.lineTo(p.x + lay[i][2], p.y + lay[i][1] + 6);
        g.lineTo(p.x - lay[i][2], p.y + lay[i][1] + 6);
        g.closePath(); g.fill();
      }
    } else if(d.t === "rock"){
      g.fillStyle = "#6b7280";
      g.beginPath(); g.ellipse(p.x, p.y+3, 15, 11, h*2, 0, 7); g.fill();
      g.fillStyle = "#8b939e";
      g.beginPath(); g.ellipse(p.x-3, p.y-1, 9, 6, h*2, 0, 7); g.fill();
    } else if(d.t === "cactus"){
      const sway = Math.sin(sg.time*1.2 + h*6)*1.2;
      g.fillStyle = "#3f7a3a";
      sgRR(g, p.x-4, p.y-22, 8, 34, 4); g.fill();
      sgRR(g, p.x-14, p.y-12, 8, 5, 2.5); g.fill();
      sgRR(g, p.x-14, p.y-16, 6, 9, 3); g.fill();
      sgRR(g, p.x+6+sway*0.3, p.y-6, 8, 5, 2.5); g.fill();
      sgRR(g, p.x+8+sway*0.3, p.y-12, 6, 11, 3); g.fill();
      g.fillStyle = "#5c9a52";
      sgRR(g, p.x-4, p.y-22, 3.5, 34, 3); g.fill();
      g.fillStyle = "#e8b4c8";
      g.beginPath(); g.arc(p.x, p.y-23+sway*0.2, 2.4, 0, 7); g.fill();
    } else if(d.t === "skull"){
      g.fillStyle = "#d8d2c2";
      g.beginPath(); g.ellipse(p.x, p.y-2, 9, 8, 0, 0, 7); g.fill();
      sgRR(g, p.x-5, p.y+2, 10, 6, 2); g.fill();
      g.fillStyle = "#4a4438";
      g.beginPath(); g.arc(p.x-3.4, p.y-3, 2.2, 0, 7); g.fill();
      g.beginPath(); g.arc(p.x+3.4, p.y-3, 2.2, 0, 7); g.fill();
      g.fillStyle = "#8a8272";
      g.fillRect(p.x-4, p.y+3.4, 1.6, 3.4); g.fillRect(p.x-0.8, p.y+3.4, 1.6, 3.4); g.fillRect(p.x+2.4, p.y+3.4, 1.6, 3.4);
    } else if(d.t === "pine"){
      const sway = Math.sin(sg.time*1.1 + h*6)*1.4;
      g.fillStyle = "#4a3828"; g.fillRect(p.x-2.6, p.y+2, 5.2, 11);
      const lay = [[0,-8,16],[0,-18,12.5],[0,-27,9]];
      for(let i=0;i<lay.length;i++){
        g.fillStyle = ["#2c4a3e","#38584a","#456856"][i];
        g.beginPath();
        g.moveTo(p.x+sway*(i*0.4), p.y + lay[i][1] - lay[i][2]*0.95);
        g.lineTo(p.x + lay[i][2], p.y + lay[i][1] + 6);
        g.lineTo(p.x - lay[i][2], p.y + lay[i][1] + 6);
        g.closePath(); g.fill();
        g.fillStyle = "rgba(255,255,255,.75)";
        g.beginPath();
        g.moveTo(p.x+sway*(i*0.4), p.y + lay[i][1] - lay[i][2]*0.95);
        g.lineTo(p.x + lay[i][2]*0.55, p.y + lay[i][1] - lay[i][2]*0.3);
        g.lineTo(p.x - lay[i][2]*0.55, p.y + lay[i][1] - lay[i][2]*0.3);
        g.closePath(); g.fill();
      }
    } else if(d.t === "emberrock"){
      const glow = 0.5 + Math.sin(sg.time*2.2 + h*8)*0.35;
      g.fillStyle = "#3a2830";
      g.beginPath(); g.ellipse(p.x, p.y+2, 14, 10, h, 0, 7); g.fill();
      g.fillStyle = "#241a20";
      g.beginPath(); g.ellipse(p.x-3, p.y-2, 9, 6, h, 0, 7); g.fill();
      g.globalAlpha = glow;
      g.strokeStyle = "#ff8a4c"; g.lineWidth = 1.6;
      g.beginPath(); g.moveTo(p.x-9, p.y+1); g.lineTo(p.x-2, p.y-3); g.lineTo(p.x+4, p.y+2); g.lineTo(p.x+10, p.y-1); g.stroke();
      g.globalAlpha = glow*0.35;
      g.fillStyle = "#ff8a4c";
      g.beginPath(); g.arc(p.x, p.y, 16, 0, 7); g.fill();
      g.globalAlpha = 1;
    } else if(d.t === "deadtree"){
      g.strokeStyle = "#3a2a30"; g.lineWidth = 3;
      g.beginPath(); g.moveTo(p.x, p.y+12); g.lineTo(p.x, p.y-14); g.stroke();
      g.lineWidth = 2;
      g.beginPath(); g.moveTo(p.x, p.y-4); g.lineTo(p.x-9, p.y-16); g.stroke();
      g.beginPath(); g.moveTo(p.x, p.y-9); g.lineTo(p.x+8, p.y-20); g.stroke();
      g.beginPath(); g.moveTo(p.x, p.y-14); g.lineTo(p.x-4, p.y-24); g.stroke();
    } else {
      g.fillStyle = "#2f5c30";
      for(const [dx,dy,rr] of [[-7,2,9],[6,3,8],[0,-3,10]]){
        g.beginPath(); g.arc(p.x+dx, p.y+dy, rr, 0, 7); g.fill();
      }
      g.fillStyle = "#d16a8a";
      for(let i=0;i<3;i++) { g.beginPath(); g.arc(p.x-8+i*8, p.y-4+sgHash(i,d.r)*6, 1.8, 0, 7); g.fill(); }
    }
  }
}

function sgDrawCastle(g){
  const cp = sgCC(SG_CASTLE.c, SG_CASTLE.r);
  const x = Math.min(cp.x, SG_W-34), y = cp.y;
  g.fillStyle = "rgba(0,0,0,.35)";
  g.beginPath(); g.ellipse(x, y+26, 34, 10, 0, 0, 7); g.fill();
  const stone = "#9aa3b2", stoneD = "#6f7787", stoneL = "#b8c0cd";
  // side towers
  for(const dx of [-24, 24]){
    g.fillStyle = stoneD; g.fillRect(x+dx-10, y-30, 20, 54);
    g.fillStyle = stone;  g.fillRect(x+dx-10, y-30, 13, 54);
    for(let i=0;i<3;i++){ g.fillStyle = stoneL; g.fillRect(x+dx-11+i*8, y-36, 5, 7); }
    g.fillStyle = "#2b3142"; g.fillRect(x+dx-3, y-16, 6, 9);
  }
  // keep
  g.fillStyle = stoneD; g.fillRect(x-19, y-44, 38, 68);
  g.fillStyle = stone;  g.fillRect(x-19, y-44, 25, 68);
  for(let i=0;i<5;i++){ g.fillStyle = stoneL; g.fillRect(x-20+i*8, y-51, 5, 8); }
  // gate
  g.fillStyle = "#4a3626";
  g.beginPath();
  if(g.roundRect) g.roundRect(x-9, y-2, 18, 26, [9,9,0,0]); else g.rect(x-9,y-2,18,26);
  g.fill();
  g.strokeStyle = "#2f2318"; g.lineWidth = 1.4;
  for(let i=1;i<4;i++){ g.beginPath(); g.moveTo(x-9, y-2+i*7); g.lineTo(x+9, y-2+i*7); g.stroke(); }
  // banner
  g.strokeStyle = "#c9ccd4"; g.lineWidth = 2;
  g.beginPath(); g.moveTo(x, y-51); g.lineTo(x, y-72); g.stroke();
  const wav = Math.sin(sg.time*3)*3;
  g.fillStyle = "#6c8cff";
  g.beginPath();
  g.moveTo(x, y-72); g.lineTo(x+20+wav, y-66); g.lineTo(x, y-58); g.closePath(); g.fill();
  // hp
  const f = Math.max(0, sg.hp/sg.maxHp);
  g.fillStyle = "rgba(0,0,0,.6)"; g.fillRect(x-28, y+30, 56, 6);
  g.fillStyle = f > .5 ? "#3ddc84" : f > .25 ? "#ffd35c" : "#ff5c5c";
  g.fillRect(x-28, y+30, 56*f, 6);
  if(f < 0.34){
    g.globalAlpha = 0.25 + Math.sin(sg.time*6)*0.2;
    g.fillStyle = "#ff5c5c";
    g.beginPath(); g.arc(x, y-8, 46, 0, 7); g.fill();
    g.globalAlpha = 1;
  }
}

function sgDrawTower(g, t){
  const rs = sgResolve(t);
  const p = sgCC(t.c, t.r);
  const x = p.x, y = p.y;
  const kick = (t.muzzle||0) > 0 ? 2 : 0;
  g.fillStyle = "rgba(0,0,0,.35)";
  g.beginPath(); g.ellipse(x, y+15, 19, 7, 0, 0, 7); g.fill();
  // stone footing
  g.fillStyle = "#6f7787"; sgRR(g, x-18, y+2, 36, 14, 5); g.fill();
  g.fillStyle = "#8b939e"; sgRR(g, x-18, y+2, 36, 7, 4); g.fill();

  const face = t.face || 0;
  if(t.key === "archer"){
    g.fillStyle = "#8b939e"; sgRR(g, x-12, y-20, 24, 26, 4); g.fill();
    g.fillStyle = "#b8c0cd"; sgRR(g, x-12, y-20, 15, 26, 4); g.fill();
    for(let i=0;i<3;i++){ g.fillStyle = "#6f7787"; g.fillRect(x-13+i*9, y-26, 6, 7); }
    g.fillStyle = rs.color;
    g.beginPath(); g.arc(x + Math.cos(face)*3, y-14 + Math.sin(face)*2, 5, 0, 7); g.fill();
    g.strokeStyle = "#e8d9b5"; g.lineWidth = 2;
    g.beginPath(); g.arc(x + Math.cos(face)*9, y-14 + Math.sin(face)*6, 7, face-1.1, face+1.1); g.stroke();
    if(rs.p && rs.p.key === "volley"){
      g.fillStyle = rs.color;
      for(let i=-1;i<=1;i++){ g.beginPath(); g.arc(x+i*7, y-24, 2.4, 0, 7); g.fill(); }
    }
  } else if(t.key === "militia"){
    g.fillStyle = "#c9b48a";
    g.beginPath(); g.moveTo(x, y-24); g.lineTo(x+16, y+4); g.lineTo(x-16, y+4); g.closePath(); g.fill();
    g.fillStyle = "#a8946e";
    g.beginPath(); g.moveTo(x, y-24); g.lineTo(x+16, y+4); g.lineTo(x+4, y+4); g.closePath(); g.fill();
    g.fillStyle = "#2b3142";
    g.beginPath(); g.moveTo(x-5, y+4); g.lineTo(x, y-8); g.lineTo(x+5, y+4); g.closePath(); g.fill();
    // spears
    g.strokeStyle = "#5b3a22"; g.lineWidth = 2;
    for(const dx of [-14, 14]){
      g.beginPath(); g.moveTo(x+dx, y+6); g.lineTo(x+dx+(dx>0?5:-5), y-22); g.stroke();
      g.fillStyle = "#d9dde6";
      g.beginPath(); g.arc(x+dx+(dx>0?5:-5), y-24, 2.4, 0, 7); g.fill();
    }
    g.strokeStyle = "#c9ccd4"; g.lineWidth = 1.6;
    g.beginPath(); g.moveTo(x, y-24); g.lineTo(x, y-36); g.stroke();
    g.fillStyle = rs.color;
    const w = Math.sin(sg.time*4 + t.c)*2;
    g.beginPath(); g.moveTo(x, y-36); g.lineTo(x+12+w, y-32); g.lineTo(x, y-28); g.closePath(); g.fill();
  } else if(t.key === "cannon"){
    g.fillStyle = "#6b4f33"; sgRR(g, x-15, y-8, 30, 16, 4); g.fill();
    g.fillStyle = "#8a6b45"; sgRR(g, x-15, y-8, 30, 8, 4); g.fill();
    g.fillStyle = "#3f4654";
    g.beginPath(); g.arc(x-9, y+6, 5, 0, 7); g.fill();
    g.beginPath(); g.arc(x+9, y+6, 5, 0, 7); g.fill();
    g.save(); g.translate(x, y-10); g.rotate(face * (rs.p && rs.p.key==="mortar" ? 0.25 : 0.55));
    g.fillStyle = "#39404f"; sgRR(g, -4-kick, -7, 28, 14, 6); g.fill();
    g.fillStyle = "#525b6d"; sgRR(g, -4-kick, -7, 24, 6, 4); g.fill();
    g.fillStyle = rs.color; g.beginPath(); g.arc(24-kick, 0, 4.4, 0, 7); g.fill();
    g.restore();
    if((t.muzzle||0) > 0){
      g.globalAlpha = (t.muzzle/0.1);
      g.fillStyle = "#ffe08a";
      g.beginPath(); g.arc(x + Math.cos(face)*26, y-10 + Math.sin(face)*14, 10, 0, 7); g.fill();
      g.globalAlpha = 1;
    }
  } else if(t.key === "sniper"){
    // perch
    g.fillStyle = "#5b4a33"; sgRR(g, x-10, y-24, 20, 28, 4); g.fill();
    g.fillStyle = "#7a6547"; sgRR(g, x-10, y-24, 12, 28, 4); g.fill();
    g.fillStyle = "#3b3627"; sgRR(g, x-13, y-30, 26, 8, 3); g.fill();
    // long rifle tracking the target
    g.save(); g.translate(x, y-26); g.rotate(face);
    g.strokeStyle = "#2e3340"; g.lineWidth = 3.4;
    g.beginPath(); g.moveTo(2, 0); g.lineTo(30-kick*2, 0); g.stroke();
    g.strokeStyle = rs.color; g.lineWidth = 1.4;
    g.beginPath(); g.moveTo(20, 0); g.lineTo(30-kick*2, 0); g.stroke();
    g.restore();
    // scope glint
    const gl = (Math.sin(sg.time*2.2 + t.c) + 1)/2;
    g.globalAlpha = 0.35 + gl*0.6;
    g.fillStyle = "#ffffff";
    g.beginPath(); g.arc(x + Math.cos(face)*10, y-26 + Math.sin(face)*10, 2, 0, 7); g.fill();
    g.globalAlpha = 1;
    if((t.muzzle||0) > 0){
      g.globalAlpha = t.muzzle/0.1;
      g.fillStyle = "#ffe08a";
      g.beginPath(); g.arc(x + Math.cos(face)*32, y-26 + Math.sin(face)*32, 6, 0, 7); g.fill();
      g.globalAlpha = 1;
    }
  } else if(t.key === "bank"){
    // vault house
    g.fillStyle = "#8a6b45"; sgRR(g, x-14, y-18, 28, 22, 4); g.fill();
    g.fillStyle = "#a8845a"; sgRR(g, x-14, y-18, 28, 10, 4); g.fill();
    g.fillStyle = "#6b4f33";
    g.beginPath(); g.moveTo(x-17, y-16); g.lineTo(x, y-30); g.lineTo(x+17, y-16); g.closePath(); g.fill();
    // coin sign, gently bobbing
    const bob = Math.sin(sg.time*2.4 + t.r)*1.6;
    g.fillStyle = "#ffd35c";
    g.beginPath(); g.arc(x, y-36+bob, 6.5, 0, 7); g.fill();
    g.fillStyle = "#c9a12e";
    g.font = "bold 9px system-ui"; g.textAlign = "center"; g.textBaseline = "middle";
    g.fillText("⚡", x, y-35.5+bob);
    g.textBaseline = "alphabetic";
    // door
    g.fillStyle = "#3b2e1c"; sgRR(g, x-4, y-8, 8, 12, 2); g.fill();
  } else {
    g.fillStyle = "#6f7787";
    g.beginPath(); g.moveTo(x-11, y+4); g.lineTo(x-7, y-26); g.lineTo(x+7, y-26); g.lineTo(x+11, y+4); g.closePath(); g.fill();
    g.fillStyle = "#b8c0cd";
    g.beginPath(); g.moveTo(x-11, y+4); g.lineTo(x-7, y-26); g.lineTo(x-1, y-26); g.lineTo(x-1, y+4); g.closePath(); g.fill();
    g.fillStyle = "#4a5162"; sgRR(g, x-11, y-32, 22, 8, 3); g.fill();
    const fl = 3 + Math.sin(sg.time*9 + t.c)*1.6;
    const cold = rs.p && rs.p.key === "frost";
    g.fillStyle = cold ? "#9ee8ff" : rs.color;
    g.beginPath(); g.ellipse(x, y-38-fl*0.4, 5+fl*0.4, 9+fl, 0, 0, 7); g.fill();
    g.globalAlpha = .35;
    g.beginPath(); g.arc(x, y-38, 15+fl, 0, 7); g.fill();
    g.globalAlpha = 1;
    if(rs.p && rs.p.key === "banner"){
      g.fillStyle = "#ffd35c";
      const w = Math.sin(sg.time*4)*2;
      g.beginPath(); g.moveTo(x+9, y-30); g.lineTo(x+22+w, y-25); g.lineTo(x+9, y-20); g.closePath(); g.fill();
    }
  }
  // level pips
  for(let i=0;i<(t.level||1);i++){
    g.fillStyle = i < SG_BRANCH_LEVEL-1 ? "#ffd35c" : rs.color;
    g.beginPath(); g.arc(x-16+i*8, y+19, 2.4, 0, 7); g.fill();
  }
  if(rs.hill){
    g.fillStyle = "rgba(210,235,170,.85)"; g.font = "bold 9px system-ui"; g.textAlign = "center";
    g.fillText("▲", x+17, y-16);
  }
  if(t.level >= SG_BRANCH_LEVEL-1 && !t.path){
    const b = 0.5 + Math.sin(sg.time*5)*0.5;
    g.globalAlpha = 0.4 + b*0.5;
    g.fillStyle = "#ffd35c"; g.font = "bold 13px system-ui"; g.textAlign = "center";
    g.fillText("★", x, y-34);
    g.globalAlpha = 1;
  }
}

function sgDrawUnit(g, e){
  const p = sgEnemyPos(e);
  const d = e.def, s = d.size;
  const bob = e.blocked ? Math.sin(sg.time*16)*1.5 : Math.sin(e.walk*6)*1.6;
  const x = p.x, y = p.y + (e.fly ? Math.sin(sg.time*5 + e.off)*4 : bob);
  if(e.fly){
    g.fillStyle = "rgba(0,0,0,.22)";
    g.beginPath(); g.ellipse(x, p.y+18, s*0.9, s*0.32, 0, 0, 7); g.fill();
  } else {
    g.fillStyle = "rgba(0,0,0,.30)";
    g.beginPath(); g.ellipse(x, p.y+s*0.75, s*0.85, s*0.3, 0, 0, 7); g.fill();
  }
  const hit = e.flash > 0;
  const body = hit ? "#ffffff" : d.body, trim = hit ? "#ffffff" : d.trim;
  if(d.ghost){
    g.save();
    g.globalAlpha = 0.45 + Math.sin(sg.time*4 + e.off)*0.15;
    // trailing wisps
    g.fillStyle = d.body;
    for(let k=1;k<=2;k++){
      g.beginPath(); g.arc(x - Math.cos(e.walk)*k*6, y + k*2, s*0.5/k, 0, 7); g.fill();
    }
  }
  if(d.heavy){
    // ground-shaking plates
    g.fillStyle = "#30353f";
    g.beginPath(); g.ellipse(x, y+2, s+3, s*0.85, 0, 0, 7); g.fill();
  }
  if(e.fly){
    const flap = Math.sin(sg.time*17 + e.off)*0.8;
    g.strokeStyle = trim; g.lineWidth = 2.6; g.lineCap = "round";
    g.beginPath();
    g.moveTo(x-s*1.5, y+flap*s*0.5); g.quadraticCurveTo(x-s*0.6, y-s*0.7, x, y);
    g.quadraticCurveTo(x+s*0.6, y-s*0.7, x+s*1.5, y+flap*s*0.5); g.stroke();
  } else {
    g.strokeStyle = trim; g.lineWidth = 2.6; g.lineCap = "round";
    const step = Math.sin(e.walk*6)*s*0.4;
    g.beginPath(); g.moveTo(x-2, y+s*0.4); g.lineTo(x-2+step, y+s*0.95); g.stroke();
    g.beginPath(); g.moveTo(x+2, y+s*0.4); g.lineTo(x+2-step, y+s*0.95); g.stroke();
  }
  g.fillStyle = body;
  sgRR(g, x-s*0.6, y-s*0.35, s*1.2, s*0.9, s*0.3); g.fill();
  g.fillStyle = trim;
  sgRR(g, x-s*0.6, y-s*0.35, s*1.2, s*0.28, s*0.16); g.fill();
  g.fillStyle = hit ? "#ffffff" : "#e8c9a0";
  g.beginPath(); g.arc(x, y-s*0.62, s*0.42, 0, 7); g.fill();
  g.fillStyle = hit ? "#888" : "#2a2f38";
  g.beginPath(); g.arc(x+s*0.16, y-s*0.66, s*0.09, 0, 7); g.fill();
  g.beginPath(); g.arc(x-s*0.16, y-s*0.66, s*0.09, 0, 7); g.fill();

  if(d.weapon === "sword" || d.weapon === "axe"){
    g.strokeStyle = "#c9ccd4"; g.lineWidth = d.boss ? 4 : 2.4;
    const sw = e.hitT > 0 ? 0.9 : 0.2;
    g.beginPath(); g.moveTo(x+s*0.55, y); g.lineTo(x+s*1.25, y-s*(0.75-sw)); g.stroke();
  } else if(d.weapon === "shield"){
    g.fillStyle = "#c9ccd4";
    sgRR(g, x+s*0.4, y-s*0.5, s*0.5, s*1.0, 3); g.fill();
    g.fillStyle = trim; sgRR(g, x+s*0.52, y-s*0.3, s*0.26, s*0.6, 2); g.fill();
  } else if(d.weapon === "staff"){
    g.strokeStyle = "#8a6b45"; g.lineWidth = 2.2;
    g.beginPath(); g.moveTo(x+s*0.5, y+s*0.4); g.lineTo(x+s*0.72, y-s*1.1); g.stroke();
    const glow = 2.6 + Math.sin(sg.time*7)*0.9;
    g.fillStyle = "#8affc0";
    g.beginPath(); g.arc(x+s*0.72, y-s*1.15, glow, 0, 7); g.fill();
  } else if(d.weapon === "knife"){
    g.strokeStyle = "#c9ccd4"; g.lineWidth = 1.8;
    g.beginPath(); g.moveTo(x+s*0.5, y+s*0.1); g.lineTo(x+s*0.95, y-s*0.2); g.stroke();
  }
  if(d.boss){
    g.fillStyle = "#ffd35c";
    g.beginPath(); g.moveTo(x-s*0.4, y-s*0.95); g.lineTo(x-s*0.24, y-s*1.3); g.lineTo(x-s*0.08, y-s*0.95); g.closePath(); g.fill();
    g.beginPath(); g.moveTo(x+s*0.08, y-s*0.95); g.lineTo(x+s*0.24, y-s*1.3); g.lineTo(x+s*0.4, y-s*0.95); g.closePath(); g.fill();
  }
  if(sg.time < e.slowUntil){
    g.strokeStyle = "#9ee8ff"; g.lineWidth = 1.8; g.globalAlpha = .8;
    g.beginPath(); g.arc(x, y, s*1.15, 0, 7); g.stroke(); g.globalAlpha = 1;
  }
  if(sg.time < e.burnUntil){
    g.globalAlpha = .55; g.fillStyle = "#ff8a4c";
    g.beginPath(); g.arc(x, y-s*0.2, s*0.9 + Math.sin(sg.time*15+e.off)*2, 0, 7); g.fill();
    g.globalAlpha = 1;
  }
  const f = Math.max(0, e.hp/e.maxHp);
  const bw = s*2;
    if(d.ghost) g.restore();
  g.fillStyle = "rgba(0,0,0,.65)"; g.fillRect(x-bw/2, y-s*1.35, bw, 4);
  g.fillStyle = f > .5 ? "#3ddc84" : f > .25 ? "#ffd35c" : "#ff5c5c";
  g.fillRect(x-bw/2, y-s*1.35, bw*f, 4);
  if(e.armor > 0){
    g.fillStyle = "rgba(200,214,235,.9)"; g.font = "bold 7px system-ui"; g.textAlign = "left";
    g.fillText("🛡", x-bw/2-9, y-s*1.28);
  }
}

function sgDrawBarricade(g, b){
  g.fillStyle = "rgba(0,0,0,.32)";
  g.beginPath(); g.ellipse(b.x, b.y+12, 20, 6, 0, 0, 7); g.fill();
  const shake = b.hitT > 0 ? Math.sin(sg.time*40)*1.6 : 0;
  g.save(); g.translate(shake, 0);
  for(let i=-1;i<=1;i++){
    g.fillStyle = i===0 ? "#8a6b45" : "#6f5436";
    sgRR(g, b.x-16+ (i+1)*11, b.y-16, 9, 30, 3); g.fill();
    g.fillStyle = "#4a3626";
    g.beginPath(); g.moveTo(b.x-16+(i+1)*11, b.y-16); g.lineTo(b.x-16+(i+1)*11+4.5, b.y-22); g.lineTo(b.x-16+(i+1)*11+9, b.y-16); g.closePath(); g.fill();
  }
  g.fillStyle = "#5a4029"; g.fillRect(b.x-18, b.y-6, 36, 5);
  g.restore();
  const f = Math.max(0, b.hp/b.maxHp);
  g.fillStyle = "rgba(0,0,0,.6)"; g.fillRect(b.x-17, b.y-27, 34, 4);
  g.fillStyle = "#c9a06a"; g.fillRect(b.x-17, b.y-27, 34*f, 4);
}

function sgDrawAmbient(g, dt){
  const T = SG_MAP.theme;
  if(!sg.amb) sg.amb = [];
  // trickle in new particles
  if(sg.amb.length < 34 && sgRand() < 0.5){
    if(T.ambient === "snow")   sg.amb.push({ x:sgRand()*SG_W, y:-6, vx:8+sgRand()*14, vy:22+sgRand()*22, r:1+sgRand()*1.8, a:0.5+sgRand()*0.4, ph:sgRand()*7 });
    if(T.ambient === "leaves") sg.amb.push({ x:sgRand()*SG_W, y:-6, vx:10+sgRand()*18, vy:16+sgRand()*16, r:1.6+sgRand()*1.6, a:0.35+sgRand()*0.3, ph:sgRand()*7 });
    if(T.ambient === "sand")   sg.amb.push({ x:-6, y:sgRand()*SG_H, vx:55+sgRand()*60, vy:(sgRand()-0.5)*8, r:1+sgRand()*1.6, a:0.22+sgRand()*0.2, ph:sgRand()*7 });
    if(T.ambient === "embers") sg.amb.push({ x:sgRand()*SG_W, y:SG_H+6, vx:(sgRand()-0.5)*16, vy:-(16+sgRand()*26), r:1+sgRand()*1.5, a:0.5+sgRand()*0.4, ph:sgRand()*7 });
  }
  for(let i=sg.amb.length-1;i>=0;i--){
    const p = sg.amb[i];
    p.x += (p.vx + Math.sin(sg.time*1.7+p.ph)*8)*dt;
    p.y += p.vy*dt;
    if(p.x > SG_W+8 || p.y > SG_H+8 || p.y < -10){ sg.amb.splice(i,1); continue; }
    g.globalAlpha = p.a * (T.ambient==="embers" ? (0.6+Math.sin(sg.time*6+p.ph)*0.4) : 1);
    g.fillStyle = T.ambC;
    g.beginPath(); g.arc(p.x, p.y, p.r, 0, 7); g.fill();
  }
  g.globalAlpha = 1;
}
function sgDraw(){
  const cv = document.getElementById("sgCanvas");
  if(!cv || !sg) return;
  const g = cv.getContext("2d");
  g.save();
  g.setTransform(2,0,0,2,0,0);
  g.textAlign = "center"; g.textBaseline = "middle";
  if(sg.shake > 0.2) g.translate((sgRand()-0.5)*sg.shake, (sgRand()-0.5)*sg.shake);
  g.clearRect(-20,-20,SG_W+40,SG_H+40);

  if(!sgTerrain) sgBakeTerrain();
  g.save(); g.setTransform(1,0,0,1,0,0);
  g.drawImage(sgTerrain, 0, 0);
  g.restore();
  // drifting cloud-light: two huge soft shadows sliding across the field
  for(let i=0;i<2;i++){
    const cx = ((sg.time*9 + i*SG_W*0.7) % (SG_W+560)) - 280;
    const cy = SG_H*(0.25 + i*0.4);
    const cg = g.createRadialGradient(cx, cy, 10, cx, cy, 230);
    cg.addColorStop(0, "rgba(10,14,30,.10)"); cg.addColorStop(1, "rgba(10,14,30,0)");
    g.fillStyle = cg;
    g.beginPath(); g.ellipse(cx, cy, 240, 120, 0, 0, 7); g.fill();
  }
  // travel arrows stay live so the flow reads
  g.strokeStyle = "rgba(255,255,255,.15)"; g.lineWidth = 2.5; g.lineCap = "round";
  for(const rt of SG_ROUTES){
    const drift = (sg.time*24) % 50;
    for(let d = drift; d < rt.total; d += 50){
      const a = sgPosOn(rt,d), b = sgPosOn(rt, Math.min(rt.total, d+10));
      const ang = Math.atan2(b.y-a.y, b.x-a.x);
      g.beginPath();
      g.moveTo(a.x - Math.cos(ang-0.6)*7, a.y - Math.sin(ang-0.6)*7);
      g.lineTo(a.x, a.y);
      g.lineTo(a.x - Math.cos(ang+0.6)*7, a.y - Math.sin(ang+0.6)*7);
      g.stroke();
    }
  }

  // burning ground
  for(const f of sg.fires){
    const k = f.t/f.life, fade = 1-k*k;
    // scorched ground
    g.globalAlpha = fade*0.5;
    g.fillStyle = "#2a1408";
    g.beginPath(); g.ellipse(f.x, f.y, f.r*0.95, f.r*0.62, 0, 0, 7); g.fill();
    // heat glow
    const gl = g.createRadialGradient(f.x, f.y, 2, f.x, f.y, f.r);
    gl.addColorStop(0, "rgba(255,220,120,.75)");
    gl.addColorStop(0.45, "rgba(255,130,50,.42)");
    gl.addColorStop(1, "rgba(255,90,30,0)");
    g.globalAlpha = fade;
    g.fillStyle = gl;
    g.beginPath(); g.ellipse(f.x, f.y, f.r, f.r*0.68, 0, 0, 7); g.fill();
    // licking flames
    for(let i=0;i<13;i++){
      const ang = i/13*6.28 + i*1.7;
      const rr = f.r*(0.15 + ((i*0.37)%0.65));
      const fx = f.x + Math.cos(ang)*rr, fy = f.y + Math.sin(ang)*rr*0.62;
      const hgt = 10 + Math.abs(Math.sin(sg.time*7 + i*1.9))*15;
      g.globalAlpha = fade*0.9;
      g.fillStyle = "#ff5c1a";
      g.beginPath();
      g.moveTo(fx-5, fy+3); g.quadraticCurveTo(fx-3, fy-hgt*0.6, fx, fy-hgt);
      g.quadraticCurveTo(fx+3, fy-hgt*0.6, fx+5, fy+3); g.closePath(); g.fill();
      g.fillStyle = "#ffd35c";
      g.beginPath();
      g.moveTo(fx-2.4, fy+2); g.quadraticCurveTo(fx-1.4, fy-hgt*0.34, fx, fy-hgt*0.55);
      g.quadraticCurveTo(fx+1.4, fy-hgt*0.34, fx+2.4, fy+2); g.closePath(); g.fill();
    }
    g.globalAlpha = 1;
  }

  sgDrawDecor(g);

  // range preview for the tower being placed
  if(sg.build && sg.hover){
    const def = sgTowerDef(sg.build);
    const ok = sgCanBuildAt(sg.hover.c, sg.hover.r) && sg.supply >= def.cost;
    const p = sgCC(sg.hover.c, sg.hover.r);
    const hillMul = sgIsHill(sg.hover.c, sg.hover.r) ? 1.18 : 1;
    g.fillStyle = ok ? "rgba(108,140,255,.12)" : "rgba(255,92,92,.12)";
    g.strokeStyle = ok ? "rgba(108,140,255,.7)" : "rgba(255,92,92,.7)";
    g.lineWidth = 2;
    g.beginPath(); g.arc(p.x, p.y, def.range*SG_CELL*hillMul, 0, 7); g.fill(); g.stroke();
    g.strokeStyle = ok ? "#6c8cff" : "#ff5c5c";
    g.strokeRect(p.x-SG_CELL/2+3, p.y-SG_CELL/2+3, SG_CELL-6, SG_CELL-6);
  }
  // ability targeting reticle
  if(sg.aiming && sg.hover){
    const ab = sgAbility(sg.aiming);
    const p = sgCC(sg.hover.c, sg.hover.r);
    const ok = sgAbilityValidAt(sg.aiming, sg.hover.c, sg.hover.r);
    g.strokeStyle = ok ? "#ffd35c" : "#ff5c5c"; g.lineWidth = 2.4;
    g.setLineDash([7,6]); g.lineDashOffset = -sg.time*22;
    if(ab.radius){
      g.fillStyle = ok ? "rgba(255,211,92,.14)" : "rgba(255,92,92,.12)";
      g.beginPath(); g.arc(p.x, p.y, ab.radius*SG_CELL, 0, 7); g.fill(); g.stroke();
    } else {
      g.strokeRect(p.x-22, p.y-22, 44, 44);
    }
    g.setLineDash([]);
  }
  // selected tower range
  if(sg.sel){
    const rs = sgResolve(sg.sel);
    const p = sgCC(sg.sel.c, sg.sel.r);
    g.fillStyle = "rgba(255,255,255,.06)";
    g.strokeStyle = "rgba(255,255,255,.45)"; g.lineWidth = 1.6;
    g.beginPath(); g.arc(p.x, p.y, rs.range, 0, 7); g.fill(); g.stroke();
    if(rs.minRange){
      g.strokeStyle = "rgba(255,92,92,.55)"; g.setLineDash([5,5]);
      g.beginPath(); g.arc(p.x, p.y, rs.minRange, 0, 7); g.stroke(); g.setLineDash([]);
    }
    g.strokeStyle = "#ffffff"; g.lineWidth = 2;
    g.strokeRect(p.x-24, p.y-24, 48, 48);
  }

  sgDrawCastle(g);
  for(const b of sg.barricades) sgDrawBarricade(g, b);
  const sorted = sg.towers.slice().sort((a,b)=>a.r-b.r);
  for(const t of sorted) sgDrawTower(g, t);

  // projectiles
  for(const s of sg.shots){
    const k = s.t/s.life;
    const x = s.x + (s.tx-s.x)*k;
    const y = s.y + (s.ty-s.y)*k - Math.sin(k*Math.PI)*(s.arc||10);
    if(s.kind === "arrow"){
      const ang = Math.atan2((s.ty-s.y) - Math.cos(k*Math.PI)*Math.PI*(s.arc||10)/1, s.tx-s.x);
      g.save(); g.translate(x,y); g.rotate(ang);
      g.strokeStyle = s.crit ? "#ffd35c" : s.color; g.lineWidth = s.crit ? 3 : 2;
      g.beginPath(); g.moveTo(-7,0); g.lineTo(6,0); g.stroke();
      g.fillStyle = s.crit ? "#ffd35c" : "#e8eaf2";
      g.beginPath(); g.moveTo(6,0); g.lineTo(2,-2.4); g.lineTo(2,2.4); g.closePath(); g.fill();
      g.restore();
    } else {
      g.globalAlpha = .35; g.fillStyle = "#20242e";
      g.beginPath(); g.arc(x-(s.tx-s.x)*0.05, y+4, 4.4, 0, 7); g.fill();
      g.globalAlpha = 1;
      g.fillStyle = "#39404f";
      g.beginPath(); g.arc(x, y, 5.4, 0, 7); g.fill();
      g.fillStyle = s.color;
      g.beginPath(); g.arc(x-1.4, y-1.4, 2.4, 0, 7); g.fill();
    }
  }

  for(const e of sg.enemies) sgDrawUnit(g, e);

  // effects
  for(const f of sg.fx){
    const k = f.t/f.life;
    g.globalAlpha = 1-k;
    if(f.kind === "boom"){
      g.fillStyle = "#ffe08a";
      g.beginPath(); g.arc(f.x, f.y, f.r*(0.25+k*0.55), 0, 7); g.fill();
      g.globalAlpha = (1-k)*0.7; g.fillStyle = f.color;
      g.beginPath(); g.arc(f.x, f.y, f.r*(0.35+k*0.75), 0, 7); g.fill();
    } else if(f.kind === "ring"){
      g.strokeStyle = f.color; g.lineWidth = 3;
      g.beginPath(); g.arc(f.x, f.y, f.r*(0.3+k), 0, 7); g.stroke();
    } else if(f.kind === "bit"){
      g.fillStyle = f.color;
      g.beginPath(); g.arc(f.x, f.y, f.r, 0, 7); g.fill();
    } else if(f.kind === "ember"){
      g.fillStyle = "#ffb45c";
      g.beginPath(); g.arc(f.x, f.y - k*16, 2.4*(1-k)+0.6, 0, 7); g.fill();
    } else if(f.kind === "coin"){
      g.fillStyle = "#ffd35c"; g.font = "bold 12px system-ui";
      g.fillText(f.txt, f.x, f.y - 16 - k*20);
    }
    g.globalAlpha = 1;
  }
  // damage numbers
  for(const n of sg.nums){
    const k = n.t/0.85;
    g.globalAlpha = 1-k*k;
    g.fillStyle = n.color;
    g.font = (n.big ? "bold 16px" : "bold 11px") + " system-ui";
    g.strokeStyle = "rgba(0,0,0,.6)"; g.lineWidth = 3;
    g.strokeText(n.txt, n.x, n.y - k*24);
    g.fillText(n.txt, n.x, n.y - k*24);
    g.globalAlpha = 1;
  }

  // kill streak
  if(sg.streak >= 5){
    const pulse = 1 + Math.sin(sg.time*10)*0.06;
    g.save(); g.translate(SG_W-74, 32); g.scale(pulse,pulse);
    g.fillStyle = "rgba(255,211,92,.16)"; sgRR(g,-62,-15,124,30,15); g.fill();
    g.strokeStyle = "#ffd35c"; g.lineWidth = 1.6; sgRR(g,-62,-15,124,30,15); g.stroke();
    g.fillStyle = "#ffd35c"; g.font = "bold 13px system-ui";
    g.fillText(`\ud83d\udd25 ${sg.streak} STREAK`, 0, 1);
    g.restore();
  }

  sgDrawAmbient(g, sgAmbDt);

  // vignette
  const vg = g.createRadialGradient(SG_W/2, SG_H/2, SG_H*0.42, SG_W/2, SG_H/2, SG_H*0.95);
  vg.addColorStop(0, "rgba(0,0,0,0)"); vg.addColorStop(1, "rgba(0,0,0,.34)");
  g.fillStyle = vg; g.fillRect(0,0,SG_W,SG_H);

  // prep banner
  if(sg.phase === "prep"){
    const two = !!sg.nextMod;
    const h = two ? 52 : 36, wdt = two ? 420 : 300;
    g.fillStyle = "rgba(6,12,20,.78)";
    sgRR(g, SG_W/2-wdt/2, 12, wdt, h, 12); g.fill();
    g.strokeStyle = "rgba(255,255,255,.14)"; g.lineWidth = 1; g.stroke();
    g.fillStyle = "#eef0f6"; g.font = "bold 16px system-ui";
    g.fillText(`Wave ${sg.wave+1} in ${Math.ceil(sg.countdown)}s — build now`, SG_W/2, two ? 30 : 30);
    if(two){
      g.fillStyle = "#ffd35c"; g.font = "bold 12px system-ui";
      g.fillText(`${sg.nextMod.icon} ${sg.nextMod.name} — ${sg.nextMod.desc}`, SG_W/2, 50);
    }
  }
  g.restore();
}

function sgCanBuildAt(c,r){
  if(c < 0 || r < 0 || c >= SG_COLS || r >= SG_ROWS) return false;
  if(sgIsPath(c,r)) return false;
  if(SG_BLOCKED.has(sgKey(c,r))) return false;
  if(c === SG_CASTLE.c && r === SG_CASTLE.r) return false;
  return !sg.towers.some(t=>t.c===c && t.r===r);
}
function sgAbilityValidAt(key, c, r){
  if(c < 0 || r < 0 || c >= SG_COLS || r >= SG_ROWS) return false;
  const ab = sgAbility(key);
  if(ab.target === "road") return sgIsPath(c,r) && !sg.barricades.some(b=>b.c===c&&b.r===r);
  return true;
}

let sgAmbDt = 0.016;
function sgLoop(ts){
  if(!sg || !sgTabActive){ sgRaf = null; return; }
  const dtReal = Math.min(0.05, (ts - sgLastTs)/1000 || 0);
  sgAmbDt = dtReal || 0.016;
  sgLastTs = ts;
  if(sg.phase === "prep" || sg.phase === "wave"){
    for(let i=0;i<sg.speed;i++){ if(sg.phase==="prep"||sg.phase==="wave") sgTick(dtReal); }
  }
  sgDraw();
  sgHudTick = (sgHudTick||0) + 1;
  if(sgHudTick % 5 === 0){ sgRenderHud(); sgUpdateEarlyBtn(); }
  sgRaf = requestAnimationFrame(sgLoop);
}
let sgHudTick = 0;
function sgStartLoop(){ if(sgRaf) return; sgLastTs = performance.now(); sgRaf = requestAnimationFrame(sgLoop); }
function sgStopLoop(){ if(sgRaf) cancelAnimationFrame(sgRaf); sgRaf = null; }

/* ---------------- SIEGE: INTERACTION ---------------- */
function sgCanvasCell(evt){
  const cv = document.getElementById("sgCanvas");
  const rect = cv.getBoundingClientRect();
  const src = evt.touches ? evt.touches[0] : evt;
  const x = (src.clientX - rect.left) * (SG_W/rect.width);
  const y = (src.clientY - rect.top) * (SG_H/rect.height);
  return { c:Math.floor(x/SG_CELL), r:Math.floor(y/SG_CELL) };
}
function sgBindCanvas(){
  const cv = document.getElementById("sgCanvas");
  if(!cv || cv.dataset.bound) return;
  cv.dataset.bound = "1";
  cv.addEventListener("mousemove", e=>{ if(sg) sg.hover = sgCanvasCell(e); });
  cv.addEventListener("mouseleave", ()=>{ if(sg) sg.hover = null; });
  cv.addEventListener("click", e=>{
    if(!sg) return;
    const cell = sgCanvasCell(e);
    sg.hover = cell;
    if(sg.aiming){ sgCastAbility(sg.aiming, cell.c, cell.r); return; }
    const existing = sg.towers.find(t=>t.c===cell.c && t.r===cell.r);
    if(existing){ sg.sel = existing; sg.build = null; }
    else if(sg.build){ sgPlace(cell.c, cell.r); }
    else { sg.sel = null; }
    sgRenderPalette(); sgRenderSel();
  });
  document.querySelectorAll("#sgSpeed button").forEach(b=>{
    b.addEventListener("click", ()=>{
      if(!sg) return;
      sg.speed = parseInt(b.dataset.spd, 10);
      document.querySelectorAll("#sgSpeed button").forEach(x=>x.classList.toggle("on", x===b));
    });
  });
}

function sgSelectBuild(key){
  if(!sg) return;
  sg.build = (sg.build === key) ? null : key;
  sg.sel = null; sg.aiming = null;
  sgRenderPalette(); sgRenderSel(); sgRenderAbilities();
}
const SG_BANK_CAP = 3;
function sgPlace(c,r){
  const def = sgTowerDef(sg.build);
  if(!def || !sgCanBuildAt(c,r)) return;
  if(def.key === "bank" && sg.towers.filter(t=>t.key==="bank").length >= SG_BANK_CAP){
    sgLog(`The crown licenses only ${SG_BANK_CAP} counting houses per siege.`, "bad"); return;
  }
  if(sg.supply < def.cost){ sgLog(`Not enough supply for a ${def.name}.`, "bad"); return; }
  sg.supply -= def.cost;
  const t = { key:def.key, c, r, level:1, cd:0, spent:def.cost, order:"first", path:null, auraDmg:1, auraRate:1 };
  sg.towers.push(t);
  sgRecalcAuras();
  const p = sgCC(c,r);
  sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.4, r:34, color:def.color });
  if(sg.supply >= def.cost){ sg.sel = null; }
  else { sg.sel = t; sg.build = null; }
  sgRenderPalette(); sgRenderSel(); sgRenderHud();
}
function sgUpgradeSel(){
  if(!sg || !sg.sel) return;
  const t = sg.sel;
  if(t.level >= SG_TOWER_MAX) return;
  if(t.level + 1 >= SG_BRANCH_LEVEL && !t.path){ sgRenderSel(); return; }  // must pick a path first
  const cost = sgUpgradeCost(t);
  if(sg.supply < cost){ sgLog("Not enough supply to upgrade.", "bad"); return; }
  sg.supply -= cost; t.spent += cost; t.level++;
  sgRecalcAuras();
  const p = sgCC(t.c,t.r);
  sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.4, r:30, color:"#ffd35c" });
  sgRenderSel(); sgRenderHud();
}
function sgChoosePath(pathKey){
  if(!sg || !sg.sel) return;
  const t = sg.sel;
  if(t.path || t.level < SG_BRANCH_LEVEL-1) return;
  const cost = sgUpgradeCost(t);
  if(sg.supply < cost){ sgLog("Not enough supply for that specialisation.", "bad"); return; }
  sg.supply -= cost; t.spent += cost; t.path = pathKey; t.level++;
  sgRecalcAuras();
  const p = sgCC(t.c,t.r);
  sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.55, r:44, color:"#ffd35c" });
  sgLog(`A ${sgTowerDef(t.key).name} became a <b>${sgResolve(t).name}</b>.`, "good");
  sgRenderSel(); sgRenderHud();
}
function sgCycleOrder(){
  if(!sg || !sg.sel) return;
  const i = SG_ORDERS.findIndex(o=>o.key === (sg.sel.order||"first"));
  sg.sel.order = SG_ORDERS[(i+1) % SG_ORDERS.length].key;
  sgRenderSel();
}
function sgSellSel(){
  if(!sg || !sg.sel) return;
  const t = sg.sel;
  const refund = Math.round(t.spent*0.6);
  sg.supply += refund;
  sg.towers.splice(sg.towers.indexOf(t), 1);
  sg.sel = null;
  sgRecalcAuras();
  sgLog(`Dismantled a tower. <span class="good">+${refund} supply</span>`);
  sgRenderSel(); sgRenderHud();
}

/* ---- Abilities ---- */
function sgArmAbility(key){
  if(!sg) return;
  const ab = sgAbility(key);
  if((sg.cd[key]||0) > 0 || sg.supply < ab.cost) return;
  if(ab.target === "self"){ sgCastAbility(key); return; }
  sg.aiming = (sg.aiming === key) ? null : key;
  sg.build = null; sg.sel = null;
  sgRenderAbilities(); sgRenderPalette(); sgRenderSel();
}
function sgCastAbility(key, c, r){
  const ab = sgAbility(key);
  if(!ab || (sg.cd[key]||0) > 0 || sg.supply < ab.cost) return;
  const s = computeEmpireStats();
  if(ab.target !== "self" && !sgAbilityValidAt(key, c, r)){
    sgLog(key === "barricade" ? "Barricades only go on the road." : "Can't aim there.", "bad");
    return;
  }
  const p = (ab.target === "self") ? sgCC(SG_CASTLE.c, SG_CASTLE.r) : sgCC(c,r);
  sg.supply -= ab.cost;
  sg.cd[key] = ab.cd;
  sg.aiming = null;

  if(key === "volley"){
    const dmg = 90 + s.castleAttack*0.85;
    const R = ab.radius*SG_CELL;
    sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.6, r:R, color:"#6c8cff" });
    for(let i=0;i<22;i++){
      const a = sgRand()*6.28, rr = Math.sqrt(sgRand())*R;
      sg.shots.push({ kind:"arrow", x:p.x+Math.cos(a)*rr, y:-30, tx:p.x+Math.cos(a)*rr, ty:p.y+Math.sin(a)*rr,
        t:0, life:0.18+sgRand()*0.35, color:"#8fa6ff", target:null, dmg:0 });
    }
    let hit = 0;
    for(let i=sg.enemies.length-1;i>=0;i--){
      const e = sg.enemies[i], q = sgEnemyPos(e);
      if(Math.hypot(q.x-p.x, q.y-p.y) <= R){ sgHurt(e, dmg, false, false); hit++; }
    }
    sgShake(4);
    sgLog(`🏹 Arrow volley — ${hit} caught in the open.`, "good");
  } else if(key === "pitch"){
    const dps = 40 + s.weaponPower*0.42;
    sg.fires.push({ x:p.x, y:p.y, r:ab.radius*SG_CELL, t:0, life:7, dps, slow:0.35 });
    sg.fx.push({ kind:"boom", x:p.x, y:p.y, t:0, life:0.4, r:ab.radius*SG_CELL, color:"#ff8a4c" });
    sgShake(3);
    sgLog(`🔥 The road is alight — ${Math.round(dps)} damage a second for 7s.`, "good");
  } else if(key === "barricade"){
    const hp = Math.round(300 + s.wallDefense*1.6 + s.castleDefense*0.7);
    const dBy = SG_ROUTES.map(rt => rt.cellD[sgKey(c,r)]);
    sg.barricades.push({ c, r, x:p.x, y:p.y, hp, maxHp:hp, hitT:0, dBy });
    sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.45, r:36, color:"#c9a06a" });
    sgLog(`🛡️ Palisade up — ${hp.toLocaleString()} HP of oak across the road.`, "good");
  } else if(key === "rally"){
    const heal = Math.round(sg.maxHp*0.20);
    sg.hp = Math.min(sg.maxHp, sg.hp + heal);
    sg.fx.push({ kind:"ring", x:p.x, y:p.y, t:0, life:0.6, r:70, color:"#3ddc84" });
    sgNum(p.x, p.y-40, "+"+heal.toLocaleString(), "#3ddc84", true);
    sgLog(`🔔 Banners raised — keep repaired for <span class="good">+${heal.toLocaleString()} HP</span>.`, "good");
  }
  sgRenderAbilities(); sgRenderHud();
}

function sgUpdateEarlyBtn(){
  const b = document.getElementById("sgEarlyBtn");
  if(!b || !sg) return;
  const show = sg.phase === "wave" && (sg.tier.endless || sg.wave < sg.tier.waves);
  b.style.display = show ? "" : "none";
  if(show) b.textContent = `⏩ Call wave ${sg.wave+1} early · +${Math.round(18 + sg.wave*5)}⚡`;
}
function sgWaveButton(){
  if(!sg || sg.phase !== "prep") return;
  const early = Math.max(0, Math.round(sg.countdown));
  sg.supply += 25 + early*6;
  sg.countdown = 0;
  sgLog(`Early call to arms. <span class="good">+${25 + early*6} supply</span>`, "good");
  sgRenderHud();
}

/* ---------------- SIEGE: PANELS ---------------- */
function sgRenderHud(){
  if(!sg) return;
  const set = (id, txt)=>{ const el = document.getElementById(id); if(el) el.textContent = txt; };
  set("sgTierName", `${sg.tier.icon} ${sg.tier.name}`);
  set("sgWaveLbl", sg.tier.endless ? `${sg.wave} · endless` : `${sg.wave} / ${sg.tier.waves}`);
  set("sgSupply", Math.floor(sg.supply).toLocaleString());
  const fill = document.getElementById("sgHpFill");
  const frac = Math.max(0, sg.hp/sg.maxHp);
  if(fill){
    fill.style.width = (frac*100)+"%";
    fill.style.background = frac > .5 ? "linear-gradient(90deg,#3ddc84,#8fe36a)"
      : frac > .25 ? "linear-gradient(90deg,#ffd35c,#ffb45c)" : "linear-gradient(90deg,#ff5c5c,#ff8f5c)";
  }
  set("sgHpTxt", `Keep ${Math.ceil(sg.hp).toLocaleString()} / ${sg.maxHp.toLocaleString()}`);
  const wb = document.getElementById("sgWaveBtn");
  if(wb){
    if(sg.phase === "prep"){ wb.disabled = false; wb.textContent = `▶ Send Wave ${sg.wave+1} (+${25+Math.max(0,Math.round(sg.countdown))*6}⚡)`; }
    else { wb.disabled = true; wb.textContent = sg.phase === "wave" ? `Wave ${sg.wave} in progress…` : "Siege over"; }
  }
  sgRenderAbilities(true);
  let tbi = 0;
  document.querySelectorAll("#sgTowerBar .sg-tb").forEach(b=>{
    const def = SG_TOWERS[tbi++];
    if(!def) return;
    b.classList.toggle("poor", sg.supply < def.cost);
    b.classList.toggle("sel", sg.build === def.key);
  });
}

function sgRenderPreview(){
  const el = document.getElementById("sgPreview");
  if(!el || !sg) return;
  if(sg.phase !== "prep" || sg.wave >= (sg.tier.waves||Infinity)){ el.style.display = "none"; return; }
  const pv = sgWavePreview(sg.wave+1);
  const ICONS = { scav:"🐀", raider:"🗡️", brute:"🛡️", harrier:"🦅", shaman:"🔮", warlord:"👹", wraith:"👻", splitter:"🟡", jugg:"🗿" };
  el.style.display = "block";
  el.innerHTML = `
    <div class="sg-pv-head">
      <b>Wave ${sg.wave+1}</b>
      ${pv.boss ? `<span class="sg-pv-mod boss">👹 Warlord</span>` : ""}
      ${pv.mod ? `<span class="sg-pv-mod">${pv.mod.icon} ${pv.mod.name} — ${pv.mod.desc}</span>` : ""}
    </div>
    <div class="sg-pv-units">
      ${Object.entries(pv.counts).map(([k,n])=>`<span>${ICONS[k]||"•"} ×${n}</span>`).join("")}
    </div>`;
}

function sgRenderPalette(){
  const el = document.getElementById("sgTowerBar");
  if(!el || !sg) return;
  el.innerHTML = "";
  SG_TOWERS.forEach(def=>{
    const b = document.createElement("div");
    const capped = def.key === "bank" && sg.towers.filter(t=>t.key==="bank").length >= SG_BANK_CAP;
    b.className = "sg-tb" + (sg.build===def.key ? " sel" : "") + (sg.supply < def.cost || capped ? " poor" : "");
    b.title = def.desc + (def.key === "bank" ? ` (max ${SG_BANK_CAP} per siege)` : "");
    b.innerHTML = `<span class="ic">${def.icon}</span><span class="cs">${capped ? "MAX" : def.cost+"⚡"}</span><span class="nm">${def.name}</span>`;
    b.addEventListener("click", ()=>sgSelectBuild(def.key));
    el.appendChild(b);
  });
}

function sgRenderAbilities(quick){
  const el = document.getElementById("sgAbilities");
  if(!el || !sg) return;
  if(!quick || !el.children.length){
    el.innerHTML = SG_ABILITIES.map(a=>`
      <button class="sg-ab" data-key="${a.key}">
        <span class="ic">${a.icon}</span>
        <span class="nm">${a.name}</span>
        <span class="cs">${a.cost}⚡</span>
        <i class="cdmask"></i>
        <span class="cdtxt"></span>
      </button>`).join("");
    el.querySelectorAll(".sg-ab").forEach(b=>b.addEventListener("click", ()=>sgArmAbility(b.dataset.key)));
  }
  el.querySelectorAll(".sg-ab").forEach(b=>{
    const a = sgAbility(b.dataset.key);
    const cd = sg.cd[a.key]||0;
    const ready = cd <= 0 && sg.supply >= a.cost;
    b.classList.toggle("ready", ready);
    b.classList.toggle("armed", sg.aiming === a.key);
    b.classList.toggle("poor", cd <= 0 && sg.supply < a.cost);
    b.querySelector(".cdmask").style.height = cd > 0 ? Math.min(100, cd/a.cd*100)+"%" : "0%";
    b.querySelector(".cdtxt").textContent = cd > 0 ? Math.ceil(cd)+"s" : "";
  });
  const hint = document.getElementById("sgAbilityHint");
  if(hint){
    const a = sg.aiming ? sgAbility(sg.aiming) : null;
    hint.textContent = a ? `${a.icon} ${a.name} — ${a.hint} Now tap the map.` : "";
    hint.style.display = a ? "block" : "none";
  }
}

function sgRenderSel(){
  const el = document.getElementById("sgSelPop");
  if(!el || !sg) return;
  if(!sg.sel || !sg.towers.includes(sg.sel)){ el.style.display = "none"; return; }
  const t = sg.sel, rs = sgResolve(t), def = sgTowerDef(t.key);
  const maxed = t.level >= SG_TOWER_MAX;
  const needsPath = !t.path && t.level >= SG_BRANCH_LEVEL-1;
  const cost = maxed ? 0 : sgUpgradeCost(t);
  const order = SG_ORDERS.find(o=>o.key === (t.order||"first"));
  const dmgNow = rs.dmg * (t.auraDmg||1);
  // preview next level for a delta chip on the upgrade button
  let delta = "";
  if(!maxed && !needsPath){
    const peek = sgResolve({ ...t, level:t.level+1 });
    const gain = Math.round((peek.dmg/rs.dmg - 1)*100);
    delta = rs.income ? `+${Math.round((peek.income/rs.income-1)*100)}% payout` : `+${gain}% dmg`;
  }
  let body = `
    <button class="px" onclick="sgCloseSel()">✕</button>
    <div class="ph"><span>${rs.icon}</span>${rs.name}<span class="lvl">Lv ${t.level}/${SG_TOWER_MAX}${rs.hill?" ▲":""}</span></div>
    <div class="pd">
      ${rs.income
        ? `<b style="color:${rs.color}">+${rs.income}⚡</b> every wave${rs.interest?` · +${Math.round(rs.interest*100)}% interest (cap ${rs.interestCap}⚡)`:""}`
        : `<b style="color:${rs.color}">${Math.round(dmgNow).toLocaleString()}</b> dmg · ${(rs.rate*(t.auraRate||1)).toFixed(2)}/s${rs.targets>1?` · ×${rs.targets}`:""}${rs.splash?` · splash`:""}${rs.pierce?` · pierces`:""}${rs.slow?` · slows`:""}${rs.sight||t.key==="signal"?` · sees Wraiths`:""}`}
      ${(t.auraDmg>1||t.auraRate>1)?`<br><span style="color:var(--good);">☆ buffed +${Math.round((t.auraDmg-1)*100)}% dmg / +${Math.round((t.auraRate-1)*100)}% rate</span>`:""}
      ${t.auraSight && t.key!=="signal" && !rs.sight ? `<br><span style="color:#9ee8ff;">☆ beacon-sight: can hit Wraiths</span>` : ""}
    </div>`;
  if(needsPath){
    body += def.paths.map(p=>`
      <button class="sgp-path" data-p="${p.key}" ${sg.supply < cost ? "disabled" : ""}>
        <span class="pn"><span style="color:${p.color}">${p.icon}</span>${p.name}<span class="cs">${cost.toLocaleString()}⚡</span></span>
        <span class="pb">${p.blurb}</span>
      </button>`).join("");
  } else {
    body += maxed
      ? `<button class="sgp-up" disabled>★ Fully upgraded</button>`
      : `<button class="sgp-up" ${sg.supply < cost ? "disabled" : ""} onclick="sgUpgradeSel()">
           <span>⬆ Lv ${t.level+1} · ${cost.toLocaleString()}⚡</span><span class="delta">${delta}</span>
         </button>`;
  }
  body += `<div class="sgp-row">
      ${rs.income ? "" : `<button onclick="sgCycleOrder()">🎯 ${order.name}</button>`}
      <button onclick="sgSellSel()">💥 Sell +${Math.round(t.spent*0.6)}⚡</button>
    </div>`;
  el.innerHTML = body;
  el.querySelectorAll(".sgp-path").forEach(b=>b.addEventListener("click", ()=>sgChoosePath(b.dataset.p)));
  // position beside the tower, inside the stage, flipped away from the edge
  const cv = document.getElementById("sgCanvas");
  const stage = cv.parentNode;
  const scale = cv.getBoundingClientRect().width / SG_W;
  const px = cv.offsetLeft + (t.c+0.5)*SG_CELL*scale, py = cv.offsetTop + (t.r+0.5)*SG_CELL*scale;
  el.style.display = "block";
  const pw = el.offsetWidth, ph = el.offsetHeight, sw = stage.clientWidth, sh = cv.getBoundingClientRect().height;
  let left = px + 34*scale;
  if(left + pw > sw - 84) left = px - pw - 34*scale;          // flip left of tower (clear of the tower bar)
  left = Math.max(6, Math.min(left, sw - pw - 6));
  let top = py - ph/2;
  top = Math.max(6, Math.min(top, sh - ph - 6));
  el.style.left = left + "px";
  el.style.top = top + "px";
}
function sgCloseSel(){ if(sg){ sg.sel = null; } sgRenderSel(); }

/* ---------------- SIEGE: RESULT + LOBBY ---------------- *//* ---------------- SIEGE: RESULT + LOBBY ---------------- */
function sgFinish(won){
  sg.phase = won ? "won" : "lost";
  const t = sg.tier;
  if(!state.siege) state.siege = defaultSiege();
  state.siege.kills = (state.siege.kills||0) + sg.kills;
  state.siege.bestStreak = Math.max(state.siege.bestStreak||0, sg.bestStreak);

  let rep = 0, cred = 0, notes = [];
  if(t.endless){
    rep = sg.endlessRep; cred = sg.endlessCred;
    notes.push(`Survived ${sg.wave - (won?0:1)} waves.`);
  } else if(won){
    rep = t.rep; cred = t.credits;
    if(sg.leaks === 0){ rep = Math.round(rep*1.5); cred = Math.round(cred*1.5); notes.push("Flawless defense — 50% bonus."); }
    const first = !(state.siege.cleared && state.siege.cleared[t.id]);
    if(first){ rep = Math.round(rep*2); cred = Math.round(cred*2); notes.push("First clear — double payout."); }
    else { rep = Math.round(rep*0.35); cred = Math.round(cred*0.35); notes.push("Repeat clear — the spoils have thinned."); }
    state.siege.cleared = state.siege.cleared || {};
    state.siege.cleared[t.id] = true;
    state.siege.wins = (state.siege.wins||0) + 1;
  } else {
    const frac = Math.max(0, (sg.wave-1) / t.waves) * 0.4;
    rep = Math.round(t.rep*frac); cred = Math.round(t.credits*frac);
    state.siege.losses = (state.siege.losses||0) + 1;
    notes.push(`The keep fell on wave ${sg.wave}. Partial spoils recovered.`);
  }
  state.empire.reputation += rep;
  state.credits += cred;
  state.siege.totalRep = (state.siege.totalRep||0) + rep;
  state.siege.totalCredits = (state.siege.totalCredits||0) + cred;
  saveState(); renderHeader();

  const rEl = document.getElementById("sgResult");
  const title = document.getElementById("sgResultTitle");
  title.textContent = won ? (t.endless ? "Siege Ended" : "Victory") : "The Keep Has Fallen";
  title.style.color = won ? "var(--good)" : "var(--bad)";
  document.getElementById("sgResultSub").textContent =
    notes.join(" ") + ` ${sg.kills.toLocaleString()} enemies destroyed · best streak ${sg.bestStreak}.`;
  document.getElementById("sgResultReward").innerHTML =
    `<span>🎖️ ${rep.toLocaleString()} Reputation</span><span>🪙 ${cred.toLocaleString()} Credits</span>`;
  if(rEl) rEl.classList.add("show");
  sgRenderTiers(); sgRenderStats();
}

function sgRenderMaps(){
  const row = document.getElementById("sgMapRow");
  if(!row) return;
  row.innerHTML = "";
  SG_MAPS.forEach(m=>{
    const el = document.createElement("button");
    el.className = "sg-map" + (sgChosenMap === m.id ? " sel" : "");
    el.innerHTML = `<span class="mi">${m.icon}</span><span class="mn">${m.name}</span><span class="mb">${m.blurb}</span>`;
    el.addEventListener("click", ()=>{ sgChosenMap = m.id; sgRenderMaps(); });
    row.appendChild(el);
  });
}
function sgRenderTiers(){
  sgRenderMaps();
  const grid = document.getElementById("sgTierGrid");
  if(!grid) return;
  grid.innerHTML = "";
  const stats = computeEmpireStats();
  SG_TIERS.forEach(t=>{
    const unlocked = sgTierUnlocked(t);
    const cleared = !!(state.siege && state.siege.cleared && state.siege.cleared[t.id]);
    const el = document.createElement("div");
    el.className = "sg-tier" + (unlocked ? "" : " locked") + (cleared ? " cleared" : "");
    const ready = stats.empirePower >= t.power;
    el.innerHTML = `
      <div class="th"><div class="ti">${t.icon}</div>
        <div><div class="tn">${t.name}</div>
        <div class="ts">${t.endless ? "Endless waves — bank rewards as you go" : t.waves+" waves"}</div></div>
      </div>
      ${cleared ? `<div class="sg-clear-chip">Cleared</div>` : ""}
      <div class="trow"><span>Recommended Power</span><b style="color:${ready?"var(--good)":"var(--bad)"}">${t.power.toLocaleString()}</b></div>
      <div class="trow"><span>Reward</span><b>${t.endless ? "scales per wave" : `${t.rep.toLocaleString()} 🎖️ · ${t.credits.toLocaleString()} 🪙`}</b></div>
      ${t.endless && state.siege && state.siege.bestEndlessWave ? `<div class="trow"><span>Best wave</span><b>${state.siege.bestEndlessWave}</b></div>` : ""}
      <button class="btn ${unlocked ? "" : "secondary"}" ${unlocked ? "" : "disabled"} style="margin-top:auto;">
        ${unlocked ? (cleared ? "Fight Again" : "Begin Siege") : (t.endless ? "🔒 Clear The Long Winter" : `🔒 Clear ${sgTier(t.id-1).name}`)}
      </button>`;
    if(unlocked) el.querySelector("button").addEventListener("click", ()=>sgBegin(t.id));
    grid.appendChild(el);
  });
}

function sgRenderStats(){
  const bar = document.getElementById("sgStatsBar");
  if(!bar) return;
  const s = computeEmpireStats();
  const si = state.siege || defaultSiege();
  bar.innerHTML = `
    <div class="stat"><div class="num" style="color:var(--good);">${s.empirePower.toLocaleString()}</div><div class="lbl">Empire Power</div></div>
    <div class="stat"><div class="num">${sgCastleMaxHp().toLocaleString()}</div><div class="lbl">Keep HP</div></div>
    <div class="stat"><div class="num">${sgStartSupply().toLocaleString()}</div><div class="lbl">Starting Supply</div></div>
    <div class="stat"><div class="num">${(si.wins||0).toLocaleString()}</div><div class="lbl">Sieges Won</div></div>
    <div class="stat"><div class="num">${(si.kills||0).toLocaleString()}</div><div class="lbl">Total Kills</div></div>
    <div class="stat"><div class="num">${(si.bestStreak||0).toLocaleString()}</div><div class="lbl">Best Kill Streak</div></div>
    <div class="stat"><div class="num">${(si.bestEndlessWave||0).toLocaleString()}</div><div class="lbl">Best Endless Wave</div></div>
  `;
}

function sgSizeCanvas(){
  const cv = document.getElementById("sgCanvas");
  if(!cv) return;
  cv.width = SG_W*2; cv.height = SG_H*2;              // crisp 2× internal resolution
  // in fullscreen, fit the viewport: fill the screen, leaving just enough for HUD + controls
  const battle = document.getElementById("sgBattle");
  if(battle && battle.classList.contains("sg-fs")){
    const small = window.innerWidth < 720;
    const reserve = small ? 244 : 205;                 // phones: HUD + docked tower bar
    const maxH = Math.max(300, window.innerHeight - reserve);
    cv.style.maxWidth = Math.round(maxH * (SG_W/SG_H)) + "px";
  } else {
    cv.style.maxWidth = "";
  }
}
function sgBegin(tierId, mapId){
  sgSeed = (Date.now() % 99991) + 7;
  sgLoadMap(mapId || sgChosenMap);
  sg = sgNewBattle(tierId);
  sg.leaksAtWaveStart = 0;
  sg.nextMod = null;
  document.getElementById("sgLobby").style.display = "none";
  const battle = document.getElementById("sgBattle");
  battle.style.display = "block";
  battle.classList.add("sg-fs");                       // the battle takes the whole screen
  document.documentElement.classList.add("sg-noscroll");
  const res = document.getElementById("sgResult");
  if(res) res.classList.remove("show");
  document.querySelectorAll("#sgSpeed button").forEach(x=>x.classList.toggle("on", x.dataset.spd==="1"));
  sgBindCanvas();
  sgSizeCanvas();
  sgTerrain = null;
  sgLog(`<b>${sg.tier.name}</b> · ${SG_MAP.icon} ${SG_MAP.name}. Keep at ${sg.maxHp.toLocaleString()} HP, ${sg.supply} supply in the stores.`);
  sgRenderPalette(); sgRenderSel(); sgRenderAbilities(); sgRenderPreview(); sgRenderHud();
  sgStartLoop();
}
window.addEventListener("resize", ()=>{ if(sg) sgSizeCanvas(); });
function sgRetry(){ if(sg) sgBegin(sg.tier.id); }
function sgLeaveBattle(){
  sgStopLoop();
  sg = null;
  const b = document.getElementById("sgBattle"), l = document.getElementById("sgLobby");
  if(b){ b.style.display = "none"; b.classList.remove("sg-fs"); }
  document.documentElement.classList.remove("sg-noscroll");
  if(l) l.style.display = "block";
  sgRenderTiers(); sgRenderStats();
}

function renderSiege(){
  const titleEl = document.getElementById("sgBannerTitle");
  if(titleEl){
    const n = (state.account && state.account.empireName) ? state.account.empireName : "The Empire";
    titleEl.textContent = `The Siege of ${n}`;
  }
  if(!state.siege) state.siege = defaultSiege();
  sgRenderStats();
  sgRenderTiers();
  if(sg){ sgRenderPalette(); sgRenderSel(); sgRenderAbilities(); sgRenderHud(); }
}
function sgOnEnterTab(){ sgTabActive = true; if(sg) sgStartLoop(); }
function sgOnLeaveTab(){ sgTabActive = false; sgStopLoop(); }

/* ---------------- FISHING ---------------- */
const FSH_W = 800, FSH_H = 560;   // 450 is the painting; below it the water continues
const FSH_HORIZON = 256;      // where the far shore meets the water
const FSH_SURF_END = 350;     // front edge of the surface — below this we see under the water
const FSH_DOCK_Y = 297;       // dock deck (matches the painting)
const FSH_DOCK_END = 288;     // where the painting's planks stop
const FSH_SIT_X = 270;        // fisherman's hips, at the painting's dock end
const FSH_MIRROR_Y = 322;     // reflections mirror about the dock's waterline

/* Outfits change what he's actually wearing on the dock. */
const FSH_OUTFITS = [
  { name:"Old Tee & Jeans",     coat:"#2e4460", coat2:"#243750", cuff:"#3d5878", pants:"#26374d", hat:"#4a3a28", band:"#2c2318", skin:"#e6b48d", hair:"#5a3f2a" },
  { name:"Flannel & Waders",    coat:"#a5453c", coat2:"#7e332c", cuff:"#c25c50", pants:"#4f5c46", hat:"#5e4c34", band:"#c9a06a", skin:"#e6b48d", hair:"#6b4a30" },
  { name:"Yellow Rain Slicker", coat:"#e8b843", coat2:"#c2952c", cuff:"#f5cd63", pants:"#3a5262", hat:"#e8b843", band:"#2f4756", skin:"#e6b48d", hair:"#6b4a30" },
  { name:"Sun-Bleached Vest",   coat:"#c3cfae", coat2:"#a3b08c", cuff:"#d6e0c4", pants:"#7d6f52", hat:"#ddd4b8", band:"#6b8a5c", skin:"#e6b48d", hair:"#6b4a30" },
  { name:"Deep Sea Bib",        coat:"#28455f", coat2:"#1d3348", cuff:"#37587a", pants:"#1b2c3e", hat:"#22384d", band:"#d9a400", skin:"#e6b48d", hair:"#4a3524" },
  { name:"Captain's Coat",      coat:"#1d2b42", coat2:"#141f32", cuff:"#2b3d59", pants:"#141f32", hat:"#0e1626", band:"#c9992e", skin:"#e6b48d", hair:"#3a2a1c" },
];

/* The scene's base layer is the reference painting itself — patched clean of the
   baked-in fisherman, line, splash, gulls and fish so every one of those can be
   animated live on top. The old procedural backdrop stays as a fallback. */
const FSH_BG_URL = "data:image/jpeg;base64,";
let fshBgImg = null, fshBgReady = false;
/* The painted fisherman, cut from the reference in two pieces — body and legs —
   so the legs can swing and the body can pump the rod without tearing the art. */
const FSH_MAN_BODY_URL = "data:image/png;base64,";
const FSH_MAN_LEGS_URL = "data:image/png;base64,";
let fshManBody = null, fshManLegs = null, fshManReady = false;
/* where the sprite sits in scene coordinates (derived from the source painting) */
const FSH_MAN = { x:233.0, y:218.0, w:77.2, h:135.4, ax:270, ay:300, gripX:292, gripY:278,
                  hipX:271, hipY:297 };

let fshT = 0;
let fshGulls = null, fshFish = null, fshRays = null, fshStreaks = null, fshWaves = null;
let fshBackdrop = null, fshCloudSprites = null, fshClouds = null, fshRaySprite = null;
let fshMirrorCv = null, fshMirrorCtx = null;

function fshCv(w,h){ const c = document.createElement("canvas"); c.width=w; c.height=h; return c; }
function fshCanBlur(){
  try{ const g = fshCv(4,4).getContext("2d"); g.filter = "blur(2px)"; return g.filter !== "none"; }catch(e){ return false; }
}

/* ---- Soft painterly cloud sprite, pre-rendered once so the blur costs nothing per frame ---- */
function fshMakeCloud(w, h, seed, blurOk){
  // The sprite is padded well beyond the shape: a blur clipped by the canvas edge
  // leaves a hard rectangle, which is exactly what we don't want.
  const blur = Math.max(2, Math.round(h*0.022));
  const pad = blur*4 + 12;
  const c = fshCv(w + pad*2, h + pad*2), g = c.getContext("2d");
  c._pad = pad;
  const rnd = (n)=>{ const v = Math.sin(seed*97.3 + n*41.7)*43758.5453; return v - Math.floor(v); };
  g.translate(pad, pad);
  const cx = w/2, cy = h*0.62;
  if(blurOk) g.filter = `blur(${blur}px)`;
  // shaded belly
  g.fillStyle = "rgba(196,216,228,.85)";
  for(let i=0;i<11;i++){
    const a = (i/11)*Math.PI - 0.15;
    const rx = w*0.11 + rnd(i)*w*0.10;
    g.beginPath();
    g.ellipse(cx - w*0.38 + (i/11)*w*0.76, cy + h*0.10 - Math.sin(a)*h*0.16, rx, rx*0.72, 0, 0, 7);
    g.fill();
  }
  // lit body
  g.fillStyle = "rgba(255,255,255,1)";
  for(let i=0;i<13;i++){
    const a = (i/13)*Math.PI;
    const rx = w*0.10 + rnd(i+20)*w*0.11;
    g.beginPath();
    g.ellipse(cx - w*0.36 + (i/13)*w*0.72, cy - Math.sin(a)*h*0.30 + rnd(i+40)*h*0.05, rx, rx*0.80, 0, 0, 7);
    g.fill();
  }
  // warm sunlit crown — soft and wide so it tints rather than reads as its own shape
  if(blurOk) g.filter = `blur(${blur*3}px)`;
  g.fillStyle = "rgba(255,247,222,.45)";
  for(let i=0;i<7;i++){
    const a = (i/7)*Math.PI*0.85 + 0.3;
    const rx = w*0.13 + rnd(i+60)*w*0.07;
    g.beginPath();
    g.ellipse(cx - w*0.24 + (i/7)*w*0.52, cy - Math.sin(a)*h*0.30 - h*0.03, rx, rx*0.7, 0, 0, 7);
    g.fill();
  }
  g.filter = "none";
  return c;
}

/* A single soft shaft of light, pre-blurred so its edges never read as a polygon. */
function fshMakeRay(blurOk){
  const W = 200, H = 150, pad = 34;
  const c = fshCv(W + pad*2, H + pad), g = c.getContext("2d");
  if(blurOk) g.filter = "blur(13px)";
  const gr = g.createLinearGradient(0, 0, 0, H);
  gr.addColorStop(0,   "rgba(236,250,255,.95)");
  gr.addColorStop(0.55,"rgba(236,250,255,.42)");
  gr.addColorStop(1,   "rgba(236,250,255,0)");
  g.fillStyle = gr;
  g.beginPath();
  g.moveTo(pad + W*0.34, 0);
  g.lineTo(pad + W*0.66, 0);
  g.lineTo(pad + W*0.92, H);
  g.lineTo(pad + W*0.02, H);
  g.closePath(); g.fill();
  g.filter = "none";
  return c;
}

/* ---- Sky, sun and the misty ridges, painted once into a buffer ---- */
const FSH_RIDGES = [
  { col:"#aec7cd", amp:30, base:96, freq:0.0049, ph:0.6, blur:5.0, mist:0.66 },
  { col:"#98bdb9", amp:33, base:80, freq:0.0067, ph:2.4, blur:3.5, mist:0.50 },
  { col:"#7eb09a", amp:30, base:64, freq:0.0090, ph:4.0, blur:2.4, mist:0.35 },
  { col:"#63a07e", amp:27, base:48, freq:0.0121, ph:5.6, blur:1.6, mist:0.21 },
  { col:"#48874f", amp:21, base:33, freq:0.0165, ph:1.5, blur:0.9, mist:0.10 },
  { col:"#30663c", amp:14, base:19, freq:0.0228, ph:4.4, blur:0,   mist:0.02 },
];
function fshRidgeH(r, x){
  return r.base
    + Math.sin(x*r.freq + r.ph)*r.amp
    + Math.sin(x*r.freq*2.3 + r.ph*1.7)*r.amp*0.40
    + Math.sin(x*r.freq*4.9 + r.ph*2.4)*r.amp*0.17
    + Math.sin(x*r.freq*9.3 + r.ph*3.2)*r.amp*0.07;
}
function fshBuildBackdrop(){
  const blurOk = fshCanBlur();
  const c = fshCv(FSH_W, FSH_H), g = c.getContext("2d");

  const sky = g.createLinearGradient(0,0,0,FSH_HORIZON+10);
  sky.addColorStop(0,   "#63aede");
  sky.addColorStop(0.34,"#8ec8e6");
  sky.addColorStop(0.66,"#bfdfec");
  sky.addColorStop(1,   "#e4f1f2");
  g.fillStyle = sky; g.fillRect(0,0,FSH_W,FSH_HORIZON+10);

  // big diffuse sun, high and to the right
  const sx = 636, sy = 22;
  const glow = g.createRadialGradient(sx,sy,2, sx,sy,300);
  glow.addColorStop(0,   "rgba(255,253,240,1)");
  glow.addColorStop(0.09,"rgba(255,250,225,.85)");
  glow.addColorStop(0.26,"rgba(255,245,206,.42)");
  glow.addColorStop(0.55,"rgba(252,241,205,.16)");
  glow.addColorStop(1,   "rgba(250,240,205,0)");
  g.fillStyle = glow; g.beginPath(); g.arc(sx,sy,300,0,7); g.fill();

  for(const r of FSH_RIDGES){
    if(blurOk && r.blur > 0) g.filter = `blur(${r.blur}px)`;
    g.beginPath();
    g.moveTo(-20, FSH_HORIZON+20);
    for(let x=-20; x<=FSH_W+20; x+=5) g.lineTo(x, FSH_HORIZON - Math.max(2, fshRidgeH(r,x)));
    g.lineTo(FSH_W+20, FSH_HORIZON+20); g.closePath();
    g.fillStyle = r.col; g.fill();
    g.filter = "none";
    // mist sitting in front of the ridge
    const hz = g.createLinearGradient(0, FSH_HORIZON-(r.base+r.amp*1.7), 0, FSH_HORIZON);
    hz.addColorStop(0,   `rgba(232,244,246,${r.mist*0.18})`);
    hz.addColorStop(0.5, `rgba(234,245,247,${r.mist*0.55})`);
    hz.addColorStop(1,   `rgba(240,249,250,${r.mist})`);
    g.fillStyle = hz;
    g.fillRect(0, FSH_HORIZON-(r.base+r.amp*1.7), FSH_W, (r.base+r.amp*1.7)+2);
  }
  // haze pooling right on the waterline
  const rim = g.createLinearGradient(0, FSH_HORIZON-26, 0, FSH_HORIZON);
  rim.addColorStop(0, "rgba(244,251,252,0)");
  rim.addColorStop(1, "rgba(246,252,253,.42)");
  g.fillStyle = rim; g.fillRect(0, FSH_HORIZON-26, FSH_W, 27);
  fshBackdrop = c;
}

function fshInitScene(){
  const blurOk = fshCanBlur();
  fshBuildBackdrop();
  if(!fshBgImg){
    fshBgImg = new Image();
    fshBgImg.onload = ()=>{ fshBgReady = true; };
    fshBgImg.src = FSH_BG_URL;
    if(fshBgImg.complete && fshBgImg.naturalWidth) fshBgReady = true;
  }
  if(!fshManBody){
    let loaded = 0;
    const done = ()=>{ if(++loaded>=2) fshManReady = true; };
    fshManBody = new Image(); fshManBody.onload = done; fshManBody.src = FSH_MAN_BODY_URL;
    fshManLegs = new Image(); fshManLegs.onload = done; fshManLegs.src = FSH_MAN_LEGS_URL;
    if(fshManBody.complete && fshManBody.naturalWidth && fshManLegs.complete && fshManLegs.naturalWidth) fshManReady = true;
  }
  fshCloudSprites = [
    fshMakeCloud(300,120, 1, blurOk), fshMakeCloud(230, 96, 2, blurOk),
    fshMakeCloud(360,140, 3, blurOk), fshMakeCloud(190, 82, 4, blurOk),
  ];
  fshClouds = [
    { i:1, x:150, y: 52, s:0.62, spd:2.0, a:0.85 },
    { i:3, x:520, y: 34, s:0.55, spd:1.4, a:0.75 },
    { i:0, x:-80, y: 96, s:0.5,  spd:1.1, a:0.6  },
  ];
  fshGulls = [
    { x: 70, y: 78, s:1.2, spd:12, ph:0.0 },
    { x:250, y:118, s:0.9, spd:9,  ph:1.9 },
  ];
  // soft light streaks lying on the surface
  fshStreaks = Array.from({length:52}, (_,i)=>{
    const d = (i%13)/13 + ((i*0.091)%0.07);
    return { y: FSH_HORIZON + 5 + d*(FSH_SURF_END-FSH_HORIZON-8),
             x: ((i*137)%FSH_W), w: 22 + (i%6)*26 + d*40, ph:(i*0.77)%6.28, d };
  });
  // thin outlined ripples along the front edge
  fshWaves = Array.from({length:9}, (_,i)=>({ x:(i*104)%FSH_W, y:FSH_SURF_END-4+((i%3)-1)*7, w:70+(i%4)*34, ph:(i*0.9)%6.28, spd:5+(i%3)*3 }));
  const SP = ["#2c5773","#24485f","#356a86","#1e3f57"];
  fshFish = Array.from({length:8}, (_,i)=>({
    x:(i*111)%FSH_W, y: FSH_SURF_END + 20 + ((i*67)%170),
    dir:(i%3===0)?-1:1, spd:7+(i%4)*4, s:0.75+((i*17)%9)/12,
    color:SP[i%SP.length], ph:(i*1.3)%6.28, dph:(i*0.7)%6.28 }));
  fshRays = Array.from({length:6}, (_,i)=>({ x: 330 + i*98, w: 40 + (i%3)*26, ph:(i*1.1)%6.28 }));
  fshRaySprite = fshMakeRay(blurOk);
  if(!fshMirrorCv){ fshMirrorCv = fshCv(FSH_W, FSH_H); fshMirrorCtx = fshMirrorCv.getContext("2d"); }
}

function fshRound(g,x,y,w,h,r){ g.beginPath(); if(g.roundRect) g.roundRect(x,y,w,h,r); else g.rect(x,y,w,h); }

function fshDrawSky(g){
  if(fshBgReady){
    g.drawImage(fshBgImg, 0, 0, FSH_W, 450);
    // the painting ends at y450 — continue its deep water down the extra canvas,
    // starting from the painting's own bottom-row colour so there is no seam
    const d = g.createLinearGradient(0, 442, 0, FSH_H);
    d.addColorStop(0, "rgba(62,111,137,0)");
    d.addColorStop(0.10, "rgba(62,111,137,1)");
    d.addColorStop(1, "rgb(34,74,104)");
    g.fillStyle = d; g.fillRect(0, 442, FSH_W, FSH_H-442);
  } else if(fshBackdrop){ g.drawImage(fshBackdrop, 0, 0); }
}
function fshDrawHills(g){ /* baked into the backdrop */ }
function fshDrawClouds(g){
  for(const c of fshClouds){
    c.x += c.spd*0.016;
    const sp = fshCloudSprites[c.i];
    const w = sp.width*c.s, h = sp.height*c.s;
    if(c.x > FSH_W + w) c.x = -w;
    g.globalAlpha = c.a;
    g.drawImage(sp, c.x - w/2, c.y - h/2, w, h);   // sprite is pre-padded, so no hard edge
    g.globalAlpha = 1;
  }
}
/* ---- The surface: pale, calm, streaked with soft reflected light ---- */
function fshDrawWater(g){
  if(!fshBgReady){
    const w = g.createLinearGradient(0,FSH_HORIZON,0,FSH_SURF_END);
    w.addColorStop(0,   "#cfe8ee");
    w.addColorStop(0.18,"#a8d6e6");
    w.addColorStop(0.60,"#83c4de");
    w.addColorStop(1,   "#6fb6d6");
    g.fillStyle = w; g.fillRect(0, FSH_HORIZON, FSH_W, FSH_SURF_END-FSH_HORIZON);
  }
  // soft horizontal light streaks drifting sideways
  g.save();
  g.beginPath(); g.rect(0, FSH_HORIZON+1, FSH_W, FSH_SURF_END-FSH_HORIZON-1); g.clip();
  g.lineCap = "round";
  for(const s of fshStreaks){
    s.x += (0.10 + s.d*0.5);
    if(s.x > FSH_W + 90) s.x = -90;
    const tw = 0.55 + 0.45*Math.sin(fshT*0.9 + s.ph);
    g.globalAlpha = (0.10 + s.d*0.30) * tw;
    g.strokeStyle = "#ffffff";
    g.lineWidth = 1.1 + s.d*2.2;
    const yy = s.y + Math.sin(fshT*0.8 + s.ph)*1.2;
    g.beginPath(); g.moveTo(s.x, yy); g.lineTo(s.x + s.w, yy); g.stroke();
  }
  g.globalAlpha = 1;
  g.restore();
}

/* ---- Under the surface ---- */
function fshDrawUnderwater(g){
  if(!fshBgReady){
    const d = g.createLinearGradient(0,FSH_SURF_END,0,FSH_H);
    d.addColorStop(0,   "#79c0da");
    d.addColorStop(0.30,"#5da5c8");
    d.addColorStop(1,   "#3f83ab");
    g.fillStyle = d; g.fillRect(0, FSH_SURF_END, FSH_W, FSH_H-FSH_SURF_END);
  }

  g.save();
  g.beginPath(); g.rect(0, FSH_SURF_END, FSH_W, FSH_H-FSH_SURF_END); g.clip();
  if(fshRaySprite){
    const H = FSH_H - FSH_SURF_END;
    for(const r of fshRays){
      const sway = Math.sin(fshT*0.42 + r.ph)*14;
      const a = 0.34 + 0.16*Math.sin(fshT*0.75 + r.ph*1.3);
      const w = r.w*3.4;
      g.globalAlpha = a;
      g.drawImage(fshRaySprite, r.x + sway - w/2, FSH_SURF_END - 6, w, H + 14);
    }
    g.globalAlpha = 1;
  }
  g.restore();
}

function fshDrawFishSchool(g){
  g.save();
  g.beginPath(); g.rect(0, FSH_SURF_END+1, FSH_W, FSH_H-FSH_SURF_END); g.clip();
  for(const f of fshFish){
    f.x += f.dir * f.spd * 0.016;
    if(f.dir > 0 && f.x > FSH_W + 70) f.x = -70;
    if(f.dir < 0 && f.x < -70) f.x = FSH_W + 70;
    const y = f.y + Math.sin(fshT*0.7 + f.dph)*4;
    const wag = Math.sin(fshT*4.6 + f.ph);
    const L = 34*f.s, Hh = 10*f.s;
    const depth = (y - FSH_SURF_END) / (FSH_H - FSH_SURF_END);
    g.globalAlpha = 0.60 - depth*0.22;
    g.save();
    g.translate(f.x, y); g.scale(f.dir, 1); g.rotate(wag*0.045);
    g.fillStyle = f.color;
    g.beginPath();
    g.moveTo(L*0.50, 0);
    g.quadraticCurveTo(L*0.16, -Hh*0.62, -L*0.24, -Hh*0.44);
    g.quadraticCurveTo(-L*0.40, -Hh*0.22, -L*0.44, 0);
    g.quadraticCurveTo(-L*0.40,  Hh*0.22, -L*0.24,  Hh*0.44);
    g.quadraticCurveTo(L*0.16,  Hh*0.62, L*0.50, 0);
    g.closePath(); g.fill();
    g.beginPath();
    g.moveTo(-L*0.42, 0);
    g.lineTo(-L*0.74, -Hh*0.62 + wag*Hh*0.26);
    g.lineTo(-L*0.66, 0);
    g.lineTo(-L*0.74,  Hh*0.62 + wag*Hh*0.26);
    g.closePath(); g.fill();
    g.beginPath();
    g.moveTo(-L*0.04, -Hh*0.5); g.lineTo(L*0.06, -Hh*1.0); g.lineTo(L*0.18, -Hh*0.44);
    g.closePath(); g.fill();
    g.restore();
  }
  g.globalAlpha = 1;
  g.restore();
}

/* ---- Thin outlined ripples along the front edge, not chunky foam ---- */
function fshDrawFoamLine(g){
  g.save();
  g.lineCap = "round"; g.lineJoin = "round";
  for(const w of fshWaves){
    w.x += w.spd*0.016;
    if(w.x > FSH_W + w.w) w.x = -w.w;
    const y = w.y + Math.sin(fshT*1.1 + w.ph)*2.5;
    g.globalAlpha = 0.75;
    g.strokeStyle = "#ffffff"; g.lineWidth = 2;
    g.beginPath();
    g.moveTo(w.x, y);
    g.quadraticCurveTo(w.x + w.w*0.25, y - 5, w.x + w.w*0.5, y);
    g.quadraticCurveTo(w.x + w.w*0.75, y + 4, w.x + w.w, y - 1);
    g.stroke();
    g.globalAlpha = 0.45;
    g.lineWidth = 1.4;
    g.beginPath();
    g.moveTo(w.x + w.w*0.18, y + 6);
    g.quadraticCurveTo(w.x + w.w*0.42, y + 1.5, w.x + w.w*0.66, y + 6);
    g.stroke();
  }
  g.globalAlpha = 1;
  g.restore();
}

function fshDrawReflection(g){
  if(!fshMirrorCtx) return;
  const m = fshMirrorCtx;
  m.clearRect(0,0,FSH_W,FSH_H);
  m.save(); m.textAlign="center"; m.textBaseline="middle";
  if(!fshBgReady){ fshDrawDock(m); fshDrawFisherman(m); }   // painting reflects its own dock & man
  m.restore();
  g.save();
  g.beginPath(); g.rect(0, FSH_MIRROR_Y, FSH_W, FSH_H-FSH_MIRROR_Y); g.clip();
  g.globalAlpha = 0.20;
  g.translate(0, FSH_MIRROR_Y*2); g.scale(1,-1);
  g.drawImage(fshMirrorCv, 0, 0);
  g.restore();
  g.save();
  g.beginPath(); g.rect(0, FSH_MIRROR_Y, FSH_W, FSH_H-FSH_MIRROR_Y); g.clip();
  for(let i=0;i<15;i++){
    const y = FSH_MIRROR_Y + 3 + i*9;
    g.globalAlpha = 0.14;
    g.strokeStyle = "#cdeaf5"; g.lineWidth = 2.6;
    g.beginPath();
    for(let x=0;x<=FSH_W;x+=18){
      const yy = y + Math.sin(x*0.028 + fshT*1.2 + i*0.6)*1.6;
      x ? g.lineTo(x,yy) : g.moveTo(x,yy);
    }
    g.stroke();
  }
  g.restore();
  g.globalAlpha = 1;
}

function fshDrawGull(g, x, y, s, flap){
  const up = Math.sin(flap)*0.55;
  g.lineCap = "round";
  g.strokeStyle = "rgba(255,255,255,.95)"; g.lineWidth = 2.4*s;
  g.beginPath();
  g.moveTo(x-13*s, y + 7*s*up);
  g.quadraticCurveTo(x-6*s, y-7*s*up, x, y);
  g.quadraticCurveTo(x+6*s, y-7*s*up, x+13*s, y + 7*s*up);
  g.stroke();
  g.fillStyle = "rgba(255,255,255,.95)";
  g.beginPath(); g.ellipse(x, y+1*s, 3.2*s, 2*s, 0, 0, 7); g.fill();
}
function fshDrawGulls(g){
  for(const b of fshGulls){
    b.x += b.spd*0.016;
    if(b.x > FSH_W + 40) b.x = -40;
    fshDrawGull(g, b.x, b.y + Math.sin(fshT*0.55 + b.ph)*8, b.s, fshT*4.6 + b.ph);
  }
}
function fshDrawDock(g){
  if(fshBgReady) return;              // the painting supplies the dock and its clutter
  const y = FSH_DOCK_Y, endX = FSH_DOCK_END;
  // pilings, continuing down through the water
  for(const px of [40, 118, 196, 274]){
    g.fillStyle = "#8a6c47"; g.fillRect(px-8, y+12, 17, 150);
    g.fillStyle = "#6d5335"; g.fillRect(px+3, y+12, 6, 150);
    g.fillStyle = "rgba(255,255,255,.14)"; g.fillRect(px-8, y+12, 3.5, 150);
    g.fillStyle = "#4e6b48"; g.fillRect(px-8, y+72, 17, 10);   // waterline moss
    g.fillStyle = "rgba(30,70,95,.28)"; g.fillRect(px-8, y+82, 17, 80);
  }
  // deck
  g.fillStyle = "#a5825a"; g.fillRect(0, y, endX, 15);
  g.fillStyle = "#8a6c47"; g.fillRect(0, y+11, endX, 8);
  for(let x=0; x<endX; x+=25){
    g.fillStyle = ((x/25)%2) ? "#ae8b62" : "#a07d55";
    g.fillRect(x, y, 23, 11);
    g.fillStyle = "rgba(70,48,26,.35)"; g.fillRect(x+23, y, 2, 11);
  }
  g.fillStyle = "rgba(255,246,222,.4)"; g.fillRect(0, y, endX, 2.5);
  g.fillStyle = "#6d5335"; g.fillRect(endX-3, y, 4, 19);

  // clutter
  g.fillStyle = "#93a0ad";
  g.beginPath(); g.moveTo(24, y-25); g.lineTo(54, y-25); g.lineTo(50, y); g.lineTo(28, y); g.closePath(); g.fill();
  g.fillStyle = "#7f8d99"; g.fillRect(24, y-27, 30, 5);
  g.strokeStyle = "#6b7883"; g.lineWidth = 2;
  g.beginPath(); g.arc(39, y-27, 13, Math.PI*1.05, Math.PI*1.95); g.stroke();
  g.fillStyle = "#4f7fa8";
  g.beginPath(); g.ellipse(39, y-9, 7, 4, 0, 0, 7); g.fill();
  g.fillStyle = "#c0452f"; fshRound(g, 66, y-31, 13, 31, 3); g.fill();
  g.fillStyle = "#8e2f1f"; fshRound(g, 66, y-31, 13, 8, 3); g.fill();
  g.fillStyle = "#d8c79a"; g.beginPath(); g.ellipse(101, y-6, 15, 7, 0, 0, 7); g.fill();
  g.fillStyle = "#c2ae7c"; g.beginPath(); g.ellipse(101, y-8, 12, 5, 0, 0, 7); g.fill();
  g.fillStyle = "#3f7a5c"; fshRound(g, 132, y-21, 44, 21, 3); g.fill();
  g.fillStyle = "#2f5f47"; g.fillRect(132, y-13, 44, 4);
  g.fillStyle = "#d9c07a"; g.fillRect(151, y-16, 7, 6);
  g.strokeStyle = "#2f5f47"; g.lineWidth = 2;
  g.beginPath(); g.arc(154, y-23, 8, Math.PI, 0); g.stroke();
}

/* The man himself. When the painting is live he IS the painting — the actual
   figure cut from the reference, breathing, swaying, tugging when a fish runs.
   The procedural drawing remains as the fallback. */
function fshDrawFisherman(g){
  if(fshBgReady && fshManReady){
    const M = FSH_MAN;
    const snap = v => Math.round(v*2)/2;             // half-pixel grid at 2x = no resample shimmer
    const reeling = fsh && fsh.phase === "reeling";
    const charging = fsh && fsh.phase === "charging";

    // slow idle life: breath-bob, gentle sway, an occasional weight shift
    const bob = snap(Math.sin(fshT*1.25)*1.0 + Math.sin(fshT*0.31)*0.5);
    let ang = Math.sin(fshT*0.55)*0.011;
    const breathe = 1 + Math.sin(fshT*1.25 + 0.7)*0.006;

    // reeling: he PUMPS the rod — a rhythmic rotational heave, not a vibration
    let crankX = 0, crankY = 0;
    if(reeling){
      const p = fshT*2*Math.PI*1.9;
      const heave = Math.pow(Math.max(0, Math.sin(p)), 1.5);   // sharp pull, soft release
      ang += -0.030*heave + 0.006*Math.sin(p*2);
      crankX = Math.cos(p*2)*1.1;                              // his hands crank a small circle
      crankY = Math.sin(p*2)*1.1;
    } else if(charging){
      ang -= 0.020 + (fsh.power/100)*0.022;                    // winding up, leaning back
    }

    // legs: relaxed pendulum swing off the dock edge; braced (quieter) while fighting a fish
    const swingScale = reeling ? 0.3 : 1;
    const legAng = (Math.sin(fshT*1.05)*0.030 + Math.sin(fshT*0.63+1.3)*0.013)*swingScale
                 + (reeling ? -0.018 : 0);

    // body (torso, head, arms)
    g.save();
    g.translate(M.ax, M.ay + bob);
    g.rotate(ang);
    g.scale(1, breathe);
    g.translate(-M.ax, -M.ay);
    g.drawImage(fshManBody, M.x, M.y, M.w, M.h);
    fshDrawHatBand(g);
    g.restore();

    // legs swing around the hip point, following the body's bob
    g.save();
    g.translate(M.hipX, M.hipY + bob);
    g.rotate(legAng);
    g.translate(-M.hipX, -M.hipY);
    g.drawImage(fshManLegs, M.x, M.y, M.w, M.h);
    g.restore();

    const ca = Math.cos(ang), sa = Math.sin(ang);
    const rx = M.gripX - M.ax, ry = M.gripY - M.ay;
    return { gripX: M.ax + crankX + rx*ca - ry*sa,
             gripY: M.ay + bob + crankY + (rx*sa + ry*ca)*breathe };
  }
  const o = FSH_OUTFITS[fshOutfitIndex()];
  const hipX = FSH_SIT_X, hipY = FSH_DOCK_Y - 1;
  const breathe = Math.sin(fshT*1.4)*1.2;
  const swing = Math.sin(fshT*1.05);
  const tug = (fsh && fsh.phase === "reeling") ? Math.sin(fshT*20)*2.2 : 0;

  const K = 0.86;                      // matches the painted figure's proportions
  g.save();
  g.translate(tug, 0);
  g.translate(hipX, hipY); g.scale(K, K); g.translate(-hipX, -hipY);
  g.lineCap = "round"; g.lineJoin = "round";

  const drawLeg = (dx, sw, back)=>{
    const kneeX = hipX + 20 + dx, kneeY = hipY + 13;
    const footX = kneeX - 3 + sw*8, footY = kneeY + 25 + Math.abs(sw)*3;
    g.strokeStyle = o.pants; g.lineWidth = 13;
    g.beginPath(); g.moveTo(hipX+2+dx, hipY+3); g.quadraticCurveTo(kneeX, kneeY, footX, footY); g.stroke();
    if(back){ g.strokeStyle = "rgba(0,0,0,.28)"; g.beginPath();
      g.moveTo(hipX+2+dx, hipY+3); g.quadraticCurveTo(kneeX, kneeY, footX, footY); g.stroke(); }
    g.strokeStyle = back ? "#4a3524" : "#5e4430"; g.lineWidth = 11.5;   // boot
    g.beginPath(); g.moveTo(footX-1, footY-2); g.lineTo(footX+8, footY+2); g.stroke();
    g.fillStyle = back ? "#38271a" : "#463123";
    g.beginPath(); g.ellipse(footX+5, footY+5.5, 7.5, 2.8, 0, 0, 7); g.fill();
  };
  drawLeg(-9, Math.sin(fshT*1.05 + 1.0)*0.8, true);
  drawLeg(5,  swing, false);

  // far arm bracing behind
  g.strokeStyle = o.coat2; g.lineWidth = 9;
  g.beginPath(); g.moveTo(hipX-3, hipY-31+breathe); g.quadraticCurveTo(hipX-16, hipY-14, hipX-13, hipY-1); g.stroke();

  // torso
  g.fillStyle = o.coat;
  g.beginPath();
  g.moveTo(hipX-14, hipY+3);
  g.quadraticCurveTo(hipX-18, hipY-27+breathe, hipX-8, hipY-44+breathe);
  g.quadraticCurveTo(hipX+6, hipY-51+breathe, hipX+13, hipY-38+breathe);
  g.quadraticCurveTo(hipX+16, hipY-15, hipX+12, hipY+3);
  g.closePath(); g.fill();
  g.fillStyle = o.coat2;
  g.beginPath();
  g.moveTo(hipX+2, hipY+3);
  g.quadraticCurveTo(hipX+14, hipY-17, hipX+13, hipY-38+breathe);
  g.quadraticCurveTo(hipX+16, hipY-15, hipX+12, hipY+3);
  g.closePath(); g.fill();
  // open collar
  g.fillStyle = o.cuff;
  g.beginPath();
  g.moveTo(hipX-9, hipY-45+breathe); g.lineTo(hipX+2, hipY-38+breathe); g.lineTo(hipX+9, hipY-46+breathe);
  g.lineTo(hipX+2, hipY-49+breathe); g.closePath(); g.fill();

  // neck + head
  const headY = hipY - 60 + breathe;
  g.strokeStyle = o.skin; g.lineWidth = 8.5;
  g.beginPath(); g.moveTo(hipX-1, hipY-44+breathe); g.lineTo(hipX+1, headY+9); g.stroke();
  g.fillStyle = o.skin;
  g.beginPath(); g.ellipse(hipX+2, headY, 12.5, 13.5, 0.05, 0, 7); g.fill();
  g.fillStyle = o.hair;                                         // hair at the nape
  g.beginPath(); g.ellipse(hipX-7, headY+1, 6, 8, 0.2, 0, 7); g.fill();
  g.fillStyle = "#dba97f";
  g.beginPath(); g.ellipse(hipX-5, headY+3, 3.2, 3.6, 0, 0, 7); g.fill();   // ear
  // face, in profile
  g.fillStyle = "#3a2c22";
  g.beginPath(); g.ellipse(hipX+7.5, headY-1, 1.5, 1.8, 0, 0, 7); g.fill();
  if(Math.sin(fshT*0.62) > 0.985){ g.fillStyle = o.skin; g.fillRect(hipX+5.5, headY-3.4, 5, 4); }
  g.strokeStyle = "#c08a62"; g.lineWidth = 1.7;
  g.beginPath(); g.moveTo(hipX+12, headY-1.5); g.quadraticCurveTo(hipX+16.5, headY+2, hipX+12, headY+4.5); g.stroke();
  g.strokeStyle = "#9a6244"; g.lineWidth = 1.5;
  g.beginPath(); g.arc(hipX+8, headY+6, 3.6, 0.15, 1.2); g.stroke();
  g.globalAlpha = .14; g.fillStyle = "#4a3626";
  g.beginPath(); g.ellipse(hipX+6, headY+8, 7, 4.6, 0, 0, 7); g.fill(); g.globalAlpha = 1;

  // wide-brim hat
  g.fillStyle = o.hat;
  g.beginPath(); g.ellipse(hipX+2, headY-9, 12.5, 10.5, 0, Math.PI, 0); g.fill();
  g.fillStyle = o.band;
  g.fillRect(hipX-10.5, headY-11.5, 25, 3.4);
  g.fillStyle = o.hat;
  g.beginPath(); g.ellipse(hipX+3, headY-7, 21.5, 5.2, 0.03, 0, 7); g.fill();
  g.fillStyle = "rgba(0,0,0,.20)";
  g.beginPath(); g.ellipse(hipX+3, headY-6, 21.5, 3.0, 0.03, 0, Math.PI); g.fill();

  // near arm to the rod
  const gripX = hipX + 27, gripY = hipY - 35 + breathe + tug;
  g.strokeStyle = o.coat; g.lineWidth = 9.5;
  g.beginPath(); g.moveTo(hipX+6, hipY-39+breathe); g.quadraticCurveTo(hipX+21, hipY-31+breathe, gripX, gripY); g.stroke();
  g.strokeStyle = o.cuff; g.lineWidth = 9.5;
  g.beginPath(); g.moveTo(gripX-5, gripY+3); g.lineTo(gripX-1, gripY+1); g.stroke();
  g.fillStyle = o.skin; g.beginPath(); g.arc(gripX, gripY, 4.6, 0, 7); g.fill();
  g.strokeStyle = o.coat2; g.lineWidth = 8.5;
  g.beginPath(); g.moveTo(hipX-2, hipY-33+breathe); g.quadraticCurveTo(hipX+11, hipY-21+breathe, gripX-10, gripY+12); g.stroke();
  g.fillStyle = o.skin; g.beginPath(); g.arc(gripX-10, gripY+12, 4.2, 0, 7); g.fill();

  g.restore();
  return { gripX: hipX + (gripX - hipX)*K + tug, gripY: hipY + (gripY - hipY)*K };
}

/* ---- What the equipped gear looks like in the scene ---- */
function fshEqQ(slot){ const it = fshEquippedItem(slot); return it ? it.q : 0; }
const FSH_ROD_STYLES = [
  { c1:"#8a5c34", c2:"#5b3a22", w:5.0, len:112, guides:0, wraps:null },                    // bare/branch
  { c1:"#8a5c34", c2:"#5b3a22", w:5.0, len:118, guides:0, wraps:null },                    // starter
  { c1:"#d8c078", c2:"#a08848", w:4.4, len:122, guides:2, wraps:"#84422c" },               // fiberglass
  { c1:"#5a6270", c2:"#343941", w:3.8, len:126, guides:3, wraps:"#c2cad8" },               // graphite
  { c1:"#2e3440", c2:"#171b24", w:3.6, len:133, guides:4, wraps:"#3f8fd0" },               // carbon surf
  { c1:"#c09858", c2:"#7a5a30", w:4.4, len:130, guides:4, wraps:"#d4af37", brass:true },   // split-cane
];
const FSH_LINE_STYLES = [
  { taut:"rgba(255,255,255,.85)", slack:"rgba(255,255,255,.6)",  w:1.6 },
  { taut:"rgba(255,255,255,.85)", slack:"rgba(255,255,255,.6)",  w:1.6 },   // mono
  { taut:"rgba(224,242,255,.6)",  slack:"rgba(224,242,255,.4)",  w:1.3 },   // fluoro — near invisible
  { taut:"rgba(120,160,110,.95)", slack:"rgba(120,160,110,.7)",  w:1.8 },   // braid
  { taut:"rgba(232,186,80,.95)",  slack:"rgba(232,186,80,.7)",   w:1.9 },   // kevlar
  { taut:"rgba(150,225,255,.95)", slack:"rgba(150,225,255,.75)", w:1.7 },   // titanium
];
const FSH_BOB_STYLES = [
  { top:"#e04a3c", bot:"#f5f5f5" },
  { top:"#e04a3c", bot:"#f5f5f5" },              // barbed
  { top:"#e8862c", bot:"#f8e8b0" },              // circle
  { top:"#3f9e5c", bot:"#eef5ee", stripe:"#2a6e40" },   // treble
  { top:"#7a4fd0", bot:"#e8e0f8", glow:"rgba(154,95,224,.5)" },  // chem-sharpened
  { top:"#d4a017", bot:"#fdf4d0", glow:"rgba(255,207,64,.6)", glint:true }, // auto-set
];
const FSH_HAT_COLORS = [null, null, "#8fae7a", "#3f9ec9", "#9a5fe0", "#ffcf40"];

/* A band on his painted hat, in the colour of the hat he owns. Drawn inside the
   body transform so it rides every nod and sway. */
function fshDrawHatBand(g){
  const q = fshEqQ("hat");
  const col = FSH_HAT_COLORS[q];
  if(!col) return;
  g.save();
  // a slim ribbon along the base of the crown, following the hat's tilt
  g.translate(266.5, 251.2); g.rotate(-0.13);
  g.globalAlpha = 0.62;
  g.fillStyle = col;
  fshRound(g, -9.5, -1.0, 19, 2.0, 1.0); g.fill();
  g.globalAlpha = 1;
  g.restore();
}

/* Rod bends when a fish is on. Returns the rod tip so the line can hang off it. */
function fshDrawRod(g, grip){
  const bend = (fsh && fsh.phase === "reeling") ? 26 + Math.sin(fshT*9)*7
             : (fsh && fsh.phase === "bite") ? 9 : (fsh && fsh.phase === "charging") ? -8 - fsh.power*0.14 : 3;
  const bx = grip.gripX, by = grip.gripY;
  const sprite = fshBgReady && fshManReady;
  const st = FSH_ROD_STYLES[fshEqQ("rod")] || FSH_ROD_STYLES[0];
  const L = st.len;
  const tipX = bx + L, tipY = by - Math.round(L*0.56) + bend;
  const cx = bx + L*0.44, cy = by - L*0.37 + bend*0.35;
  g.strokeStyle = st.c2; g.lineWidth = st.w;
  g.beginPath(); g.moveTo(bx-14, by+18); g.quadraticCurveTo(cx, cy, tipX, tipY); g.stroke();
  g.strokeStyle = st.c1; g.lineWidth = Math.max(1.6, st.w*0.4);
  g.beginPath(); g.moveTo(bx-14, by+18); g.quadraticCurveTo(cx, cy, tipX, tipY); g.stroke();
  if(st.wraps){
    // thread wraps near the butt + line guides along the blank
    g.strokeStyle = st.wraps; g.lineWidth = 2.4;
    for(const t of [0.10, 0.16]){
      const qx = (1-t)*(1-t)*(bx-14) + 2*(1-t)*t*cx + t*t*tipX;
      const qy = (1-t)*(1-t)*(by+18) + 2*(1-t)*t*cy + t*t*tipY;
      g.beginPath(); g.moveTo(qx-1.5, qy-2.5); g.lineTo(qx+1.5, qy+2.5); g.stroke();
    }
    g.lineWidth = 1.3;
    for(let i=1; i<=st.guides; i++){
      const t = 0.25 + i*(0.68/st.guides);
      const qx = (1-t)*(1-t)*(bx-14) + 2*(1-t)*t*cx + t*t*tipX;
      const qy = (1-t)*(1-t)*(by+18) + 2*(1-t)*t*cy + t*t*tipY;
      g.strokeStyle = st.brass ? "#d4af37" : st.wraps;
      g.beginPath(); g.arc(qx, qy+2.2, 2.0, 0, 7); g.stroke();
    }
  }
  if(!sprite){
    // cork grip + reel (the painted figure already has his own)
    g.strokeStyle = "#c9a06a"; g.lineWidth = 7;
    g.beginPath(); g.moveTo(bx-14, by+18); g.lineTo(bx+4, by+7); g.stroke();
    g.fillStyle = "#43506b"; g.beginPath(); g.arc(bx+9, by+11, 6.5, 0, 7); g.fill();
    g.strokeStyle = "#8fa2c9"; g.lineWidth = 1.6;
    const spin = (fsh && fsh.phase === "reeling") ? fshT*14 : fshT*0.6;
    g.beginPath(); g.moveTo(bx+9, by+11); g.lineTo(bx+9+Math.cos(spin)*5, by+11+Math.sin(spin)*5); g.stroke();
  }
  return { x:tipX, y:tipY };
}

/* ---------------- FISHING: TRAINING (permanent, Upgrades tab) ---------------- */
/* These are the angler, not the gear. Permanent, bought with Credits, and they
   live in the Upgrades tab alongside every other permanent upgrade. */
const FSH_TIER_COST  = [0, 15000, 90000, 500000, 2500000, 12000000];
const FSH_TIER_LEVEL = [0, 0, 2, 5, 9, 14];
const FSH_MAX_TIER = 5;

const FSH_SKILLS = [
  { key:"rod",    name:"Casting Technique", icon:"🫱", costMult:1.0,
    effect:"Years of practice put the bobber where you want it.",
    stat:(t)=>`+${(t*6)}% cast distance · +${(t*0.6).toFixed(1)} reel power` },
  { key:"reel",   name:"Reeling Strength",  icon:"💪", costMult:1.1,
    effect:"Every crank of the handle brings in more line.",
    stat:(t)=>`+${(t*2.2).toFixed(1)} reel power` },
  { key:"line",   name:"Line Control",      icon:"🎚️", costMult:0.85,
    effect:"You feel the strain before the line does.",
    stat:(t)=>`+${(t*18)} max tension` },
  { key:"hook",   name:"Hook Setting",      icon:"⚡", costMult:0.9,
    effect:"You set the hook the instant it goes down.",
    stat:(t)=>`+${(t*0.3).toFixed(2)}s bite window` },
  { key:"bait",   name:"Bait Craft",        icon:"🥣", costMult:0.7,
    effect:"You present bait so well it works harder than it should.",
    stat:(t)=>`−${Math.round((1-Math.pow(0.93,t))*100)}% wait · ${Math.round(t*12)}% chance bait isn't used up` },
  { key:"lure",   name:"Fish Sense",        icon:"👁️", costMult:1.35,
    effect:"You read the water and know where the big ones sit.",
    stat:(t)=>`+${(t*0.55).toFixed(2)} catch luck` },
  { key:"box",    name:"Haggling",          icon:"🤝", costMult:1.0,
    effect:"You know exactly what a fish like that is worth.",
    stat:(t)=>`+${(t*14)}% catch value` },
  { key:"gloves", name:"Grip Training",     icon:"🖐️", costMult:0.6,
    effect:"Calloused hands recover between pulls.",
    stat:(t)=>`+${(t*3.5).toFixed(1)} tension recovery · softer hands on the reel` },
  { key:"outfit", name:"Endurance",         icon:"🫀", costMult:0.8,
    effect:"Long afternoons stopped wearing you out. Small bonus to everything.",
    stat:(t)=>`+${(t*0.4).toFixed(1)} reel power · +${(t*3)}% value · +${(t*0.1).toFixed(2)} luck` },
];
function fshSkill(key){ return FSH_SKILLS.find(s=>s.key===key); }
function fshSkillCost(skill, tier){ return Math.round(FSH_TIER_COST[tier] * skill.costMult); }
function fshSkillTier(key){
  const f = state.fishing;
  return (f && f.skills && f.skills[key]) || 0;
}
function fshBuySkill(key){
  const skill = fshSkill(key);
  if(!skill) return;
  if(!state.fishing) state.fishing = defaultFishing();
  const tier = fshSkillTier(key);
  if(tier >= FSH_MAX_TIER) return;
  const next = tier + 1;
  const playerLevel = (state.player && state.player.level) || 1;
  if(playerLevel < FSH_TIER_LEVEL[next]) return;
  const cost = fshSkillCost(skill, next);
  if(state.credits < cost) return;
  state.credits -= cost;
  state.fishing.skills[key] = next;
  saveState(); renderHeader(); renderUpgrades(); renderFishingStats();
}

