function fshItem(id){ return FSH_ITEMS.find(i=>i.id===id); }

/* ---- Bait: consumed one per cast ---- */
const FSH_BAIT = [
  { id:"bread",  name:"Stale Bread",         icon:"🍞", bundle:25, price:400,     stats:{speed:5} },
  { id:"worm",   name:"Garden Worms",        icon:"🪱", bundle:25, price:1800,    stats:{speed:14,luck:0.3} },
  { id:"crawler",name:"Nightcrawlers",       icon:"🪱", bundle:25, price:9000,    stats:{speed:24,luck:0.7} },
  { id:"minnow", name:"Live Minnows",        icon:"🐟", bundle:25, price:45000,   stats:{speed:34,luck:1.3,loot:6} },
  { id:"shrimp", name:"Shrimp & Squid",      icon:"🦐", bundle:25, price:220000,  stats:{speed:44,luck:2.1,loot:12} },
  { id:"dough",  name:"Secret Family Dough", icon:"🥟", bundle:25, price:1100000, stats:{speed:55,luck:3.2,loot:20} },
];
function fshBait(id){ return FSH_BAIT.find(b=>b.id===id); }
/* Fishing a bare hook is allowed, just worse. */
const FSH_NO_BAIT = { speed:-25, luck:-0.5 };

/* ---- Charms: a run of casts with something strong turned on ---- */
const FSH_CHARMS = [
  { id:"chum",   name:"Chum Bucket",       icon:"🪣", price:60000,  casts:10, stats:{speed:45},
    blurb:"Bites come in roughly half the time for 10 casts." },
  { id:"sinker", name:"Lucky Sinker",      icon:"🍀", price:150000, casts:10, stats:{luck:3},
    blurb:"+3 catch luck for 10 casts — a real shot at the deep stuff." },
  { id:"tag",    name:"Trophy Tag",        icon:"💰", price:400000, casts:5,  stats:{loot:100},
    blurb:"Double value on everything you land for 5 casts." },
  { id:"calm",   name:"Calm Water Charm",  icon:"🌊", price:200000, casts:10, stats:{calm:100},
    blurb:"For 10 casts the fish simply never runs." },
];
function fshCharm(id){ return FSH_CHARMS.find(c=>c.id===id); }
/* ---- Inventory helpers ---- */
function fshInv(){
  if(!state.fishing) state.fishing = defaultFishing();
  return state.fishing;
}
function fshOwns(id){ return (fshInv().items[id]||0) > 0; }
function fshEquipped(slot){ return fshInv().equipped[slot] || null; }
function fshEquippedItem(slot){ const id = fshEquipped(slot); return id ? fshItem(id) : null; }

function fshBuyItem(id){
  const it = fshItem(id);
  if(!it) return;
  const f = fshInv();
  if(f.items[id]) return;                      // one of each is plenty
  if(state.credits < it.price) return;
  state.credits -= it.price;
  f.items[id] = 1;
  if(!f.equipped[it.slot]) f.equipped[it.slot] = id;   // auto-equip an empty slot
  saveState(); renderHeader(); renderTackleShop(); renderEquipment(); renderFishingStats();
  showToast(`🎣 Bought ${it.name}${f.equipped[it.slot]===id ? " — equipped." : "."}`);
}
function fshEquip(slot, id){
  const f = fshInv();
  if(id && !fshOwns(id)) return;
  f.equipped[slot] = id || null;
  saveState(); renderEquipment(); renderFishingStats(); renderTackleShop();
}
function fshBuyBait(id){
  const b = fshBait(id);
  if(!b || state.credits < b.price) return;
  state.credits -= b.price;
  const f = fshInv();
  f.bait[id] = (f.bait[id]||0) + b.bundle;
  if(!f.activeBait || !(f.bait[f.activeBait]>0)) f.activeBait = id;
  saveState(); renderHeader(); renderTackleShop(); renderEquipment(); renderFishingStats();
}
function fshSetBait(id){
  const f = fshInv();
  if(id && !(f.bait[id] > 0)) return;
  f.activeBait = id || null;
  saveState(); renderEquipment(); renderFishingStats(); fshRenderControls();
}
function fshBuyCharm(id){
  const c = fshCharm(id);
  if(!c || state.credits < c.price) return;
  state.credits -= c.price;
  const f = fshInv();
  f.charms[id] = (f.charms[id]||0) + 1;
  saveState(); renderHeader(); renderTackleShop(); renderEquipment();
}
function fshUseCharm(id){
  const c = fshCharm(id);
  const f = fshInv();
  if(!c || !(f.charms[id] > 0)) return;
  f.charms[id]--;
  f.active[id] = (f.active[id]||0) + c.casts;
  saveState(); renderEquipment(); renderFishingStats(); renderTackleShop();
  showToast(`${c.icon} ${c.name} active for ${f.active[id]} casts.`);
}
/* Burn one cast off every running charm, and one bait off the spool. */
function fshConsumeOnCast(){
  const f = fshInv();
  let baitUsed = false;
  if(f.activeBait && f.bait[f.activeBait] > 0){
    const keepChance = fshSkillTier("bait") * 0.12;
    if(Math.random() >= keepChance){ f.bait[f.activeBait]--; baitUsed = true; }
    if(f.bait[f.activeBait] <= 0){
      delete f.bait[f.activeBait];
      const next = FSH_BAIT.slice().reverse().find(b=>f.bait[b.id] > 0);
      f.activeBait = next ? next.id : null;
      if(!next) showToast("🪱 Out of bait — you're fishing a bare hook now.");
    }
  }
  for(const k of Object.keys(f.active)){
    f.active[k]--;
    if(f.active[k] <= 0) delete f.active[k];
  }
  saveState();
  renderEquipment();
  return baitUsed;
}

/* ---- Everything the angler is worth, added up ---- */
function fshStats(){
  const f = fshInv();
  const sk = k => (f.skills && f.skills[k]) || 0;
  const acc = { cast:0, pull:0, tension:0, recover:0, strain:0, window:0, speed:0, luck:0, loot:0, calm:0 };
  const add = (st, mul)=>{ if(!st) return; for(const k in st) if(k in acc) acc[k] += st[k]*(mul===undefined?1:mul); };

  // equipped gear
  for(const s of FSH_EQ_SLOTS){ const it = fshEquippedItem(s.key); if(it) add(it.stats); }
  // bait on the hook (or the penalty for none)
  const bait = f.activeBait && f.bait[f.activeBait] > 0 ? fshBait(f.activeBait) : null;
  add(bait ? bait.stats : FSH_NO_BAIT);
  // charms currently running
  for(const id in f.active){ const c = fshCharm(id); if(c) add(c.stats); }
  // permanent training
  acc.cast    += sk("rod")*6;
  acc.pull    += sk("rod")*0.6 + sk("reel")*2.2 + sk("outfit")*0.4;
  acc.tension += sk("line")*18;
  acc.window  += sk("hook")*0.3;
  acc.speed   += (1 - Math.pow(0.93, sk("bait")))*100;
  acc.luck    += sk("lure")*0.55 + sk("outfit")*0.1;
  acc.loot    += sk("box")*14 + sk("outfit")*3;
  acc.recover += sk("gloves")*3.5;
  acc.strain  += sk("gloves")*0.22*4.5;

  return {
    raw: acc,
    bait,
    castBonus:    1 + acc.cast/100,
    tapPower:     Math.max(2, 6 + acc.pull),
    maxTension:   Math.max(40, Math.round(100 + acc.tension)),
    tensionDecay: Math.max(6, 16 + acc.recover),
    tensionPerTap:Math.max(2.4, 7.5 * (1 - Math.min(0.75, acc.strain/100))),
    hookWindow:   Math.max(700, 1400 + acc.window*1000),
    biteMult:     Math.max(0.25, 1 - Math.min(0.8, acc.speed/100)),
    luck:         Math.max(0, acc.luck),
    lootMult:     Math.max(0.5, 1 + acc.loot/100),
    calm:         Math.min(1, Math.max(0, acc.calm/100)),   // 1 = the fish never runs
  };
}
function fshGearScore(){
  const f = fshInv();
  let n = 0;
  for(const s of FSH_EQ_SLOTS){ const it = fshEquippedItem(s.key); if(it) n += it.q; }
  return n;
}
function fshSkillScore(){
  const f = fshInv();
  return FSH_SKILLS.reduce((a,s)=>a + ((f.skills && f.skills[s.key])||0), 0);
}
/* The coat you're wearing is the coat he's drawn in. */
function fshOutfitIndex(){
  const it = fshEquippedItem("coat");
  return it ? Math.min(FSH_OUTFITS.length-1, it.q) : 0;
}
/* ---------------- FISHING: TRAINING PANEL (Upgrades tab) ---------------- */
function renderAnglerTraining(){
  const grid = document.getElementById("anglerGrid");
  if(!grid) return;
  if(!state.fishing) state.fishing = defaultFishing();
  const playerLevel = (state.player && state.player.level) || 1;
  grid.innerHTML = "";
  FSH_SKILLS.forEach(skill=>{
    const tier = fshSkillTier(skill.key);
    const maxed = tier >= FSH_MAX_TIER;
    const next = maxed ? null : tier+1;
    const cost = maxed ? 0 : fshSkillCost(skill, next);
    const needLvl = maxed ? 0 : FSH_TIER_LEVEL[next];
    const locked = !maxed && playerLevel < needLvl;
    const afford = !maxed && !locked && state.credits >= cost;
    const el = document.createElement("div");
    el.className = "upgrade-card" + (maxed ? " maxed" : "") + (locked ? " empire-locked" : "");
    el.innerHTML = `
      <div class="uhead">
        <div class="uicon">${skill.icon}</div>
        <div>
          <div class="utitle">${skill.name}</div>
          <div class="ulevel">${maxed ? "MAX LEVEL" : `Level ${tier} / ${FSH_MAX_TIER}`}</div>
        </div>
      </div>
      <div class="udesc">${skill.effect}</div>
      <div class="ueffect">${tier ? "Current: "+skill.stat(tier) : "Not trained yet"}${maxed ? "" : `<br><span style="color:var(--good);">Next: ${skill.stat(next)}</span>`}</div>
      <div class="uprogress"><div style="width:${tier/FSH_MAX_TIER*100}%"></div></div>
      <div class="ubuy">
        ${maxed ? `<span class="ucost" style="color:var(--good);">Fully trained</span>`
          : locked ? `<span class="ucost">🔒 Unlocks at Level ${needLvl}</span>`
          : `<span class="ucost">${cost.toLocaleString()} 🪙</span>
             <button class="btn ${afford ? "" : "secondary"}" ${afford ? "" : "disabled"}>${afford ? "Train" : "Need Credits"}</button>`}
      </div>`;
    if(!maxed && !locked && afford) el.querySelector("button").addEventListener("click", ()=>fshBuySkill(skill.key));
    grid.appendChild(el);
  });
}

/* ---------------- FISHING: TACKLE SHOP (Market tab) ---------------- */
let tackleTab = "rod";
function setTackleTab(k){ tackleTab = k; renderTackleShop(); }
/* The top item in a slot, by quality first and price as the tiebreak. */
function fshSlotBest(slotKey){
  const items = FSH_ITEMS.filter(i=>i.slot === slotKey);
  if(!items.length) return null;
  return items.slice().sort((a,b)=>((b.q||0)-(a.q||0)) || ((b.price||0)-(a.price||0)))[0];
}
/* Own the best rod there is and the Rods tab has nothing left to sell you. */
function fshSlotDone(slotKey){
  const best = fshSlotBest(slotKey);
  return !!best && fshOwns(best.id);
}
function fshStatLine(stats){
  const L = {
    cast:v=>`+${v}% cast distance`, pull:v=>`+${v} reel power`, tension:v=>`+${v} max tension`,
    recover:v=>`+${v} tension recovery`, strain:v=>`−${v}% reel strain`, window:v=>`+${v}s bite window`,
    speed:v=> v>=0 ? `−${v}% wait for a bite` : `+${-v}% wait for a bite`,
    luck:v=> v>=0 ? `+${v} catch luck` : `${v} catch luck`, loot:v=>`+${v}% catch value`,
    calm:v=>`−${v}% chance the fish runs`,
  };
  return Object.entries(stats).map(([k,v])=>L[k] ? L[k](v) : `${k} ${v}`).join(" · ");
}
function renderTackleShop(){
  if(!document.getElementById("tackleShop")) return;   /* the shop lives in the fishing modal now */
  const wrap = document.getElementById("tackleShop");
  if(!wrap) return;
  if(!state.fishing) state.fishing = defaultFishing();
  const f = state.fishing;
  const tabs = FSH_EQ_SLOTS.filter(s=>!fshSlotDone(s.key))
    .map(s=>({key:s.key, label:s.icon+" "+s.name}))
    .concat([{key:"bait", label:"🪱 Bait"},{key:"charm", label:"🍀 Charms"}]);
  /* Standing on a tab that just retired? Slide over to the first one left. */
  if(!tabs.some(t=>t.key === tackleTab)) tackleTab = tabs[0].key;
  const bar = tabs.map(t=>`<button class="tk-tab ${tackleTab===t.key?"on":""}" data-k="${t.key}">${t.label}</button>`).join("");

  let body = "";
  if(tackleTab === "bait"){
    body = `<div class="tk-grid">` + FSH_BAIT.map(b=>{
      const have = f.bait[b.id]||0;
      const afford = state.credits >= b.price;
      return `<div class="tk-item">
        <div class="tk-h"><span class="tk-ic">${b.icon}</span><span class="tk-n">${b.name}</span>
          <span class="tk-q" style="color:#8fae7a; border-color:#8fae7a55;">Bait</span></div>
        <div class="tk-s">${fshStatLine(b.stats)}</div>
        <div class="tk-f">One used per cast. You have <b>${have.toLocaleString()}</b>.</div>
        <div class="tk-b"><span class="tk-p">${b.price.toLocaleString()} 🪙 / ${b.bundle}</span>
          <button class="btn ${afford?"":"secondary"}" ${afford?"":"disabled"} data-bait="${b.id}">Buy ${b.bundle}</button></div>
      </div>`;
    }).join("") + `</div>`;
  } else if(tackleTab === "charm"){
    body = `<div class="tk-grid">` + FSH_CHARMS.map(c=>{
      const have = f.charms[c.id]||0;
      const afford = state.credits >= c.price;
      return `<div class="tk-item">
        <div class="tk-h"><span class="tk-ic">${c.icon}</span><span class="tk-n">${c.name}</span>
          <span class="tk-q" style="color:#ffcf40; border-color:#ffcf4055;">Charm</span></div>
        <div class="tk-s">${c.blurb}</div>
        <div class="tk-f">Lasts ${c.casts} casts. You hold <b>${have}</b>.</div>
        <div class="tk-b"><span class="tk-p">${c.price.toLocaleString()} 🪙</span>
          <button class="btn ${afford?"":"secondary"}" ${afford?"":"disabled"} data-charm="${c.id}">Buy</button></div>
      </div>`;
    }).join("") + `</div>`;
  } else {
    const slot = fshEqSlot(tackleTab);
    const items = FSH_ITEMS.filter(i=>i.slot===tackleTab);
    body = `<div class="tk-slotnote">${slot.icon} <b>${slot.name}</b> — ${slot.blurb}</div><div class="tk-grid">` +
      items.map(i=>{
        const owned = fshOwns(i.id);
        const eq = fshEquipped(i.slot) === i.id;
        const afford = state.credits >= i.price;
        const q = FSH_QUALITY[i.q];
        return `<div class="tk-item ${owned?"owned":""}">
          <div class="tk-h"><span class="tk-ic">${i.icon}</span><span class="tk-n">${i.name}</span>
            <span class="tk-q" style="color:${q.color}; border-color:${q.color}55;">${q.name}</span></div>
          <div class="tk-s">${fshStatLine(i.stats)}</div>
          <div class="tk-f">${i.flavor}</div>
          <div class="tk-b">
            ${owned
              ? (eq ? `<span class="tk-p" style="color:var(--good);">✓ Equipped</span>`
                    : `<span class="tk-p" style="color:var(--muted);">Owned</span><button class="btn secondary" data-equip="${i.id}">Equip</button>`)
              : `<span class="tk-p">${i.price.toLocaleString()} 🪙</span>
                 <button class="btn ${afford?"":"secondary"}" ${afford?"":"disabled"} data-buy="${i.id}">Buy</button>`}
          </div>
        </div>`;
      }).join("") + `</div>`;
  }
  wrap.innerHTML = `<div class="tk-tabs">${bar}</div>${body}`;
  wrap.querySelectorAll(".tk-tab").forEach(b=>b.addEventListener("click",()=>setTackleTab(b.dataset.k)));
  wrap.querySelectorAll("[data-buy]").forEach(b=>b.addEventListener("click",()=>fshBuyItem(b.dataset.buy)));
  wrap.querySelectorAll("[data-equip]").forEach(b=>b.addEventListener("click",()=>{ const it=fshItem(b.dataset.equip); fshEquip(it.slot,it.id); }));
  wrap.querySelectorAll("[data-bait]").forEach(b=>b.addEventListener("click",()=>fshBuyBait(b.dataset.bait)));
  wrap.querySelectorAll("[data-charm]").forEach(b=>b.addEventListener("click",()=>fshBuyCharm(b.dataset.charm)));
}

/* ---------------- FISHING: EQUIPMENT SCREEN (Fishing tab) ---------------- */
let eqPicker = null;
function fshOpenPicker(slot){ eqPicker = (eqPicker===slot) ? null : slot; renderEquipment(); }
function renderEquipment(){
  const wrap = document.getElementById("fshEquip");
  if(!wrap) return;
  if(!state.fishing) state.fishing = defaultFishing();
  const f = state.fishing;
  const st = fshStats();

  const slots = FSH_EQ_SLOTS.map(s=>{
    const it = fshEquippedItem(s.key);
    const q = it ? FSH_QUALITY[it.q] : null;
    return `<button class="eq-slot ${it?"filled":""} ${eqPicker===s.key?"open":""}" data-slot="${s.key}"
              ${it?`style="border-color:${q.color}66;"`:""}>
      <span class="eq-si">${it ? it.icon : s.icon}</span>
      <span class="eq-sn">${s.name}</span>
      <span class="eq-sv" ${it?`style="color:${q.color}"`:""}>${it ? it.name : "empty"}</span>
    </button>`;
  }).join("");

  let picker = "";
  if(eqPicker){
    const slot = fshEqSlot(eqPicker);
    const owned = FSH_ITEMS.filter(i=>i.slot===eqPicker && fshOwns(i.id));
    picker = `<div class="eq-picker">
      <div class="eq-ph">${slot.icon} ${slot.name} — ${slot.blurb}</div>
      ${owned.length ? owned.map(i=>{
        const q = FSH_QUALITY[i.q], on = fshEquipped(eqPicker)===i.id;
        return `<button class="eq-opt ${on?"on":""}" data-pick="${i.id}">
          <span class="ic">${i.icon}</span>
          <span class="tx"><b style="color:${q.color}">${i.name}</b><br><span class="st">${fshStatLine(i.stats)}</span></span>
          <span class="mk">${on?"✓":""}</span></button>`;
      }).join("") : `<div class="eq-empty">Nothing for this slot yet — the Tackle Shop in the Market sells them.</div>`}
      ${fshEquipped(eqPicker) ? `<button class="eq-opt clear" data-pick="">Take it off</button>` : ""}
    </div>`;
  }

  const baitRows = FSH_BAIT.filter(b=>(f.bait[b.id]||0) > 0).map(b=>{
    const on = f.activeBait === b.id;
    return `<button class="eq-bait ${on?"on":""}" data-bait="${b.id}">
      <span class="ic">${b.icon}</span><span class="nm">${b.name}</span>
      <span class="ct">×${(f.bait[b.id]||0).toLocaleString()}</span>${on?`<span class="on-tag">on the hook</span>`:""}
    </button>`;
  }).join("");

  const charmRows = FSH_CHARMS.map(c=>{
    const have = f.charms[c.id]||0, live = f.active[c.id]||0;
    if(!have && !live) return "";
    return `<div class="eq-charm ${live?"live":""}">
      <span class="ic">${c.icon}</span>
      <span class="tx"><b>${c.name}</b><br><span class="st">${live ? `Active — ${live} cast${live===1?"":"s"} left` : c.blurb}</span></span>
      ${have ? `<button class="btn secondary" data-charm="${c.id}">Use (${have})</button>` : ""}
    </div>`;
  }).join("");

  wrap.innerHTML = `
    <div class="eq-grid">${slots}</div>
    ${picker}
    <div class="eq-sec">🪱 Bait <span class="eq-hint">one used per cast</span></div>
    ${baitRows || `<div class="eq-empty">No bait. You can still fish, but bites come slower and the good stuff stays away.</div>`}
    ${f.activeBait ? "" : `<div class="eq-warn">⚠️ Fishing a bare hook — ${fshStatLine(FSH_NO_BAIT)}</div>`}
    ${charmRows ? `<div class="eq-sec">🍀 Charms</div>${charmRows}` : ""}
    <div class="eq-sec">📋 Everything, added up</div>
    <div class="fsh-derived">
      <span>Reel power <b>${(st.tapPower*1.55).toFixed(1)}</b>/s held</span>
      <span>Max tension <b>${st.maxTension}</b></span>
      <span>Recovery <b>${st.tensionDecay.toFixed(1)}</b>/s</span>
      <span>Drag load <b>${(30 + st.tapPower*0.75).toFixed(0)}</b> held</span>
      <span>Bite window <b>${(st.hookWindow/1000).toFixed(2)}s</b></span>
      <span>Wait <b>×${st.biteMult.toFixed(2)}</b></span>
      <span>Cast <b>×${st.castBonus.toFixed(2)}</b></span>
      <span>Luck <b>+${st.luck.toFixed(2)}</b></span>
      <span>Value <b>×${st.lootMult.toFixed(2)}</b></span>
      <span>Fish runs <b>${Math.round((1-st.calm)*100)}%</b> as often</span>
    </div>`;

  wrap.querySelectorAll("[data-slot]").forEach(b=>b.addEventListener("click",()=>fshOpenPicker(b.dataset.slot)));
  wrap.querySelectorAll("[data-pick]").forEach(b=>b.addEventListener("click",()=>{ fshEquip(eqPicker, b.dataset.pick || null); eqPicker=null; renderEquipment(); }));
  wrap.querySelectorAll("[data-bait]").forEach(b=>b.addEventListener("click",()=>fshSetBait(b.dataset.bait)));
  wrap.querySelectorAll("[data-charm]").forEach(b=>b.addEventListener("click",()=>fshUseCharm(b.dataset.charm)));
}


/* ---------------- FISHING: REALISTIC CATCH PHOTOS ----------------
   Every catch gets a real photograph on the result card, looked up by name from
   the same archive the card inspector uses (and sharing its cache). Fantasy and
   ambiguous catches map to their closest real-world cousin below. The lookup is
   kicked off the moment the fish bites, so by the time you've reeled it in the
   photo is almost always already here. */
const FSH_PIC_ALIAS = {
  "Old Boot":"Wellington boot", "Rusty Can":"Steel and tin cans", "Tangled Seaweed":"Seaweed",
  "Soggy Newspaper":"Newspaper", "Someone's Sunglasses":"Sunglasses",
  "Little Sunfish":"Bluegill", "Creek Chub":"Creek chub", "Pond Snail":"Lymnaeidae",
  "River Roach":"Common roach", "Rainbow Darter":"Rainbow darter", "Lake Herring":"Cisco (fish)",
  "Spot Croaker":"Spot (fish)", "Crayfish":"Crayfish", "Brook Silverside":"Brook silverside",
  "Silver Bream":"Silver bream", "Sea Bream":"Gilt-head bream", "Porgy":"Sparidae",
  "Sauger":"Sauger", "Blue Crab":"Chesapeake blue crab",
  "Lake Muskie":"Muskellunge", "Tiger Muskie":"Tiger muskellunge", "Steelhead":"Rainbow trout",
  "King Salmon":"Chinook salmon", "Snakehead":"Snakehead (fish)", "Rock Octopus":"Octopus",
  "Reef Squid":"Caribbean reef squid", "Pufferfish":"Tetraodontidae", "Porcupinefish":"Porcupinefish",
  "Mahi-Mahi":"Mahi-mahi", "Great Barracuda":"Great barracuda",
  "Giant Tarpon":"Tarpon", "Goliath Grouper":"Atlantic goliath grouper", "Giant Trevally":"Giant trevally",
  "Pacific Halibut":"Pacific halibut", "Giant Squid":"Giant squid", "Beluga Sturgeon":"Beluga (sturgeon)",
  "King Mackerel":"King mackerel",
  "Golden Koi":"Koi", "Ghost Koi":"Koi", "Moonlit Eel":"European eel",
  "The Old Man of the Lake":"Wels catfish", "Silverscale Leviathan":"Oarfish",
  "Abyssal Anglerfish":"Anglerfish", "Kraken Hatchling":"Giant Pacific octopus",
  "Megalodon Pup":"Megalodon", "Rainbow Serpent Eel":"Moray eel",
  "Frost Whale Calf":"Beluga whale", "Thunderfin Marlin":"Atlantic blue marlin",
  "Colossal Squid":"Colossal squid", "Great White Shark":"Great white shark",
  "Sunken Chest":"Treasure hunting", "Message in a Bottle":"Message in a bottle",
  "Ship's Bell":"Ship's bell", "Pearl Oyster":"Pinctada", "Old Coin Purse":"Coin purse",
  "Doubloon Stack":"Doubloon", "Ancient Amphora":"Amphora", "Ruby Ring":"Ruby",
  "Bronze Trident":"Trident", "Captain's Spyglass":"Spyglass", "Treasure Map":"Treasure map",
  "Jeweled Chalice":"Chalice", "Seer's Orb":"Crystal ball",
  "Gold Pocket Watch":"Pocket watch", "Pearl Necklace":"Pearl", "Silver Goblet":"Chalice",
  "Jade Figurine":"Chinese jade", "Antique Sextant":"Sextant",
  "Drowned King's Crown":"Crown", "Flawless Diamond":"Diamond", "Emerald Dagger":"Dagger",
  "Gilded Opera Mask":"Venetian mask", "Meteorite Shard":"Meteorite",
};
function fshPicSubject(name){ return FSH_PIC_ALIAS[name] || name; }
function fshPrefetchPic(name){ if(!name) return; try{ ciLookup(fshPicSubject(name)); }catch(e){} }
let fshPicToken = 0;
function fshLoadResultPhoto(r){
  if(r.failed || !r.title) return;
  const token = ++fshPicToken;
  ciLookup(fshPicSubject(r.title)).then(entry=>{
    if(token !== fshPicToken) return;
    const ph = document.getElementById("fshResultPhoto");
    if(!ph || !entry || !entry.img) return;
    ph.innerHTML = `<img src="${entry.img}" alt="${r.title}">
      <span class="rPhotoIcon">${r.icon || ""}</span>`;
    const im = ph.querySelector("img");
    if(im) im.addEventListener("error", ()=>{
      ph.innerHTML = `<div class="rIcon">${r.icon || "🎣"}</div>`;
    });
  });
}

