/* ---------------- Relics & Curses ---------------- */
const RD_RELICS = [
  { id:"compass",  icon:"🧭", name:"Gilded Compass",    desc:"Vault treasure +20%.",                       curse:"Gambles succeed 5% less often." },
  { id:"skull",    icon:"💀", name:"Whispering Skull",  desc:"Gamble odds +10%.",                          curse:"Ghost chambers cost double." },
  { id:"flask",    icon:"🍶", name:"Bottomless Flask",  desc:"+2 stamina after every chamber.",            curse:null },
  { id:"tooth",    icon:"🦷", name:"Wyrm Tooth",        desc:"+1 damage against guardians.",               curse:"Guardians hit 2 harder." },
  { id:"candle",   icon:"🕯️", name:"Unsleeping Candle", desc:"Dark crossings cost nothing.",               curse:null },
  { id:"coin",     icon:"🪙", name:"Two-Headed Coin",   desc:"Your first failed gamble is refunded.",      curse:null },
  { id:"idol",     icon:"🗿", name:"Jade Idol",         desc:"Strange events find you twice as often.",    curse:"…all of them do." },
  { id:"hourglass",icon:"⏳", name:"Cracked Hourglass", desc:"Masterstrokes: 30% (up from 18%).",          curse:"Masterstrokes no longer refund stamina." },
  { id:"bellows",  icon:"🌬️", name:"Ember Bellows",     desc:"Smelting yields +1 bar.",                    curse:null },
  { id:"chain",    icon:"⛓️", name:"Saint's Chain",     desc:"Cheat death once: snap back to 10⚡.",       curse:null },
  { id:"lens",     icon:"🔍", name:"Appraiser's Lens",  desc:"Credit finds +30%.",                         curse:null },
  { id:"drum",     icon:"🥁", name:"War Drum",          desc:"Guardian blows land 2 softer.",              curse:null },
];
function rdRelic(id){ return !!(rd && rd.relics && rd.relics.includes(id)); }
function rdRelicDef(id){ return RD_RELICS.find(r=>r.id===id); }
function rdUnownedRelics(){ return RD_RELICS.filter(r=>!rdRelic(r.id)).map(r=>r.id); }
function rdGrantRelic(id){
  const R = rdRelicDef(id);
  if(!R || rdRelic(id) || rd.relics.length >= 4) return false;
  rd.relics.push(id);
  rdLog(`🏺 <b>${R.icon} ${R.name}.</b> ${R.desc}${R.curse ? ` <i style="color:#ff9d6e">But: ${R.curse}</i>` : ""}`);
  return true;
}

/* ---------------- Vault Guardians ---------------- */
const RD_GUARDIANS = {
  mine:     { icon:"🐛", name:"The Tunnel Wyrm",      hp:3, min:5, max:8,  intro:"The floor bulges and splits. The good ore was bait all along." },
  temple:   { icon:"🗿", name:"The Stone Sentinel",   hp:4, min:6, max:9,  intro:"A statue you already walked past is standing behind you now." },
  galleon:  { icon:"🧜", name:"The Drowned Captain",  hp:4, min:6, max:10, intro:"The captain rises from the vault stair, still in his hat. He tips it. Then he draws." },
  reliquary:{ icon:"🛡️", name:"The Reliquary Warden", hp:5, min:7, max:10, intro:"Frost-forged armor with nothing inside it. Mostly nothing." },
  sanctum:  { icon:"🦾", name:"The Prime Automaton",  hp:5, min:8, max:12, intro:"The oldest machine unfolds from the wall. It has waited centuries for a visitor. You are late." },
  hoard:    { icon:"🐲", name:"The Hoard-Warden Drake",hp:6, min:8, max:12, intro:"Not THE dragon — its favorite child. This is not an improvement." },
};
const RD_DEPTH_GUARDS = [
  { icon:"🕷️", name:"The Broodmother" }, { icon:"👁️", name:"The Unblinking" },
  { icon:"🗿", name:"The Forgotten Colossus" }, { icon:"🐍", name:"The Coiled Dark" },
];
function rdGuardTele(def){
  let n = def.min + Math.floor(Math.random()*(def.max - def.min + 1));
  if(rdRelic("drum")) n = Math.max(3, n - 2);
  if(rdRelic("tooth")) n += 2;
  return n;
}
function rdSpawnGuardian(def, after){
  rd.guardian = { def, hp:def.hp, maxHp:def.hp, next:rdGuardTele(def), braced:false, round:1, after };
  rdLog(`⚔️ <b>${def.icon} ${def.name}.</b> ${def.intro || "It bars the way, and it is not in a bargaining mood."}`);
}
function rdDepthGuardian(depth){
  const base = RD_DEPTH_GUARDS[Math.floor(Math.random()*RD_DEPTH_GUARDS.length)];
  return { icon:base.icon, name:`${base.name} of Floor ${depth}`,
    hp: 3 + Math.floor(depth/3), min: 5 + Math.ceil(depth*0.5), max: 8 + Math.ceil(depth*0.7),
    intro:"Something below has noticed the noise you make." };
}
function rdGuardOptions(){
  const c = rd.caps, o = [];
  const pickName = c.pick===5 ? "The Worldsplitter" : ["","Rusty Pickaxe","Iron Pickaxe","Steel Pickaxe","Dwarven Pickaxe"][c.pick];
  if(c.pick > 0) o.push({ label:"⛏️ Pickaxe strike", flavor:"Aim for the joints.", kind:"mine",
    cost:3, wear:pickName, dmg:1, stamp:"HIT −1", log:"You land a ringing blow where it hates it." });
  if(c.hammer) o.push({ label:"🔨 Full hammer swing", flavor:"Wind up. Follow through.", kind:"forge",
    cost:5, wear:"Forge Hammer", dmg:2, stamp:"CRUNCH −2", log:"The hammer speaks with authority." });
  if(c.powder > 0) o.push({ label:"💥 Blasting powder", flavor:"Negotiations, concluded.", kind:"blast",
    cost:1, consume:"Blasting Powder", dmg:3, stamp:"BOOM −3", log:"The blast staggers it badly." });
  if(rd.res.bars > 0) o.push({ label:"🧱 Hurl an iron bar", flavor:"Expensive ammunition. Effective ammunition.", kind:"forge",
    cost:2, gain:{barSpend:1}, dmg:2, stamp:"CLANG −2", log:"The bar hits like a fired cannonball." });
  if(c.smoke > 0) o.push({ label:"💨 Smoke bomb — slip past it", flavor:"You came for the vault, not the glory.", kind:"walk",
    cost:0, consume:"Smoke Bomb", skip:true, stamp:"VANISHED", log:"When the smoke clears, you are already inside the vault. It is still growling at the door." });
  o.push({ label:"🫳 Improvised assault", flavor:"Rocks. Fists. Strong language.", kind:"walk",
    cost:6, risk:{ chance:0.6, failCost:4, failStamp:"IT SHRUGS", failLog:"Your best rock bounces off with a sad tik." },
    dmg:1, stamp:"SCRAPPY −1", log:"You find a soft spot the hard way." });
  o.push({ label:"🛡️ Brace for the blow", flavor:"Set your feet. Halve the next hit.", kind:"climb",
    cost:2, brace:true, stamp:"BRACED", log:"You plant yourself and take it on the pack frame." });
  return o;
}

