/* ================= The Mythic Forge =================
   Credits buy a rite. The rite is a roll — you know the band, never the number —
   and whatever it lands on is welded to you permanently, across every floor. */
const MR_ROLLS = [
  { id:"iron",   name:"Whisper of Iron",   icon:"🗡️", cost:1e6,  min:1,  max:3,
    blurb:"A smith who does not give her name puts an edge on everything you will ever hold." },
  { id:"ember",  name:"Ember Rite",        icon:"🔥", cost:1e7,  min:4,  max:8,
    blurb:"They bank the forge with something that was alive. It takes." },
  { id:"storm",  name:"Storm Covenant",    icon:"⚡", cost:1e8,  min:10, max:18,
    blurb:"Signed in a room with no ceiling, during weather that was not weather." },
  { id:"drake",  name:"Dragonbone Pact",   icon:"🐉", cost:1e9,  min:26, max:42,
    blurb:"The Hoard-Warden's kin keep ledgers. You are now in one." },
  { id:"accord", name:"The Mythic Accord", icon:"🌌", cost:1e12, min:80, max:130,
    blurb:"Daemonheim agrees to stop arguing with you. The terms are not written down." },
];
function fmtBig(n){
  if(typeof n !== "number" || !isFinite(n)) return "\u221e";
  if(n < 0) return "-" + fmtBig(-n);
  /* The Mythic Accord costs a trillion a pull, so balances run well past what
     "trillion" can label. Keep naming them instead of printing "1000 trillion". */
  const u = (d, name)=> (n/d).toFixed(n % d ? 1 : 0).replace(/\.0$/,"") + " " + name;
  if(n >= 1e18) return u(1e18, "quintillion");
  if(n >= 1e15) return u(1e15, "quadrillion");
  if(n >= 1e12) return u(1e12, "trillion");
  if(n >= 1e9)  return u(1e9,  "billion");
  if(n >= 1e6)  return u(1e6,  "million");
  return n.toLocaleString();
}
function mrMight(){ const S = dgSave(); return (typeof S.might === "number" && isFinite(S.might)) ? S.might : 0; }
function mrRollCount(id){ const S = dgSave(); return (S.rolls && S.rolls[id]) || 0; }
function mrBuyRoll(id){
  const R = MR_ROLLS.find(r=>r.id === id);
  if(!R) return;
  const S = dgSave();
  if(state.credits < R.cost){ showToast("Not enough credits for that rite."); return; }
  if(S.rolling && !S.rolling.done) return;
  state.credits -= R.cost;
  const gained = R.min + Math.floor(Math.random() * (R.max - R.min + 1));
  S.rolls = S.rolls || {};
  S.rolls[id] = (S.rolls[id] || 0) + 1;
  /* the gain is banked the instant you pay — the spin below is only theatre,
     so a reload or a closed tab can never eat the rite you bought */
  S.might = mrMight() + gained;
  S.rolling = { id, gained, shown: R.min, done:false };
  saveState(); renderHeader(); renderDungeon();
  /* spin the number for a moment before it settles */
  const started = Date.now();
  const tick = ()=>{
    const S2 = dgSave();
    if(!S2.rolling || S2.rolling.id !== id) return;
    const t = (Date.now() - started) / 1100;
    if(t >= 1){
      S2.rolling.shown = gained;
      S2.rolling.done = true;
      saveState(); renderDungeon();
      setTimeout(()=>{ const S3 = dgSave(); if(S3.rolling && S3.rolling.done){ S3.rolling = null; saveState(); renderDungeon(); } }, 2600);
      return;
    }
    S2.rolling.shown = R.min + Math.floor(Math.random()*(R.max - R.min + 1));
    renderDungeon();
    setTimeout(tick, 60 + t*140);
  };
  setTimeout(tick, 80);
}

/* ---- what you are actually wearing adds up to this ---- */
function mrBon(){
  const B = { dmg:0, arm:0, crit:0, gather:0, healBonus:0, coinFind:0, dodge:0,
              lifeMax:0, lifesteal:0, haggle:0, puzzleGrace:0,
              styleDmg:{melee:0,ranged:0,magic:0},
              doorGrace:false, senseKeys:false, senseAll:false, wardPierce:false, noSlip:false };
  if(!dg) return B;
  const add = st=>{
    if(!st) return;
    ["dmg","arm","crit","gather","healBonus","coinFind","dodge","lifeMax","lifesteal","haggle","puzzleGrace"]
      .forEach(k=>{ if(st[k]) B[k] += st[k]; });
    ["doorGrace","senseKeys","senseAll","wardPierce","noSlip"].forEach(k=>{ if(st[k]) B[k] = true; });
    if(st.styleDmg) Object.keys(st.styleDmg).forEach(k=>{ B.styleDmg[k] += st.styleDmg[k]; });
    if(st.tool) dg.tools[st.tool] = true;
  };
  const counts = {};
  MR_SLOTS.forEach(sl=>{
    const it = dg.equip && dg.equip[sl];
    if(!it) return;
    add(it.stats);
    if(it.set) counts[it.set] = (counts[it.set]||0) + 1;
  });
  Object.keys(counts).forEach(sid=>{
    const set = mrSet(sid); if(!set) return;
    const n = counts[sid];
    if(n >= 2) add(set.b2);
    if(n >= 3) add(set.b3);
    if(n >= 5) add(set.b5);
  });
  /* whatever the Forge welded on, on every floor, forever */
  B.dmg += mrMight() / 100;
  /* temporary food effects */
  (dg.buffs || []).forEach(b=>{
    if(b.turns <= 0) return;
    if(b.buffDmg) B.dmg += b.buffDmg;
    if(b.buffCrit) B.crit += b.buffCrit;
    if(b.armTemp) B.arm += b.armTemp;
    if(b.healBonusTemp) B.healBonus += b.healBonusTemp;
    if(b.dodgeTemp) B.dodge += b.dodgeTemp;
  });
  return B;
}
function mrSetCounts(){
  const c = {};
  if(!dg || !dg.equip) return c;
  MR_SLOTS.forEach(sl=>{ const it = dg.equip[sl]; if(it && it.set) c[it.set] = (c[it.set]||0)+1; });
  return c;
}
function mrTickBuffs(){
  if(!dg || !dg.buffs) return;
  dg.buffs.forEach(b=>{ b.turns--; });
  const gone = dg.buffs.filter(b=>b.turns === 0);
  dg.buffs = dg.buffs.filter(b=>b.turns > 0);
  gone.forEach(b=>dgLog(`The ${b.name} wears off.`));
}
/* ---- finding things ---- */
function mrRollItem(floorTier, luck){
  const pool = MR_ITEM_LIST.filter(it=>it.kind !== "food" && (it.drop||1) <= floorTier + 1 + (luck?1:0));
  if(!pool.length) return null;
  return pool[Math.floor(Math.random()*pool.length)];
}
function mrRollFood(){
  const pool = MR_ITEM_LIST.filter(it=>it.kind === "food");
  return pool[Math.floor(Math.random()*pool.length)];
}
function mrGive(item, quiet){
  if(!dg) return;
  dg.bag = dg.bag || [];
  dg.bag.push(item);
  if(!quiet) dgLog(`${item.icon} You find <b>${item.name}</b>${item.secret?" — a secret recipe":""}.`);
  /* auto-equip anything strictly better and not competing with a set you are building */
  if(item.slot && !dg.equip[item.slot]) mrEquip(dg.bag.length-1, true);
  else if(item.kind === "weapon" && dg.equip.weapon && item.dmg > dg.equip.weapon.dmg) mrEquip(dg.bag.length-1, true);
}
function mrEquip(bagIdx, quiet){
  const it = dg.bag[bagIdx];
  if(!it || !it.slot) return;
  const old = dg.equip[it.slot];
  dg.equip[it.slot] = it;
  dg.bag.splice(bagIdx, 1);
  if(old) dg.bag.push(old);
  if(it.kind === "weapon" && it.style) dg.gear.style = it.style;
  const B = mrBon();
  dg.maxHp = dg.baseHp + B.lifeMax;
  dg.hp = Math.min(dg.hp, dg.maxHp);
  if(!quiet) dgLog(`${it.icon} You put on the <b>${it.name}</b>.`);
}
function mrEatItem(bagIdx){
  const it = dg.bag[bagIdx];
  if(!it || it.kind !== "food") return;
  dg.bag.splice(bagIdx, 1);
  const B = mrBon();
  if(it.heal){ const h = Math.round(it.heal * (1 + B.healBonus)); dgHeal(h); dgLog(`${it.icon} ${it.name}. +${h} life.`); }
  else dgLog(`${it.icon} ${it.name}.`);
  const e = it.eff || {};
  if(e.turns){ dg.buffs = dg.buffs || []; dg.buffs.push(Object.assign({ name:it.name }, e)); dgLog(`<i>${it.flavor}</i>`); }
  if(e.coins){ dg.inv.coins += e.coins; dgLog(`Tucked inside: ${e.coins} rusty coins.`); }
  if(e.revealMap || e.senseKeys){ dg.D.rooms.forEach(r=>{ r.seen = true; }); dgLog(`The floor lays itself out in your head.`); }
  if(e.cureAll){ dg.hp = dg.maxHp; dgLog(`Everything that hurt stops hurting.`); }
  if(e.noFreeze){ dg.noFreeze = true; }
  saveState(); renderDungeon();
}

/* ================= the run ================= */
let dg = null;                     /* the dungeon you are standing in */
function dgSave(){
  if(!state.dungeon || typeof state.dungeon !== "object") state.dungeon = defaultDungeon();
  const D = state.dungeon, base = defaultDungeon();
  for(const k in base) if(D[k] === undefined || D[k] === null) D[k] = base[k];
  if(typeof D.xp !== "number" || !isFinite(D.xp) || D.xp < 0) D.xp = 0;
  if(typeof D.maxFloor !== "number" || !isFinite(D.maxFloor)) D.maxFloor = 1;
  D.maxFloor = Math.max(1, Math.min(DG_FLOORS.length, Math.floor(D.maxFloor)));
  if(!Array.isArray(D.bound)) D.bound = [];
  if(typeof D.floorsDone !== "object" || !D.floorsDone) D.floorsDone = {};
  if(typeof D.tokens !== "number" || !isFinite(D.tokens)) D.tokens = 0;
  if(typeof D.might !== "number" || !isFinite(D.might) || D.might < 0) D.might = 0;
  if(typeof D.rolls !== "object" || !D.rolls) D.rolls = {};
  if(!D.rolling || typeof D.rolling !== "object" || !D.rolling.done) D.rolling = null;
  if(!DG_SIZES[D.lastSize]) D.lastSize = "small";
  if(!DG_COMPLEXITY[D.lastCx]) D.lastCx = 6;
  return D;
}
function defaultDungeon(){
  return { xp:0, prestige:0, floorsDone:{}, maxFloor:1, bound:[], tokens:0, might:0, rolls:{}, rolling:null,
           runs:0, clears:0, deepest:0, bestXp:0, lastSize:"small", lastCx:6 };
}
function dgLevel(){ return dgLevelFor(dgSave().xp); }

/* ---- what you may carry in ---- */
function dgBoundPool(){
  return [...new Set(cards.filter(c=>c.category === "Raid Gear").map(c=>c.name.split(" — ")[0]))]
    .filter(sub=>cards.some(c=>c.name.split(" — ")[0] === sub && (state.owned[c.id]||0) > 0));
}
function dgBoundActive(){
  const D = dgSave();
  return (D.bound || []).slice(0, dgBindSlots(dgLevel())).filter(b=>dgBoundPool().includes(b));
}
function dgToggleBind(sub){
  const D = dgSave();
  D.bound = D.bound || [];
  const i = D.bound.indexOf(sub);
  if(i >= 0) D.bound.splice(i, 1);
  else {
    if(D.bound.length >= dgBindSlots(dgLevel())){ showToast("No free bind slots — unbind something first."); return; }
    D.bound.push(sub);
  }
  saveState(); renderDungeon();
}
/* bound gear translates into what you walk in holding */
const DG_BIND_EFFECTS = {
  "Rusty Pickaxe":{tool:"pick"}, "Iron Pickaxe":{tool:"pick"}, "Steel Pickaxe":{tool:"pick"},
  "Dwarven Pickaxe":{tool:"pick"}, "The Worldsplitter":{tool:"pick", wep:2},
  "Hand Axe":{tool:"axe"}, "Woodsman's Axe":{tool:"axe"},
  "Lockpick Set":{tool:"lock"}, "Skeleton Key":{tool:"lock"},
  "Crowbar":{tool:"lock"}, "Forge Hammer":{smith:true},
  "Oil Lantern":{light:true}, "Everburn Lantern":{light:true}, "Miner's Helm":{light:true, tool:"pick"},
  "Warm Cloak":{armour:1}, "Drakescale Gloves":{armour:1},
  "Trail Rations":{food:2}, "Second Wind Tonic":{hp:12},
  "Clay Kiln":{smelt:true}, "Blast Furnace":{smelt:true}, "Alchemist's Crucible":{smelt:true},
  "Dragonfire Forge":{smelt:true, wep:1}, "Lucky Rabbit's Foot":{luck:true},
  "Grappling Hook":{tool:"lock"}, "Rope Coil":{tool:"lock"}, "Climbing Kit":{tool:"lock"},
  "Ancient Map Fragment":{map:true}, "The Cartographer's Eye":{map:true},
};

function dgBegin(floor, size, complexity){
  const S = dgSave();
  if(floor > S.maxFloor){ showToast("That floor is still sealed."); return; }
  if(dgLevel() < dgFloorUnlockLevel(floor)){ showToast(`Needs Mythic Raids level ${dgFloorUnlockLevel(floor)}.`); return; }
  const D = dgGenerate(floor, size, complexity);
  const fd = dgFloorDef(floor);
  dg = {
    floor, size, complexity, D,
    pos: D.start, prev: D.start,
    keys: [], inv: { ore:0, bars:0, wood:0, raw:0, food:1, coins:45 },
    tools: {}, gear: { wep:1, style:"melee", arm:0 },
    equip: { weapon:null, head:null, body:null, legs:null, hands:null, feet:null, trinket:null },
    bag: [], buffs: [], baseHp: 78,
    hp: 78, maxHp: 78,
    deaths: 0, log: [], done:false, won:false, boss:null, puzzle:null,
    started: Date.now(), xpEarned:0,
  };
  /* everything you carry in, you chose to bind */
  dgBoundActive().forEach(sub=>{
    const e = DG_BIND_EFFECTS[sub] || {};
    if(e.tool) dg.tools[e.tool] = true;
    if(e.smith) dg.tools.smith = true;
    if(e.smelt) dg.tools.smelt = true;
    if(e.light) dg.tools.light = true;
    if(e.map) dg.tools.map = true;
    if(e.luck) dg.tools.luck = true;
    if(e.wep) dg.gear.wep = Math.max(dg.gear.wep, e.wep);
    if(e.armour) dg.gear.arm += e.armour;
    if(e.food) dg.inv.food += e.food;
    if(e.hp){ dg.maxHp += e.hp; dg.hp += e.hp; }
    dgWear(sub);
  });
  S.runs = (S.runs||0) + 1;
  dgReveal(D.start);
  dgLog(`You step onto <b>floor ${floor}</b> of Daemonheim. The door seals behind you.`);
  mrGive(MR_ITEMS.nov_sword, true);
  dgLog(`The Smuggler presses a novite shortsword and one cooked fish on you. "Start there."`);
  if(!dgBoundActive().length) dgLog(`You carry nothing. That is the point.`);
  else dgLog(`Bound gear: ${dgBoundActive().join(", ")}.`);
  if(dg.tools.map){ D.rooms.forEach(r=>{ r.seen = true; }); dgLog(`🗺️ Your bound chart sketches the whole floor.`); }
  mrRevealForGear();
  saveState(); renderDungeon();
}
/* bound gear takes the same wear as raid gear — it is the same cards */
function dgWear(sub){ if(RD_USES[sub]) rdWear(sub); }

function mrRevealForGear(){
  if(!dg) return;
  const B = mrBon();
  if(B.senseAll) dg.D.rooms.forEach(r=>{ r.seen = true; });
  else if(B.senseKeys) dg.D.rooms.forEach(r=>{ if(r.keys && r.keys.length) r.seen = true; });
}
function dgLog(m){ if(!dg) return; dg.log.unshift(m); if(dg.log.length > 26) dg.log.pop(); }
function dgReveal(i){
  const D = dg.D;
  D.rooms[i].seen = true; D.rooms[i].visited = true;
  D.adj[i].forEach(n=>{ D.rooms[n].seen = true; });
}
function dgHasKey(k){ return dg.keys.some(x=>x.colour === k.colour && x.shape === k.shape); }
function dgDoorTo(n){ return dg.D.doors[dg.D.ekey(dg.pos, n)]; }
function dgCanEnter(n){
  const d = dgDoorTo(n);
  if(!d) return { ok:false, why:"There is no way through." };
  if(d.open) return { ok:true };
  if(d.guardian && !dg.D.rooms[dg.pos].cleared) return { ok:false, why:"A guardian door — clear this room first." };
  if(d.lock && !dgHasKey(d.lock)) return { ok:false, why:`Locked: needs the ${dgKeyName(d.lock)} key.` };
  if(d.skill && !dg.tools[d.skill.id]) return { ok:false, why:`Blocked — you need a ${d.skill.name}. (Force it and it will cost you.)`, force:true };
  return { ok:true };
}
function dgMove(n){
  if(!dg || dg.done || dg.puzzle || dg.boss) return;
  if(!dg.D.adj[dg.pos].includes(n)) return;
  const from = dg.pos;
  const can = dgCanEnter(n);
  if(!can.ok){
    if(can.force){
      if(mrBon().doorGrace){
        dgLog(`💥 You force the way open. Your gear takes it instead of you.`);
      } else {
        const dmg = 8 + Math.floor(Math.random()*8);
        dgLog(`💥 You force the way open with your bare hands. −${dmg} life.`);
        dgHurt(dmg);
        if(dg.done) return;
      }
    } else { showToast(can.why); dgLog(can.why); renderDungeon(); return; }
  }
  /* forcing a door can put you on the floor — if that bounced you back to the
     entrance, the door you were pushing on is no longer in front of you */
  if(dg.pos !== from){ saveState(); renderDungeon(); return; }
  const d = dgDoorTo(n);
  if(!d){ renderDungeon(); return; }
  if(d.lock && !d.open) dgLog(`🗝️ The ${dgKeyName(d.lock)} key turns.`);
  d.open = true;
  dg.prev = dg.pos; dg.pos = n;
  dgReveal(n);
  mrRevealForGear();
  const room = dg.D.rooms[n];
  if(room.keys && room.keys.length){
    room.keys.forEach(k=>{ if(!dgHasKey(k)){ dg.keys.push(k); dgLog(`🔑 You pocket the <b>${dgKeyName(k)}</b> key.`); } });
    room.keys = [];
  }
  if(room.type === "boss" && !dg.boss) dgStartBoss();
  else if(room.type === "puzzle" && room.cleared && !room.solved && DG_COMPLEXITY[dg.complexity].puzzles) dgStartPuzzle(room);
  saveState(); renderDungeon();
}
function dgHurt(n){
  dg.hp = Math.max(0, dg.hp - n);
  if(dg.hp <= 0){
    dg.deaths++;
    if(dg.deaths >= 5){ dgEnd(false, "You are carried out of Daemonheim on a board."); return; }
    dg.hp = Math.round(dg.maxHp * 0.5);
    dg.pos = dg.D.start;
    dgLog(`☠️ <b>You go down.</b> The floor spits you back to the entrance. (death ${dg.deaths} of 5)`);
  }
}
function dgHeal(n){ dg.hp = Math.min(dg.maxHp, dg.hp + n); }


/* ================= what you do in a room ================= */
function dgRoomActions(){
  const r = dg.D.rooms[dg.pos], T = dg.tools, I = dg.inv, o = [];
  const tierCap = dgFloorDef(dg.floor).tier;
  if(!r.cleared && r.mob){
    const m = r.mob;
    o.push({ icon:DG_STYLES[m.style].icon, label:`Fight the ${m.name}`,
      flavor:`${m.hp}/${m.maxHp} life · fights ${DG_STYLES[m.style].name}. Your ${DG_STYLES[dg.gear.style].name} ${dgTriangle(dg.gear.style, m.style) > 1 ? "beats it" : dgTriangle(dg.gear.style, m.style) < 1 ? "is weak to it" : "is even"}.`,
      act:"fight" });
    o.push({ icon:"🏃", label:"Back away", flavor:"It keeps the room. You keep your life.", act:"none" });
    return o;
  }
  switch(r.type){
    case "ore": {
      const t = dgTier(Math.min(r.content.tier, tierCap));
      if(T.pick) o.push({ icon:"⛏️", label:`Mine ${t.ore}`, flavor:`Tier ${t.t} ore · ${r.content.uses} left in the seam.`, act:"mine" });
      else o.push({ icon:"🫳", label:"Claw at the seam", flavor:"No pickaxe. This will hurt and yield little.", act:"mine_bare" });
      break; }
    case "tree": {
      const t = dgTier(Math.min(r.content.tier, tierCap));
      if(T.axe) o.push({ icon:"🪓", label:`Cut ${t.wood}`, flavor:`Tier ${t.t} wood · ${r.content.uses} left standing.`, act:"chop" });
      else o.push({ icon:"🫳", label:"Snap off branches", flavor:"No hatchet. Slow, splintery work.", act:"chop_bare" });
      break; }
    case "fish": {
      const t = dgTier(Math.min(r.content.tier, tierCap));
      o.push({ icon:"🎣", label:`Fish for ${t.fish}`, flavor:`Raw — cook it to heal ${t.heal} · ${r.content.uses} left in the pool.`, act:"fish" });
      break; }
    case "forge":
      if(I.ore > 0) o.push({ icon:"🔥", label:`Smelt ${I.ore} ore into bars`, flavor:"Ore is worthless. Bars are not.", act:"smelt" });
      if(I.bars > 0) o.push({ icon:"⚒️", label:`Forge a tier ${Math.min(tierCap, dg.gear.wep + Math.max(1, Math.floor(I.bars/2)))} weapon`, flavor:"Two bars buys a tier. Bigger tier, bigger swing.", act:"forge" });
      if(I.bars > 0) o.push({ icon:"🛡️", label:"Forge armour (1 bar)", flavor:"Every point of armour takes the edge off every hit.", act:"armour" });
      if(!I.ore && !I.bars) o.push({ icon:"🔥", label:"A cold forge", flavor:"Bring ore.", act:"none", disabled:true });
      break;
    case "fire":
      if(I.raw > 0) o.push({ icon:"🍳", label:`Cook ${I.raw} raw fish`, flavor:"Cooked fish is the only healing down here.", act:"cook" });
      else o.push({ icon:"🔥", label:"A guttering fire", flavor:"Nothing to cook.", act:"none", disabled:true });
      break;
    case "chest":
      if(!r.looted) o.push({ icon:"🧰", label:"Open the chest", flavor:"Rusty coins, maybe better.", act:"chest" });
      break;
    case "start":
      o.push({ icon:"🕴️", label:"Trade with the Smuggler", flavor:`He sells what you should have brought. ${I.coins} rusty coins.`, act:"shop" });
      break;
    case "puzzle":
      if(r.solved) o.push({ icon:"✅", label:"Solved", flavor:"The mechanism rests.", act:"none", disabled:true });
      else o.push({ icon:"🧩", label:"Work the mechanism", flavor:"Something here wants solving.", act:"puzzle" });
      break;
  }
  if(dg.inv.food > 0) o.push({ icon:"🍖", label:`Eat (${dg.inv.food})`, flavor:`Heals ${dgTier(Math.max(1,dgFloorDef(dg.floor).tier)).heal}.`, act:"eat" });
  if(!o.length) o.push({ icon:"🚪", label:"Nothing here", flavor:"Bare stone and old air.", act:"none", disabled:true });
  return o;
}
function dgAct(i){
  if(!dg || dg.done) return;
  const o = dgRoomActions()[i];
  if(!o || o.disabled) return;
  const r = dg.D.rooms[dg.pos], I = dg.inv;
  const tierCap = dgFloorDef(dg.floor).tier;
  switch(o.act){
    case "fight": {
      const m = r.mob;
      const R = mrDamage(m.style);
      const hit = R.dmg;
      m.hp -= hit;
      const B0 = mrBon();
      if(B0.lifesteal) dgHeal(Math.round(hit * B0.lifesteal));
      dgLog(`${DG_STYLES[dg.gear.style].icon} You hit the ${m.name} for ${hit}${R.crit?" — <b>critical!</b>":""}.`);
      if(m.hp <= 0){
        r.cleared = true;
        if(r.type === "puzzle" && !r.solved && DG_COMPLEXITY[dg.complexity].puzzles) setTimeout(()=>{ if(dg && !dg.done) { dgStartPuzzle(r); renderDungeon(); } }, 10);
        const B1 = mrBon();
        const coins = Math.round((6 + Math.floor(Math.random()*10) + dg.floor*2) * (1 + B1.coinFind));
        I.coins += coins;
        dgLog(`💀 The ${m.name} falls. +${coins} rusty coins.`);
        if(Math.random() < 0.3){ I.raw += 1; dgLog(`It was carrying something edible. +1 raw.`); }
        mrOnKill();
      } else {
        const back = mrTakeHit(m.dmg[0] + Math.random()*(m.dmg[1]-m.dmg[0]));
        if(back){ dgLog(`💢 It answers for ${back}.`); dgHurt(back); }
      }
      break; }
    case "mine": { const t = Math.min(r.content.tier, tierCap); const n = 1 + (Math.random() < 0.35 ? 1 : 0) + mrBon().gather;
      I.ore += n; dgLog(`⛏️ ${n} ${dgTier(t).ore} ore.`);
      if(--r.content.uses <= 0){ r.type = "empty"; dgLog(`The seam is worked out.`); } break; }
    case "mine_bare": { I.ore += 1; dgHurt(4); dgLog(`🫳 One lump of ore, and torn hands. −4 life.`);
      if(--r.content.uses <= 0) r.type = "empty"; break; }
    case "chop": { I.wood += 1 + (Math.random()<0.3?1:0) + mrBon().gather; dgLog(`🪓 Timber. Wood: ${I.wood}.`);
      if(--r.content.uses <= 0){ r.type = "empty"; dgLog(`Nothing left worth cutting.`); } break; }
    case "chop_bare": { I.wood += 1; dgHurt(3); dgLog(`🫳 You wrench a branch free. −3 life.`);
      if(--r.content.uses <= 0) r.type = "empty"; break; }
    case "fish": { I.raw += 1 + (Math.random()<0.3?1:0) + mrBon().gather; dgLog(`🎣 ${dgTier(Math.min(r.content.tier,tierCap)).fish}, raw and flapping.`);
      if(--r.content.uses <= 0){ r.type = "empty"; dgLog(`The pool is fished out.`); } break; }
    case "smelt": { const bars = Math.max(1, I.ore + (dg.tools.smelt?1:0)); I.bars += bars; I.ore = 0;
      dgLog(`🔥 ${bars} bar${bars===1?"":"s"} out of the furnace.`); break; }
    case "forge": { const t = Math.min(tierCap, dg.gear.wep + Math.max(1, Math.floor(I.bars/2)));
      if(t <= dg.gear.wep){ dgLog(`You need more bars to better this.`); break; }
      I.bars = Math.max(0, I.bars - (t - dg.gear.wep)*2); dg.gear.wep = t;
      dgLog(`⚒️ You forge a <b>tier ${t} ${dgTier(t).ore}</b> weapon.`); break; }
    case "armour": { I.bars -= 1; dg.gear.arm += 1; dgLog(`🛡️ Armour up to ${dg.gear.arm}.`); break; }
    case "cook": { const t = dgTier(Math.max(1, dgFloorDef(dg.floor).tier));
      I.food += I.raw; dgLog(`🍳 ${I.raw} cooked. Each heals ${t.heal}.`); I.raw = 0; break; }
    case "eat": { const t = dgTier(Math.max(1, dgFloorDef(dg.floor).tier)); I.food--; dgHeal(t.heal);
      dgLog(`🍖 You eat. +${t.heal} life.`); break; }
    case "chest": { r.looted = true;
      const Bc = mrBon();
      const coins = Math.round((25 + Math.floor(Math.random()*40) + dg.floor*6) * (1 + Bc.coinFind));
      I.coins += coins;
      dgLog(`🧰 ${coins} rusty coins.`);
      const it = mrRollItem(dgFloorDef(dg.floor).tier, dg.tools.luck);
      if(it && Math.random() < 0.7) mrGive(it);
      /* the secret larder: only ever in chests, and only sometimes */
      if(Math.random() < 0.3) mrGive(mrRollFood());
      else if(Math.random() < 0.5) I.bars += 2;
      break; }
    case "shop": dg.shop = true; break;
    case "puzzle": dgStartPuzzle(r); break;
  }
  saveState(); renderDungeon();
}
/* ---- damage, with everything you are wearing counted ---- */
function mrDamage(defStyle){
  const B = mrBon(), w = dg.equip.weapon, style = dg.gear.style;
  const base = w ? w.dmg : (5 + dg.gear.wep*5);
  const mult = dgTriangle(style, defStyle);
  const crit = Math.random() < (0.05 + B.crit);
  let d = base * (1 + B.dmg + (B.styleDmg[style]||0)) * mult * (0.8 + Math.random()*0.4);
  if(crit) d *= 1.8;
  return { dmg: Math.max(1, Math.round(d)), crit, mult };
}
function mrTakeHit(raw){
  const B = mrBon();
  if(Math.random() < B.dodge){ dgLog(`💨 You slip the blow entirely.`); return 0; }
  return Math.max(1, Math.round(raw / (1 + (dg.gear.arm + B.arm) * 0.18)));
}
function mrOnKill(bonusTier){
  const B = mrBon();
  if(Math.random() < 0.30 + (B.coinFind ? 0.08 : 0)){
    const it = mrRollItem(bonusTier || dgFloorDef(dg.floor).tier, dg.tools.luck);
    if(it) mrGive(it);
  } else if(Math.random() < 0.10){ mrGive(mrRollFood()); }
}

/* ---- the Smuggler ---- */
const DG_SHOP = [
  { id:"pick",  icon:"⛏️", name:"Pickaxe",    cost:35,  give:d=>{ d.tools.pick = true; }, has:d=>d.tools.pick },
  { id:"axe",   icon:"🪓", name:"Hatchet",    cost:35,  give:d=>{ d.tools.axe = true; },  has:d=>d.tools.axe },
  { id:"lock",  icon:"🗝️", name:"Lockpick",   cost:55,  give:d=>{ d.tools.lock = true; }, has:d=>d.tools.lock },
  { id:"food",  icon:"🍖", name:"Cooked fish ×2", cost:25, give:d=>{ d.inv.food += 2; } },
  { id:"bars",  icon:"🧱", name:"Two bars",   cost:60,  give:d=>{ d.inv.bars += 2; } },
  { id:"arm",   icon:"🛡️", name:"Scrap armour", cost:80, give:d=>{ d.gear.arm += 1; } },
];
function dgBuy(id){
  const it = DG_SHOP.find(x=>x.id === id);
  if(!it || !dg) return;
  if(it.has && it.has(dg)){ showToast("You already have one."); return; }
  const cost = Math.round(it.cost * (1 - mrBon().haggle));
  if(dg.inv.coins < cost){ showToast("Not enough rusty coins."); return; }
  dg.inv.coins -= cost; it.give(dg);
  dgLog(`🕴️ The Smuggler takes ${cost} coins for a ${it.name.toLowerCase()}.`);
  saveState(); renderDungeon();
}
function dgSetStyle(st){ if(dg && DG_STYLES[st]){ dg.gear.style = st; dgLog(`You settle into a ${DG_STYLES[st].name.toLowerCase()} stance.`); renderDungeon(); } }

/* ================= finishing ================= */
function dgEnd(won, msg){
  if(!dg || dg.done) return;
  dg.done = true; dg.won = won;
  const S = dgSave();
  if(won){
    const base = Math.round(180 * Math.pow(dg.floor, 1.42) + 120);
    const sz = DG_SIZES[dg.size].xp, cx = DG_COMPLEXITY[dg.complexity].xp;
    const deathMul = Math.max(0.5, 1 - 0.06*dg.deaths);
    const xp = Math.round(base * sz * cx * deathMul);
    dg.xpEarned = xp;
    S.xp += xp;
    S.floorsDone[dg.floor] = true;
    S.clears = (S.clears||0) + 1;
    S.deepest = Math.max(S.deepest||0, dg.floor);
    S.bestXp = Math.max(S.bestXp||0, xp);
    S.tokens = (S.tokens||0) + Math.round(xp/12);
    if(dg.floor >= S.maxFloor && S.maxFloor < DG_FLOORS.length &&
       dgLevel() >= dgFloorUnlockLevel(S.maxFloor + 1)) S.maxFloor++;
    const credits = Math.round(xp * 3.2);
    state.credits += credits;
    dg.creditsEarned = credits;
    grantBonusXP(Math.min(90, xp/40));
    recomputePlayerXP();
    dgLog(`🏆 <b>Floor ${dg.floor} complete.</b> +${xp.toLocaleString()} Mythic Raids XP, +${credits.toLocaleString()} 🪙`);
    if(Math.random() < 0.35 + dg.floor*0.03){
      const c = arAwardCard(5 + Math.min(6, dg.floor));
      if(c){ dg.cardWon = c; dgLog(`🃏 Daemonheim gives up a card: ${c.emoji} ${c.name}`); }
    }
  } else {
    dgLog(msg || `You leave with nothing. Daemonheim keeps what it is given.`);
  }
  saveState(); renderHeader(); renderDungeon();
}
function dgLeave(){ dg = null; renderDungeon(); }
function dgPrestige(){
  const S = dgSave();
  const done = Object.keys(S.floorsDone).length;
  if(done < S.maxFloor){ showToast("Clear every floor you have unlocked first."); return; }
  S.prestige = (S.prestige||0) + 1;
  S.floorsDone = {};
  showToast(`Prestige ${S.prestige}. Every floor counts as fresh again.`);
  saveState(); renderDungeon();
}


/* ================= puzzle rooms ================= */
const DG_EMOTES = ["👏","💃","🙇","🙌","🤸","🫡"];
function dgStartPuzzle(room){
  const kinds = ["flip","emote","statues","grooves","levers","riddle"];
  const kind = room.puzzleKind || (room.puzzleKind = kinds[Math.floor(Math.random()*kinds.length)]);
  const p = { kind, room: room.i, tries:0, msg:"" };
  if(kind === "flip"){
    /* Lights Out — built by scrambling a solved board, so it always comes apart again */
    p.n = 4; p.grid = Array(16).fill(true);
    const tap = i=>{ const x=i%4, y=(i/4)|0;
      [[0,0],[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{
        const nx=x+dx, ny=y+dy;
        if(nx>=0&&nx<4&&ny>=0&&ny<4) p.grid[ny*4+nx] = !p.grid[ny*4+nx];
      }); };
    for(let k=0;k<5 + Math.floor(Math.random()*3);k++) tap(Math.floor(Math.random()*16));
    if(p.grid.every(v=>v)) tap(Math.floor(Math.random()*16));
  } else if(kind === "emote"){
    p.seq = Array.from({length:4}, ()=>DG_EMOTES[Math.floor(Math.random()*DG_EMOTES.length)]);
    p.given = []; p.showing = true;
  } else if(kind === "statues"){
    const styles = ["melee","ranged","magic"];
    p.facing = styles[Math.floor(Math.random()*3)];
    p.answer = Object.keys(DG_STYLES).find(k=>DG_STYLES[k].beats === p.facing);
  } else if(kind === "grooves"){
    p.rows = [0,1,2].map(()=>({ safe: Math.floor(Math.random()*5), at:-1 }));
    p.row = 0;
    p.hint = p.rows.map(r=>r.safe % 2 === 0 ? "even" : "odd");
  } else if(kind === "levers"){
    const cols = ["gold","crimson","green","blue","purple"];
    p.order = cols.slice().sort(()=>Math.random()-0.5);
    p.pulled = [];
    p.clues = [
      `The ${p.order[0]} lever is first.`,
      `The ${p.order[4]} lever is last.`,
      `${p.order[1]} comes straight after ${p.order[0]}.`,
      `${p.order[3]} comes straight before ${p.order[4]}.`,
    ];
  } else if(kind === "riddle"){
    const opts = [
      { k:"ore",  q:"“Dug, never grown. Heavy, never full. Show me one.”", icon:"🪨" },
      { k:"wood", q:"“It burned before it grew. Show me what the dark trees gave you.”", icon:"🪵" },
      { k:"bars", q:"“Rock that has been persuaded. Show me one.”", icon:"🧱" },
      { k:"food", q:"“It swam, then it sizzled. Show me supper.”", icon:"🍖" },
    ];
    p.want = opts[Math.floor(Math.random()*opts.length)];
  }
  dg.puzzle = p;
  dgLog(`🧩 A mechanism grinds awake.`);
}
function dgPuzzleSolved(){
  const p = dg.puzzle;
  const room = dg.D.rooms[p.room];
  room.solved = true;
  /* a solved puzzle unlocks every door out of this room */
  dg.D.adj[room.i].forEach(n=>{ const d = dg.D.doors[dg.D.ekey(room.i, n)]; if(d) d.open = true; });
  const coins = 30 + dg.floor*5;
  dg.inv.coins += coins;
  dgLog(`✅ <b>Solved.</b> The doors give. +${coins} rusty coins.`);
  dg.puzzle = null;
  saveState(); renderDungeon();
}
function dgPuzzleFail(msg){
  const p = dg.puzzle;
  p.tries++;
  p.msg = msg;
  const grace = mrBon().puzzleGrace;
  dg.graceUsed = dg.graceUsed || 0;
  if(dg.graceUsed < grace){
    dg.graceUsed++;
    dgLog(`❌ ${msg} <i>Your gear covers the mistake.</i>`);
    renderDungeon(); return;
  }
  const dmg = 5 + dg.floor;
  dgLog(`❌ ${msg} −${dmg} life.`);
  dgHurt(dmg);
  renderDungeon();
}
function dgPuzzleAct(a, b){
  const p = dg.puzzle;
  if(!p || dg.done) return;
  if(p.kind === "flip"){
    const i = a, x = i%4, y = (i/4)|0;
    [[0,0],[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{
      const nx=x+dx, ny=y+dy;
      if(nx>=0&&nx<4&&ny>=0&&ny<4) p.grid[ny*4+nx] = !p.grid[ny*4+nx];
    });
    if(p.grid.every(v=>v)) return dgPuzzleSolved();
  } else if(p.kind === "emote"){
    if(p.showing){ p.showing = false; renderDungeon(); return; }
    p.given.push(a);
    if(p.given[p.given.length-1] !== p.seq[p.given.length-1]){
      p.given = []; return dgPuzzleFail("The statues stop mid-gesture. Wrong.");
    }
    if(p.given.length === p.seq.length) return dgPuzzleSolved();
  } else if(p.kind === "statues"){
    if(a === p.answer) return dgPuzzleSolved();
    return dgPuzzleFail("The statue drops the weapon and looks at you.");
  } else if(p.kind === "grooves"){
    const r = p.rows[p.row];
    if(a === r.safe){
      r.at = a; p.row++;
      if(p.row >= p.rows.length) return dgPuzzleSolved();
      p.msg = "Solid. Next row.";
    } else return dgPuzzleFail("The tile drops out from under you.");
  } else if(p.kind === "levers"){
    const want = p.order[p.pulled.length];
    if(a === want){
      p.pulled.push(a);
      if(p.pulled.length === p.order.length) return dgPuzzleSolved();
      p.msg = "A tumbler falls somewhere in the wall.";
    } else { p.pulled = []; return dgPuzzleFail("Gas hisses from the grille. Order reset."); }
  } else if(p.kind === "riddle"){
    if(a === p.want.k){
      if((dg.inv[a]||0) <= 0) return dgPuzzleFail("You do not actually have one of those.");
      dg.inv[a]--; return dgPuzzleSolved();
    }
    return dgPuzzleFail("“No,” says the hoardstalker, delighted.");
  }
  renderDungeon();
}
function dgPuzzleLeave(){ if(dg){ dg.puzzle = null; renderDungeon(); } }

/* ================= bosses ================= */
function dgStartBoss(){
  const def = DG_BOSSES[dgFloorDef(dg.floor).boss];
  const scale = 1 + (dg.floor - 1) * 0.16;
  dg.boss = { def, hp: Math.round(def.hp*scale), maxHp: Math.round(def.hp*scale),
              turn:1, ward:null, frozen:false, invuln:false, corpses:0, sanded:false, quarter:4 };
  if(def === DG_BOSSES.astea) dg.boss.ward = ["melee","ranged","magic"][Math.floor(Math.random()*3)];
  dgLog(`⚔️ <b>${def.icon} ${def.name}.</b> ${def.intro}`);
}
function dgBossActions(){
  const B = dg.boss, k = dgFloorDef(dg.floor).boss, o = [];
  o.push({ icon:DG_STYLES[dg.gear.style].icon, label:`Attack — ${DG_STYLES[dg.gear.style].name}`,
    flavor:`Tier ${dg.gear.wep||0} weapon · ~${Math.round((5 + dg.gear.wep*5) * dgTriangle(dg.gear.style, dg.boss.def.style))} a swing.`, act:"hit" });
  Object.keys(DG_STYLES).filter(st=>st !== dg.gear.style).forEach(st=>{
    o.push({ icon:DG_STYLES[st].icon, label:`Switch to ${DG_STYLES[st].name}`, flavor:"Costs the turn.", act:"style:"+st });
  });
  if(dg.inv.food > 0) o.push({ icon:"🍖", label:`Eat (${dg.inv.food})`, flavor:"Costs the turn.", act:"eat" });
  if(k === "behemoth") o.push({ icon:"🔥", label:"Burn the carcasses", flavor:"Stops it healing for good.", act:"g" });
  if(k === "icefiend") o.push({ icon:"🛡️", label:"Take cover", flavor:"Halves the icicle fall.", act:"g" });
  if(k === "lakhra")   o.push({ icon:"🏜️", label:"Sand the ice", flavor:"Stops you slipping.", act:"g" });
  if(k === "tokash" && B.frozen) o.push({ icon:"💥", label:"Break the ice!", flavor:"Or lose the turn.", act:"g" });
  o.push({ icon:"🏳️", label:"Flee the chamber", flavor:"Back to the floor. The boss recovers.", act:"flee" });
  return o;
}
function dgBossAct(i){
  const B = dg.boss; if(!B || dg.done) return;
  const o = dgBossActions()[i]; if(!o) return;
  const k = dgFloorDef(dg.floor).boss;
  let spentTurn = true;
  if(o.act === "flee"){ dg.boss = null; dg.pos = dg.prev; dgLog("You back out of the boss chamber."); saveState(); renderDungeon(); return; }
  if(o.act.startsWith("style:")){ dg.gear.style = o.act.slice(6); dgLog(`You change stance to ${DG_STYLES[dg.gear.style].name}.`); }
  else if(o.act === "eat"){ const t = dgTier(Math.max(1,dgFloorDef(dg.floor).tier)); dg.inv.food--; dgHeal(t.heal); dgLog(`🍖 +${t.heal} life.`); }
  else if(o.act === "g"){
    if(k === "behemoth"){ B.corpses = -99; dgLog("🔥 The carcasses go up. It will get no more from them."); }
    if(k === "icefiend"){ B.covered = true; dgLog("🛡️ You get under the ledge."); }
    if(k === "lakhra"){ B.sanded = true; dgLog("🏜️ Grit across the glass. Your feet hold."); }
    if(k === "tokash"){ B.frozen = false; dgLog("💥 You smash out of the ice."); spentTurn = false; }
  }
  else if(o.act === "hit"){
    if(B.frozen){ dgLog("🥶 You are frozen solid and cannot swing."); }
    else if(B.invuln){ dgLog("The ice sheath turns your blow completely."); }
    else if(k === "lakhra" && !B.sanded && !mrBon().noSlip && Math.random() < 0.33){ dgLog("🧊 Your feet go and the swing goes wide."); }
    else {
      const Bo = mrBon();
      const R = mrDamage(B.def.style);
      let hit = R.dmg;
      if(k === "astea" && B.ward === dg.gear.style){
        if(Bo.wardPierce) dgLog(`❄️ Frostweaver silks drink her ward. The blow lands anyway.`);
        else { hit = 0; dgLog(`🕸️ She is warding ${DG_STYLES[dg.gear.style].name} — nothing lands.`); }
      }
      if(k === "icybones") hit = Math.round(hit * (dg.gear.style === "melee" ? 2 : 0.5));
      B.hp -= hit;
      if(hit > 0){
        if(Bo.lifesteal) dgHeal(Math.round(hit * Bo.lifesteal));
        dgLog(`${DG_STYLES[dg.gear.style].icon} You land ${hit} on ${B.def.name}${R.crit?" — <b>critical!</b>":""}.`);
      }
      if(B.hp <= 0) return dgBossDown();
    }
  }
  if(spentTurn) dgBossTurn();
  saveState(); renderDungeon();
}
function dgBossTurn(){
  const B = dg.boss, k = dgFloorDef(dg.floor).boss;
  B.turn++;
  if(k === "behemoth" && B.corpses > -99){ B.hp = Math.min(B.maxHp, B.hp + 6); dgLog(`🦬 It drags over a carcass and heals 6.`); }
  if(k === "astea"){ B.ward = ["melee","ranged","magic"][Math.floor(Math.random()*3)];
    dgLog(`🕸️ She shifts her ward to ${DG_STYLES[B.ward].name}.`); }
  if(k === "icefiend"){
    const q = Math.ceil(B.hp / B.maxHp * 4);
    if(q < B.quarter){ B.quarter = q; B.invuln = true;
      const dmg = B.covered ? 6 : 14; dgLog(`🧊 It seals itself and the ceiling comes down. −${dmg} life.`);
      B.covered = false; dgHurt(dmg); if(dg.done) return; }
    else B.invuln = false;
  }
  if(k === "tokash" && B.turn % 3 === 0 && !B.frozen){
    if(dg.noFreeze) dgLog(`🥶 He shouts. The sorbet in you shrugs it off.`);
    else { B.frozen = true; dgLog(`🥶 <b>“DEEP FREEZE!”</b> You are locked in place.`); }
  }
  if(B.invuln) return;
  mrTickBuffs();
  const raw = (B.def.dmg[0] + Math.random()*(B.def.dmg[1]-B.def.dmg[0])) * (1 + (dg.floor-1)*0.07);
  const dmg = mrTakeHit(raw);
  if(dmg){ dgLog(`💢 ${B.def.name} hits you for ${dmg}.`); dgHurt(dmg); }
}
function dgBossDown(){
  const B = dg.boss;
  dgLog(`🏆 <b>${B.def.name} falls.</b>`);
  /* a boss always gives up gear, and often something from the secret larder */
  const drop = mrRollItem(dgFloorDef(dg.floor).tier + 1, true);
  if(drop) mrGive(drop);
  if(Math.random() < 0.6) mrGive(mrRollFood());
  dg.boss = null;
  dgEnd(true);
}


/* ================= the screen ================= */
const DG_ROOM_ICON = { start:"🚪", ore:"⛰️", tree:"🌲", fish:"🎣", forge:"🔥", fire:"🍳",
                       monster:"👹", chest:"🧰", puzzle:"🧩", boss:"💀", empty:"·" };
function dgRenderMap(){
  const D = dg.D, CELL = 44, GAP = 13, P = CELL + GAP;
  let html = `<div class="dg-map" style="width:${D.W*P - GAP}px; height:${D.H*P - GAP}px;">`;
  /* corridors first so rooms sit on top */
  D.edges.forEach(e=>{
    const [a,b] = e.split("|").map(Number);
    const d = D.doors[e];
    const ax = a % D.W, ay = (a / D.W)|0, bx = b % D.W, by = (b / D.W)|0;
    const seen = D.rooms[a].seen && D.rooms[b].seen;
    if(!seen) return;
    const horiz = ay === by;
    const left = horiz ? Math.min(ax,bx)*P + CELL : ax*P + CELL/2 - 4;
    const top  = horiz ? ay*P + CELL/2 - 4 : Math.min(ay,by)*P + CELL;
    let cls = "dg-link";
    let tip = "";
    if(d.lock && !d.open){ cls += " locked"; tip = dgKeyName(d.lock); }
    else if(d.skill && !d.open){ cls += " tool"; tip = d.skill.name; }
    else if(d.guardian && !d.open){ cls += " guard"; }
    const col = (d.lock && !d.open) ? (DG_KEY_COLOURS.find(c=>c.id === d.lock.colour)||{}).hex : null;
    html += `<i class="${cls}" title="${tip}" style="left:${left}px; top:${top}px; ${horiz?`width:${GAP}px;height:8px;`:`width:8px;height:${GAP}px;`}${col?`background:${col};`:""}"></i>`;
  });
  D.rooms.forEach(r=>{
    const x = r.x*P, y = r.y*P;
    const here = r.i === dg.pos;
    const adj = D.adj[dg.pos].includes(r.i);
    let cls = "dg-room";
    if(!r.seen) cls += " unseen";
    if(r.visited) cls += " visited";
    if(here) cls += " here";
    if(adj) cls += " adj";
    if(!r.cleared && r.seen) cls += " hostile";
    const icon = !r.seen ? "" : (here ? "🧍" : (DG_ROOM_ICON[r.type] || "·"));
    const keyPip = (r.seen && r.keys && r.keys.length) ? `<b class="dg-keypip">🔑</b>` : "";
    html += `<button class="${cls}" data-room="${r.i}" style="left:${x}px; top:${y}px; width:${CELL}px; height:${CELL}px;">${icon}${keyPip}</button>`;
  });
  html += `</div>`;
  return html;
}
function dgCardGrid(list, handler){
  return `<div class="rd-dgrid">${list.map((o,i)=>`
    <button class="rd-dcard${o.risk?" risky":""}" data-i="${i}" ${o.disabled?"disabled":""}>
      <span class="di">${o.icon}</span>
      <span class="dl">${o.label}</span>
      ${o.flavor?`<span class="df">${o.flavor}</span>`:""}
    </button>`).join("")}</div>`;
}
function mrGearHtml(){
  const B = mrBon(), counts = mrSetCounts();
  const slots = MR_SLOTS.map(sl=>{
    const it = dg.equip[sl];
    return `<div class="mr-slot${it?" on":""}">
      <span class="ms">${MR_SLOT_NAME[sl]}</span>
      <span class="mi">${it?it.icon:"—"}</span>
      <span class="mn">${it?it.name:"empty"}</span>
    </div>`;
  }).join("");
  const setRows = Object.keys(counts).map(sid=>{
    const set = mrSet(sid), n = counts[sid];
    return `<div class="mr-setrow">
      <b>${set.icon} ${set.name}</b> <em>${n}/5</em>
      <span class="${n>=2?"on":""}">2: ${set.b2t}</span>
      <span class="${n>=3?"on":""}">3: ${set.b3t}</span>
      <span class="${n>=5?"on":""}">5: ${set.b5t}</span>
    </div>`;
  }).join("");
  const bag = (dg.bag||[]).map((it,i)=>`
    <button class="mr-bagit" data-bag="${i}">
      <span class="bi">${it.icon}</span>
      <span class="bn">${it.name}</span>
      <span class="bd">${it.kind==="food"
        ? (it.heal?`heals ${it.heal}`:"effect") + (it.secret?" · secret":"")
        : it.kind==="weapon" ? `${it.dmg} dmg · ${DG_STYLES[it.style].name}`
        : mrSet(it.set) ? mrSet(it.set).name : "trinket"}</span>
      <span class="ba">${it.kind==="food"?"Eat":"Equip"}</span>
    </button>`).join("");
  const bonusBits = [];
  if(B.dmg) bonusBits.push(`+${Math.round(B.dmg*100)}% damage`);
  ["melee","ranged","magic"].forEach(k=>{ if(B.styleDmg[k]) bonusBits.push(`+${Math.round(B.styleDmg[k]*100)}% ${k}`); });
  if(B.arm) bonusBits.push(`+${B.arm} armour`);
  if(B.crit) bonusBits.push(`+${Math.round(B.crit*100)}% crit`);
  if(B.gather) bonusBits.push(`+${B.gather} per node`);
  if(B.dodge) bonusBits.push(`${Math.round(B.dodge*100)}% dodge`);
  if(B.healBonus) bonusBits.push(`+${Math.round(B.healBonus*100)}% healing`);
  if(B.coinFind) bonusBits.push(`+${Math.round(B.coinFind*100)}% coin`);
  if(B.lifesteal) bonusBits.push(`${Math.round(B.lifesteal*100)}% lifesteal`);
  if(B.puzzleGrace) bonusBits.push(`${B.puzzleGrace} free puzzle slips`);
  if(mrMight()) bonusBits.push(`⚒️ +${mrMight()}% forged`);
  if(B.doorGrace) bonusBits.push(`force doors unharmed`);
  if(B.senseAll) bonusBits.push(`whole floor mapped`);
  else if(B.senseKeys) bonusBits.push(`keys sensed`);
  if(B.wardPierce) bonusBits.push(`pierces wards`);
  if(B.noSlip) bonusBits.push(`sure-footed`);
  if(B.haggle) bonusBits.push(`${Math.round(B.haggle*100)}% off the Smuggler`);
  const buffs = (dg.buffs||[]).map(b=>`<span class="mr-buff">${b.name} · ${b.turns}</span>`).join("");
  return `<div class="mr-gear">
    <div class="mr-slots">${slots}</div>
    ${bonusBits.length?`<div class="mr-bonus">${bonusBits.map(b=>`<span>${b}</span>`).join("")}</div>`:""}
    ${buffs?`<div class="mr-bonus">${buffs}</div>`:""}
    ${setRows?`<div class="mr-sets">${setRows}</div>`:""}
    <div class="mr-bagtitle">Pack ${(dg.bag||[]).length ? "" : "— empty"}</div>
    ${bag?`<div class="mr-bag">${bag}</div>`:""}
    <button class="btn secondary" style="margin-top:10px;" onclick="dg.gearOpen=false; renderDungeon();">Close</button>
  </div>`;
}
function dgHud(){
  const hpPct = Math.max(0, dg.hp/dg.maxHp*100);
  const I = dg.inv;
  return `<div class="dg-hud">
    <div class="dg-hp"><i style="width:${hpPct}%; background:${hpPct>50?"#3ddc84":hpPct>25?"#ffd35c":"#ff5c5c"}"></i><span>❤️ ${Math.round(dg.hp)} / ${dg.maxHp}</span></div>
    <button class="chip mr-gearbtn" onclick="dg.gearOpen=!dg.gearOpen; renderDungeon();">🎒 Gear${(dg.bag||[]).length?` · ${dg.bag.length}`:""}</button>
    <div class="chip">${dg.equip.weapon?dg.equip.weapon.icon:DG_STYLES[dg.gear.style].icon} ${dg.equip.weapon?dg.equip.weapon.dmg:5+dg.gear.wep*5}</div>
    <div class="chip">🛡️ ${dg.gear.arm + mrBon().arm}</div>
    <div class="chip">🪙 ${I.coins}</div>
    ${I.ore?`<div class="chip">⛰️ ${I.ore}</div>`:""}
    ${I.bars?`<div class="chip">🧱 ${I.bars}</div>`:""}
    ${I.wood?`<div class="chip">🪵 ${I.wood}</div>`:""}
    ${I.raw?`<div class="chip">🐟 ${I.raw}</div>`:""}
    ${I.food?`<div class="chip">🍖 ${I.food}</div>`:""}
    ${dg.keys.map(k=>`<div class="chip dg-key" style="border-color:${(DG_KEY_COLOURS.find(c=>c.id===k.colour)||{}).hex}">${DG_SHAPE_GLYPH[k.shape]||"🔑"} ${k.colour}</div>`).join("")}
  </div>`;
}
function dgPuzzleHtml(){
  const p = dg.puzzle;
  let body = "", title = "", blurb = "";
  if(p.kind === "flip"){
    title = "Flip Tiles"; blurb = "Light every tile. Touching one flips it and its neighbours.";
    body = `<div class="dg-flip">${p.grid.map((v,i)=>`<button data-p="${i}" class="${v?"on":""}"></button>`).join("")}</div>`;
  } else if(p.kind === "emote"){
    title = "Follow the Leader";
    if(p.showing){ blurb = "The statues perform. Watch, then repeat.";
      body = `<div class="dg-seq">${p.seq.map(e=>`<span>${e}</span>`).join("")}</div>
              <button class="btn" data-p="go">I have it</button>`;
    } else { blurb = `Repeat the sequence. ${p.given.length} of ${p.seq.length}.`;
      body = `<div class="dg-seq small">${p.seq.map((e,i)=>`<span>${i<p.given.length?p.given[i]:"❔"}</span>`).join("")}</div>
              <div class="dg-emotes">${DG_EMOTES.map(e=>`<button data-p="${e}">${e}</button>`).join("")}</div>`; }
  } else if(p.kind === "statues"){
    title = "Three Statues"; blurb = `The armed statue faces you holding <b>${DG_STYLES[p.facing].icon} ${DG_STYLES[p.facing].name}</b>. Arm the empty one with what beats it.`;
    body = `<div class="dg-emotes">${Object.keys(DG_STYLES).map(k=>`<button data-p="${k}">${DG_STYLES[k].icon}<em>${DG_STYLES[k].name}</em></button>`).join("")}</div>`;
  } else if(p.kind === "grooves"){
    title = "Suspicious Grooves"; blurb = `Row ${p.row+1} of 3. The safe tile is in an <b>${p.hint[p.row]}</b> position.`;
    body = `<div class="dg-rows">${p.rows.map((r,ri)=>`<div class="dg-row${ri===p.row?" active":""}">${
      [0,1,2,3,4].map(i=>`<button data-p="${i}" ${ri!==p.row?"disabled":""} class="${r.at===i?"safe":""}">${ri<p.row?(r.at===i?"✔":"·"):(ri===p.row?i+1:"·")}</button>`).join("")}</div>`).join("")}</div>`;
  } else if(p.kind === "levers"){
    title = "The Levers"; blurb = "Pull them in the right order before the gas. The wall is scratched with hints.";
    body = `<div class="dg-clues">${p.clues.map(c=>`<div>• ${c}</div>`).join("")}</div>
      <div class="dg-emotes">${["gold","crimson","green","blue","purple"].map(c=>{
        const done = p.pulled.includes(c);
        const hex = (DG_KEY_COLOURS.find(k=>k.id===c)||{}).hex;
        return `<button data-p="${c}" ${done?"disabled":""} style="border-color:${hex}; color:${hex}">${done?"✔":"⇩"}<em>${c}</em></button>`;
      }).join("")}</div>`;
  } else if(p.kind === "riddle"){
    title = "The Enigmatic Hoardstalker"; blurb = p.want.q;
    body = `<div class="dg-emotes">${[["ore","🪨","ore"],["wood","🪵","wood"],["bars","🧱","bar"],["food","🍖","food"]].map(([k,ic,nm])=>
      `<button data-p="${k}">${ic}<em>${nm} (${dg.inv[k]||0})</em></button>`).join("")}</div>`;
  }
  return `<div class="dg-puzzle">
    <div class="dg-ptitle">🧩 ${title}</div>
    <div class="dg-pblurb">${blurb}</div>
    ${p.msg?`<div class="dg-pmsg">${p.msg}</div>`:""}
    ${body}
    <button class="btn secondary" style="margin-top:12px;" onclick="dgPuzzleLeave()">Step away from it</button>
  </div>`;
}
function dgBossHtml(){
  const B = dg.boss;
  const pct = Math.max(0, B.hp/B.maxHp*100);
  return `<div class="dg-boss">
    <div class="dg-bicon">${B.def.icon}</div>
    <div class="dg-bname">${B.def.name}</div>
    <div class="dg-bhp"><i style="width:${pct}%"></i><span>${Math.max(0,Math.round(B.hp))} / ${B.maxHp}</span></div>
    <div class="dg-bgim">${B.def.gimmick}</div>
    ${B.ward?`<div class="dg-bward">🕸️ Warding <b>${DG_STYLES[B.ward].name}</b> this turn</div>`:""}
    ${B.frozen?`<div class="dg-bward" style="color:#8fd3ff">🥶 You are frozen — break out</div>`:""}
    ${B.invuln?`<div class="dg-bward" style="color:#8fd3ff">🧊 Sealed in ice — nothing lands</div>`:""}
  </div>` + dgCardGrid(dgBossActions());
}
function dgShopHtml(){
  return `<div class="dg-shop">
    <div class="dg-ptitle">🕴️ The Smuggler</div>
    <div class="dg-pblurb">“Everything you should have brought, at a price you will resent.” You have <b>${dg.inv.coins}</b> rusty coins.</div>
    <div class="rd-dgrid">${DG_SHOP.map(it=>{
      const owned = it.has && it.has(dg);
      const cost = Math.round(it.cost * (1 - mrBon().haggle));
      const poor = dg.inv.coins < cost;
      return `<button class="rd-dcard" data-buy="${it.id}" ${owned||poor?"disabled":""}>
        <span class="di">${it.icon}</span><span class="dl">${it.name}</span>
        <span class="df">${owned?"Already carried":`${cost} rusty coins${cost<it.cost?" (haggled)":""}`}</span></button>`;
    }).join("")}</div>
    <button class="btn secondary" style="margin-top:12px;" onclick="dg.shop=false; renderDungeon();">Done</button>
  </div>`;
}
function dgLobbyHtml(){
  const S = dgSave(), lvl = dgLevel(), prog = dgXpToNext(S.xp);
  const slots = dgBindSlots(lvl), pool = dgBoundPool(), bound = dgBoundActive();
  const floors = DG_FLOORS.map(f=>{
    const need = dgFloorUnlockLevel(f.f);
    const locked = f.f > S.maxFloor || lvl < need;
    const done = !!S.floorsDone[f.f];
    const boss = DG_BOSSES[f.boss];
    return `<button class="dg-floor${locked?" locked":""}${done?" done":""}" data-floor="${f.f}" ${locked?"disabled":""}>
      <span class="fn">Floor ${f.f}</span>
      <span class="fb">${boss.icon} ${boss.name}</span>
      <span class="ft">Tier ${f.tier} · ${locked?`needs level ${need}`:done?"cleared":"unexplored"}</span>
    </button>`;
  }).join("");
  return `
  <div class="dg-lvl">
    <div class="dg-lvlnum">${lvl}</div>
    <div class="dg-lvlbody">
      <div class="dg-lvlname">Mythic Raids${S.prestige?` · Prestige ${S.prestige}`:""}</div>
      <div class="progress"><div style="width:${Math.round(prog.pct*100)}%"></div></div>
      <div class="dg-lvlxp">${S.xp.toLocaleString()} xp${lvl<99?` · ${(prog.need-prog.have).toLocaleString()} to ${lvl+1}`:""} · 🎟️ ${(S.tokens||0).toLocaleString()} tokens${mrMight()?` · ⚒️ <b style="color:#ff9d6e">+${mrMight()}% damage</b>`:""}</div>
    </div>
  </div>

  <div class="ui-help" data-help="What Mythic Raids is">
    <p style="color:var(--muted); margin:0; line-height:1.55;">Daemonheim does not care what you own. You go in with nothing but the gear you have
    <b>bound</b>, and everything else — the pickaxe, the bars, the food, the weapon you kill the boss with — is mined, smelted, cooked or taken off a corpse
    <i>inside that floor</i>, and left behind when you leave. Find the keys, open the way, kill what is at the bottom.</p>
  </div>

  <div class="panel">
    <div class="dg-sec">🔗 Bound gear <span>${bound.length} / ${slots} slots</span></div>
    <div class="dg-bindnote">Raid Gear you own can be bound. Bound tools are the only thing that comes in with you — and they take wear like any other run.
    More slots at level 20, 40, 60, 80.</div>
    ${pool.length ? `<div class="dg-binds">${pool.map(sub=>{
      const on = bound.includes(sub);
      const e = DG_BIND_EFFECTS[sub] || {};
      const what = e.tool==="pick"?"pickaxe":e.tool==="axe"?"hatchet":e.tool==="lock"?"lockpick":
        e.smelt?"smelting":e.smith?"smithing":e.light?"light":e.map?"maps the floor":e.food?"food":e.hp?"+life":e.armour?"+armour":"trinket";
      return `<button class="dg-bind${on?" on":""}" data-bind="${sub}"><b>${sub}</b><em>${what}</em></button>`;
    }).join("")}</div>` : `<div class="dg-bindnote" style="color:#ff9d6e;">You own no Raid Gear yet — buy a <b>Raid Supplies</b> pack. You can still dive with nothing.</div>`}
  </div>

  <div class="panel">
    <div class="dg-sec">⚒️ The Mythic Forge <span>${mrMight() ? `+${mrMight()}% damage, permanently` : "no rites yet"}</span></div>
    <div class="dg-bindnote">Credits buy a rite. Every rite is a <b>roll</b> — you know the band, never the number — and whatever it lands on is
    welded to your damage on every floor, forever. Rites stack, and you may take the same one as many times as you can pay for it.</div>
    ${S.rolling ? `<div class="mr-rolling${S.rolling.done ? " done" : ""}">
        <div class="rr-icon">${(MR_ROLLS.find(r=>r.id===S.rolling.id)||{}).icon || "⚒️"}</div>
        <div class="rr-num">+${S.rolling.shown}%</div>
        <div class="rr-lab">${S.rolling.done ? "welded on" : "the forge is deciding…"}</div>
      </div>` : ""}
    <div class="mr-rolls">${MR_ROLLS.map(r=>{
      const n = mrRollCount(r.id);
      const afford = state.credits >= r.cost;
      return `<button class="mr-roll${afford?"":" poor"}" data-roll="${r.id}" ${afford && !S.rolling ? "" : "disabled"}>
        <span class="ri">${r.icon}</span>
        <span class="rn">${r.name}</span>
        <span class="rb">+${r.min}–${r.max}% damage</span>
        <span class="rf">${r.blurb}</span>
        <span class="rfoot"><b>${fmtBig(r.cost)} 🪙</b>${n?`<em>taken ×${n}</em>`:""}</span>
      </button>`;
    }).join("")}</div>
  </div>

  <div class="panel">
    <div class="dg-sec">🗺️ Choose a floor</div>
    <div class="dg-opts">
      <div class="dg-optrow"><span>Size</span>${Object.keys(DG_SIZES).map(k=>
        `<button class="dg-opt${S.lastSize===k?" on":""}" data-size="${k}">${DG_SIZES[k].name}<em>${DG_SIZES[k].label} · ×${DG_SIZES[k].xp}</em></button>`).join("")}</div>
      <div class="dg-optrow"><span>Complexity</span>${Object.keys(DG_COMPLEXITY).map(k=>
        `<button class="dg-opt${String(S.lastCx)===k?" on":""}" data-cx="${k}">${k}<em>${DG_COMPLEXITY[k].name} · ×${DG_COMPLEXITY[k].xp}</em></button>`).join("")}</div>
      <div class="dg-cxblurb">${DG_COMPLEXITY[S.lastCx].blurb}</div>
    </div>
    <div class="dg-floors">${floors}</div>
    ${Object.keys(S.floorsDone).length >= S.maxFloor && S.maxFloor > 1
      ? `<button class="btn" style="margin-top:12px;" onclick="dgPrestige()">⭐ Prestige — reset your cleared floors</button>` : ""}
  </div>`;
}
function dgResultHtml(){
  const S = dgSave();
  return `<div class="dg-result ${dg.won?"good":"bad"}">
    <div class="ri">${dg.won?"🏆":"☠️"}</div>
    <div class="rt">${dg.won?`Floor ${dg.floor} complete`:"Dragged out of Daemonheim"}</div>
    ${dg.won?`<div class="rs">+${dg.xpEarned.toLocaleString()} Mythic Raids xp · +${(dg.creditsEarned||0).toLocaleString()} 🪙 · ${dg.deaths} death${dg.deaths===1?"":"s"}</div>`
            :`<div class="rs">Five deaths is where Daemonheim draws the line.</div>`}
    ${dg.cardWon?`<div class="rs" style="color:#ffd35c">🃏 ${dg.cardWon.emoji} ${dg.cardWon.name}</div>`:""}
    <div class="rs" style="color:var(--muted)">Mythic Raids ${dgLevel()} · ${S.xp.toLocaleString()} xp</div>
    <button class="btn" onclick="dgLeave()">Back to the surface</button>
  </div>`;
}
function renderDungeon(){
  const host = document.getElementById("dgBody");
  if(!host) return;
  if(!dg){ host.innerHTML = dgLobbyHtml(); dgBindLobby(host); uiInitHelp(); return; }
  if(dg.done){ host.innerHTML = dgResultHtml(); return; }
  const r = dg.D.rooms[dg.pos];
  let mid;
  if(dg.gearOpen) mid = mrGearHtml();
  else if(dg.shop) mid = dgShopHtml();
  else if(dg.boss) mid = dgBossHtml();
  else if(dg.puzzle) mid = dgPuzzleHtml();
  else {
    const acts = dgRoomActions();
    mid = `<div class="dg-roomhead"><span class="ri">${DG_ROOM_ICON[r.type]||"·"}</span>
        <div><div class="rn">${({start:"The Entrance",ore:"Ore Seam",tree:"Dead Grove",fish:"Black Pool",forge:"The Forge",fire:"A Fire",monster:"Occupied",chest:"An Old Chest",puzzle:"Mechanism Room",boss:"The Boss Chamber",empty:"Bare Room"})[r.type]||"Room"}</div>
        <div class="rd">${dg.D.path.includes(dg.pos)?"On the way down.":"Off the main route."}</div></div></div>`
      + dgCardGrid(acts);
  }
  host.innerHTML = `
    ${dgHud()}
    <div class="dg-maprow">${dgRenderMap()}</div>
    <div class="dg-mapnote">Tap a lit room to move. 🔑 marks a key. Coloured bars are locked doors.</div>
    ${mid}
    <div class="dg-log">${dg.log.map(l=>`<div>${l}</div>`).join("")}</div>
    <button class="btn secondary" style="margin-top:10px;" onclick="dgEnd(false)">🏳️ Abandon the floor</button>`;
  host.querySelectorAll("[data-room]").forEach(b=>b.addEventListener("click", ()=>dgMove(+b.dataset.room)));
  host.querySelectorAll("[data-bag]").forEach(b=>b.addEventListener("click", ()=>{
    const i = +b.dataset.bag, it = dg.bag[i];
    if(!it) return;
    if(it.kind === "food") mrEatItem(i); else { mrEquip(i); saveState(); renderDungeon(); }
  }));
  if(dg.gearOpen){ /* gear screen owns the taps */ }
  else if(dg.boss) host.querySelectorAll(".rd-dcard[data-i]").forEach(b=>b.addEventListener("click", ()=>dgBossAct(+b.dataset.i)));
  else if(dg.shop) host.querySelectorAll("[data-buy]").forEach(b=>b.addEventListener("click", ()=>dgBuy(b.dataset.buy)));
  else if(dg.puzzle) host.querySelectorAll("[data-p]").forEach(b=>b.addEventListener("click", ()=>{
    const v = b.dataset.p; dgPuzzleAct(/^\d+$/.test(v) ? +v : v);
  }));
  else host.querySelectorAll(".rd-dcard[data-i]").forEach(b=>b.addEventListener("click", ()=>dgAct(+b.dataset.i)));
}
function dgBindLobby(host){
  const S = dgSave();
  host.querySelectorAll("[data-bind]").forEach(b=>b.addEventListener("click", ()=>dgToggleBind(b.dataset.bind)));
  host.querySelectorAll("[data-roll]").forEach(b=>b.addEventListener("click", ()=>mrBuyRoll(b.dataset.roll)));
  host.querySelectorAll("[data-size]").forEach(b=>b.addEventListener("click", ()=>{ S.lastSize = b.dataset.size; saveState(); renderDungeon(); }));
  host.querySelectorAll("[data-cx]").forEach(b=>b.addEventListener("click", ()=>{ S.lastCx = +b.dataset.cx; saveState(); renderDungeon(); }));
  host.querySelectorAll("[data-floor]").forEach(b=>b.addEventListener("click", ()=>dgBegin(+b.dataset.floor, S.lastSize, S.lastCx)));
}
function dgOnEnterTab(){ renderDungeon(); }

/* ---------------- Chrome helpers: stat strips + help blocks ----------------
   Both work by enhancing markup already on the page, so every tab gets the same
   shape without each render function having to know about it. */
function uiPrefs(){
  if(!state.settings) state.settings = defaultSettings();
  if(!state.settings.uiOpen) state.settings.uiOpen = {};
  return state.settings.uiOpen;
}
function uiStripKey(el){
  const sec = el.closest("section");
  const idx = sec ? [...sec.querySelectorAll(".stats-bar")].indexOf(el) : 0;
  return (sec ? sec.id : "x") + ":" + Math.max(0, idx);
}
function uiStripSummary(bar){
  const stats = [...bar.querySelectorAll(".stat")];
  if(!stats.length) return `<span class="sb-empty">Stats</span>`;
  return stats.slice(0, 4).map(st=>{
    const num = (st.querySelector(".num") || {}).textContent || "";
    const lbl = (st.querySelector(".lbl") || {}).textContent || "";
    return `<b>${num.trim()}</b><span>${lbl.trim()}</span>`;
  }).join(`<i class="sep">·</i>`);
}
function uiRefreshStrip(bar){
  const wrap = bar.closest(".sb");
  if(!wrap) return;
  const sum = wrap.querySelector(".sb-sum");
  if(sum) sum.innerHTML = uiStripSummary(bar);
}
function uiInitStatStrips(){
  document.querySelectorAll(".stats-bar").forEach(bar=>{
    if(bar.closest(".sb")){ uiRefreshStrip(bar); return; }
    const key = uiStripKey(bar);
    const wrap = document.createElement("div");
    wrap.className = "sb";
    if(uiPrefs()[key]) wrap.classList.add("open");
    const head = document.createElement("button");
    head.type = "button"; head.className = "sb-head";
    head.innerHTML = `<span class="sb-sum"></span><span class="sb-caret">▾</span>`;
    const body = document.createElement("div");
    body.className = "sb-body";
    bar.parentNode.insertBefore(wrap, bar);
    wrap.appendChild(head); wrap.appendChild(body); body.appendChild(bar);
    head.addEventListener("click", ()=>{
      wrap.classList.toggle("open");
      uiPrefs()[key] = wrap.classList.contains("open");
      saveState();
    });
    try{
      new MutationObserver(()=>uiRefreshStrip(bar))
        .observe(bar, { childList:true, subtree:true, characterData:true });
    }catch(e){}
    uiRefreshStrip(bar);
  });
}
function uiInitHelp(){
  document.querySelectorAll(".ui-help, .ui-fold").forEach(el=>{
    if(el.closest(".uh")) return;
    const fold = el.classList.contains("ui-fold");
    const sec = el.closest("section");
    const key = (fold ? "fold:" : "help:") + (sec ? sec.id : "x") + ":" +
      (sec ? [...sec.querySelectorAll(".ui-help, .ui-fold")].indexOf(el) : 0);
    const wrap = document.createElement("div");
    wrap.className = fold ? "uh uh-fold" : "uh";
    const pref = uiPrefs()[key];
    const startOpen = (pref === undefined) ? (fold && el.dataset.open === "1") : !!pref;
    if(startOpen) wrap.classList.add("open");
    const head = document.createElement("button");
    head.type = "button"; head.className = "uh-head";
    head.innerHTML = fold
      ? `<span class="t">${el.dataset.help || "Section"}</span><span class="uh-caret">▾</span>`
      : `<span class="q">?</span><span class="t">${el.dataset.help || "How it works"}</span><span class="uh-caret">▾</span>`;
    const body = document.createElement("div");
    body.className = "uh-body";
    el.parentNode.insertBefore(wrap, el);
    wrap.appendChild(head); wrap.appendChild(body); body.appendChild(el);
    head.addEventListener("click", ()=>{
      wrap.classList.toggle("open");
      uiPrefs()[key] = wrap.classList.contains("open");
      saveState();
    });
  });
}

/* ---------------- Routing: six nav tabs, one Play hub ---------------- */

/* ===================== ADDED MODES ===================== */

